#!/usr/bin/env node
/**
 * Nish test runner.
 *
 *  A. Golden cases in tests/cases/  (one .ts per case, discovered automatically)
 *       <name>.ts    source
 *       <name>.ll    expected IR (module header stripped). Missing + UPDATE_GOLDENS=1 -> written.
 *       <name>.args  extra CLI flags, whitespace separated
 *       <name>.err   expected error substring; compile must fail (no .ll needed)
 *       <name>.out   expected stdout when linked with <name>.c (or tests/driver.c,
 *                    which prints `test()`) and the two runtime .c files, then run
 *       <name>.argv  command-line arguments for that run, whitespace separated (WP7)
 *       <name>.env   environment for that run, `NAME=value` per line, layered over
 *                    the inherited one (WP19 R1: `getenv` has no other way to be pinned)
 *       <name>.portability  the `--warn-portability --json` portability objects, one
 *                    per line (WP33: the case is compiled a second time with the flag)
 *       <name>.caps.json  the `--emit-capabilities` report, byte for byte (WP35: the
 *                    case is compiled a second time with the flag)
 *     Every successfully compiled case is also assembled with llvm-as.
 *     Every case is compiled by stage1 -- `src/` built by the seed into
 *     `build/nish-test` once per run -- then compared, assembled, linked and
 *     run, `defaultJobs()` cases at a time (tests/pool.js) and reported in
 *     corpus order; the native programs alone take turns, because they share
 *     the files they write. The link is against the runtime and the driver as
 *     object files, built once per run (`runtimeObjects`) rather than
 *     recompiled per case; the `runtime objects:` checks at the end of the run
 *     are what say that is the same link.
 *
 *  B. Pipeline checks: the runtime unit test, inline allocator vs C arena layout
 *     (linked for the host, and asserted per target so wasm32 cannot drift),
 *     size and wasm build profiles, Node wasm host, and the browser harness in
 *     web/ compiling with the compiler's own wasi build.
 */
import { execFileSync, spawn, spawnSync } from "node:child_process"
import crypto from "node:crypto"
import fs from "node:fs"
import https from "node:https"
import dgram from "node:dgram"
import net from "node:net"
import os from "node:os"
import path from "node:path"
import { pathToFileURL } from "node:url"
import { createRequire } from "node:module"
import { BAND_EDGE, judge as judgeTwinRun, readAcross, sideOf } from "../bench/par-reading.mjs"
import { parseCodesRegistry } from "../scripts/codes-registry.js"
import {
  budgetLabel,
  HTTP1_SERVER_START_BYTES,
  HTTP1_TLS_SERVER_START_BYTES,
  HTTP2_TLS_SERVER_START_BYTES,
  HTTP3_SERVER_START_BYTES,
  HTTP3_SERVER_SLOT_BYTES,
  RUNTIME_BUDGETS,
  TLS_TCP_START_BYTES,
} from "./runtime-budgets.js"
import { linkWith, resolveSeed, seedForOracle, spawnSeed, withoutSeed } from "./self/seed.js"
import { defaultJobs, pool, run as spawnAsync } from "./pool.js"
import { standsAlone, typeCheckDeclarations, typeCheckProject } from "./typecheck.js"
import { programs as corpusPrograms } from "./self/corpus.js"
import { cwdFor } from "./differential/lib.js"
import { selfCheckDeclarations as fuzzDeclarations } from "./differential/fuzz.js"
import { CT_TARGETS, ctSpecs, ctViolations, functionBody } from "./ct-asm.js"
import { urlFuzzVerdict } from "./link/std_url/verdict.js"
import { ctAtLevel, ctTargetName, runtimeChecks } from "./ct-asm-runtime.js"
import { panicOracle } from "./panics-oracle.js"
import { runWipeChecks } from "./wipes/index.js"
import { runFfiBufferChecks } from "./ffi-buffer.js"
import { runFfiStringChecks } from "./ffi-string.js"
import {
  packageRootOf,
  selfCheckNotes,
  selfCheckRoots,
  selfCheckVersions,
  withoutOwnRoot,
} from "./nish-cmp.js"
import { rewrite as arrowify } from "../scripts/arrowify.mjs"
import {
  copyInto,
  diagnosticWords,
  diffEmitted,
  presentInTree,
  sitsOnChange,
  verdict,
} from "../scripts/arrow-verify.mjs"
import {
  DEFAULT_ROUNDS,
  canonical as jsonCompareCanonical,
  roundOrder,
  roundsFor,
} from "../bench/json-compare/rounds.mjs"
const require = createRequire(import.meta.url)

const root = path.resolve(import.meta.dirname, "..")
/**
 * The compiler under test: stage1, `src/` linked by the seed once per run,
 * and every compile in this file is a spawn of it.
 *
 * Where it lives is part of what it is. `src/compile.ts` finds its package
 * root -- `scripts/build.sh` for `--link`, `std/` for a `nish/<module>` import
 * -- by climbing one directory from its own `argv[0]` (`packageRoot`), so the
 * binary has to sit one level below the repository root. Under `build/test/`
 * it would find no package and fall back to the working directory, which the
 * checks that run it from inside a fixture's tree would then be testing
 * instead of the compiler.
 */
const NISH = path.join(root, "build", "nish-test")
const casesDir = path.join(root, "tests", "cases")
const buildDir = path.join(root, "build", "test")
fs.mkdirSync(buildDir, { recursive: true })
// Every `--link` and `nish run` keeps the compiled runtime in a cache
// (`$XDG_CACHE_HOME/nish/runtime`), so the suite has one of its own, emptied
// each run: an entry the developer's own builds left would otherwise decide
// what an unrelated check links, and that check would never take the miss.
// A check that needs a cold cache, or no cache at all, still sets its own.
const suiteCache = path.join(buildDir, "xdg-cache")
fs.rmSync(suiteCache, { recursive: true, force: true })
process.env.XDG_CACHE_HOME = suiteCache

/**
 * The C runtime's translation units, as a direct `clang` line has to spell
 * them: `runtime.c` is the core every program touches, `runtime-os.c` wraps the
 * system calls, `runtime-parallel.c` divides work across threads,
 * `runtime-cross.c` copies the strings and arrays that cross between them,
 * `runtime-host.c` holds the wall clock, entropy, file times and signals,
 * `runtime-net.c` the sockets of `nish:net`, `runtime-simd.c` the byte
 * searches that read a vector at a time and `runtime-aes.c` AES-GCM on the
 * CPU's AES instructions, split apart so that each carries its own `.text*`
 * budget (the `*_TEXT_BUDGET` constants in tests/runtime-budgets.js). `scripts/build.sh` pairs every one
 * of them with `runtime.c`, and its `--runtime-from` link needs an object for each,
 * which is why `nish run`'s runtime cache (src/run-cache.ts) lists the same eight:
 * the two lists move together, as `runtime-aes.c` joined both with the compiler's
 * first call into it (WP38 S5).
 *
 * Named here rather than written out at each link so that a third unit is one
 * edit, and spelled out at all -- `scripts/build.sh` pairs the two itself, so
 * the builds that go through it need only name `runtime.c` -- because a link
 * line this suite gets wrong should fail as a link error rather than be quietly
 * repaired on the way past.
 */
const RUNTIME_C = [
  "runtime/runtime.c",
  "runtime/runtime-os.c",
  "runtime/runtime-parallel.c",
  "runtime/runtime-cross.c",
  "runtime/runtime-host.c",
  "runtime/runtime-net.c",
  "runtime/runtime-simd.c",
  "runtime/runtime-aes.c",
]

/** The driver every case without its own `.c` and without an `export main` is linked with. */
const DRIVER_C = path.join(root, "tests", "driver.c")

/**
 * The C a case is linked against -- `runtime.c`, `runtime-os.c` and the shared
 * driver -- compiled to object files once per run instead of once per case.
 *
 * The measurement, on a four-core Linux box: naming the three sources in a
 * case's link costs 470 ms, linking the same module against prebuilt objects
 * costs 91 ms, and building the objects costs 362 ms once. Over the 183 cases
 * that carry a `.out` that is the difference between 86 s of clang and 17 s.
 *
 * **`defines` is the cache key, and it is the whole of what can make one case
 * need a differently built runtime.** Today that is `-DNISH_THREADS=1` alone,
 * which moves `nish_arena` into thread-local storage. A wrong-but-fast link
 * would be worse than a slow one, so the key is checked rather than trusted,
 * in the two `runtime objects:` checks after section A: one relinks a case from
 * the sources and requires the same bytes out, and one requires a `--threads`
 * module linked against the *default* objects to **fail**. It does — `ld`
 * refuses a TLS reference against a non-TLS definition — so a case handed the
 * wrong objects is a red line rather than a program with two arenas.
 *
 * Nothing here survives a run. The objects are built on their first use in each
 * process, so a `runtime.c` edited between runs can never be linked against the
 * object a previous run left behind.
 */
const runtimeObjectCache = new Map()
const runtimeObjects = (defines) => {
  const key = defines.join(" ")
  const cached = runtimeObjectCache.get(key)
  if (cached !== undefined) {
    return cached
  }
  const dir = path.join(buildDir, "runtime-obj", key.replace(/[^A-Za-z0-9]+/g, "_") || "default")
  fs.mkdirSync(dir, { recursive: true })
  const built = { objects: [], driver: null, error: null }
  for (const src of [...RUNTIME_C, DRIVER_C]) {
    const obj = path.join(dir, path.basename(src).replace(/\.c$/, ".o"))
    const cc = spawnSync("clang", ["-O2", ...defines, "-c", src, "-o", obj], { cwd: root })
    if (cc.status !== 0) {
      built.error = `could not compile ${src}${key.length > 0 ? ` with ${key}` : ""}:\n${cc.stderr}`
      break
    }
    if (src === DRIVER_C) {
      built.driver = obj
    } else {
      built.objects.push(obj)
    }
  }
  runtimeObjectCache.set(key, built)
  return built
}

/**
 * The first case linked under each object key, kept so the equivalence check
 * can replay it from the sources. `fromSource` is the command line this suite
 * used before the objects existed, argument for argument.
 */
const linkSpecimens = new Map()

/** Keep `specimen` as the one for `key`, unless a link before it already was. */
const keepSpecimen = (key, specimen) => {
  if (!linkSpecimens.has(key)) {
    linkSpecimens.set(key, specimen)
  }
}

/**
 * The `clang` line that links one compiled case against the prebuilt runtime,
 * without running it: `args` wants only `-o <exe>` after it.
 *
 * `driver` is `DRIVER_C` for the shared driver, a path for a case that brings
 * its own `.c`, and null when the module carries its own `main`. `defines` says
 * how the runtime has to have been built, and is what selects the objects.
 * `error` is the runtime's own compile failure, and null when there is a line.
 *
 * The specimen comes back rather than being kept here because section A links
 * its cases concurrently, and has to keep them in corpus order, not in the
 * order the links started; {@link linkNative} keeps it straight away.
 */
const linkLine = (ll, { driver = null, defines = [], libm = false } = {}) => {
  const rt = runtimeObjects(defines)
  if (rt.error !== null) {
    return { error: rt.error, args: null, key: null, specimen: null }
  }
  const tail = libm ? ["-lm"] : []
  const driverObject = driver === DRIVER_C ? rt.driver : driver
  const args = [
    "-Wno-override-module",
    "-O2",
    ll,
    ...(driverObject === null ? [] : [driverObject]),
    ...rt.objects,
    ...tail,
  ]
  const specimen = {
    ll,
    fromObjects: args,
    // `-D` sits on the from-source line because it is compiling the runtime
    // there; on the object line it is already baked in, which is precisely
    // what the byte comparison of the two is asserting.
    fromSource: [
      "-Wno-override-module",
      "-O2",
      ...defines,
      ll,
      ...(driver === null ? [] : [driver]),
      ...RUNTIME_C,
      ...tail,
    ],
  }
  return { error: null, args, key: defines.join(" "), specimen }
}

/**
 * Link one compiled case into a runnable binary, against the prebuilt runtime,
 * with the options {@link linkLine} takes.
 *
 * Answers in `spawnSync`'s shape, so a caller reads `status` and `stderr` the
 * way it always did; a runtime that would not compile is reported as a link
 * failure against the case, because that is what it is from here.
 */
const linkNative = (exe, ll, options = {}) => {
  const line = linkLine(ll, options)
  if (line.error !== null) {
    return { status: 1, stdout: "", stderr: line.error }
  }
  keepSpecimen(line.key, line.specimen)
  return spawnSync("clang", [...line.args, "-o", exe], { cwd: root })
}

let failures = 0
let passes = 0
/**
 * Sections that did not run. Counted rather than only printed: without LLVM the
 * toolchain-dependent half of this suite skips instead of failing, and a run
 * that ends `N passed, 0 failed` then looks exactly like a run that proved
 * everything. The summary says how many skipped and the banner says which
 * tools were missing, so a reader -- or an agent -- can tell the two apart.
 */
const skipped = []
const skip = (reason) => {
  console.log(`SKIP  ${reason}`)
  skipped.push(reason)
}
/**
 * Checks this run handed to another job of the same CI run, each with the job
 * that proves it. A third column beside passed and skipped, because it is
 * neither: nothing here proved it, so it is not a pass, and something else in
 * the same run did, so it is not the "unproven by this run" a skip is. Counted
 * and named in the summary so that a reader of this job's log can see the
 * claim, and whom to hold to it, without opening the workflow.
 *
 * Only a check that another job proves *with the same inputs on the same
 * platform* may be delegated, and only when the workflow asks for it by flag.
 * There are two kinds today. The bootstrap's fixed point, and the WP14 section
 * says when the request is honoured and what makes it true. And a link
 * program's checks of what the compiler wrote rather than of what the program
 * did (`DELEGATE_IR_CHECKS`), which are the same on every host: a mac runs
 * the program, and the Linux `test` job checks the compile.
 */
const delegated = []
const delegate = (name, provedBy) => {
  console.log(`DELEGATED  ${name} -- proved by ${provedBy}`)
  delegated.push({ name, provedBy })
}
const check = (name, ok, detail) => {
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}`)
  if (ok) {
    passes++
  } else {
    failures++
    if (detail) {
      console.log(
        String(detail)
          .split("\n")
          .map((l) => "      " + l)
          .join("\n")
      )
    }
  }
  return ok
}
const has = (tool) => spawnSync("which", [tool]).status === 0
const HAS_LLVM_AS = has("llvm-as")
const HAS_CLANG = has("clang")

/**
 * The WASI sysroot the `wasi` profile links against, or undefined: wasi-sdk's,
 * or the wasi-libc package's (`WASI_SYSROOT=/usr` on Debian and Ubuntu, which
 * install it under /usr/lib/wasm32-wasi). The same places scripts/build.sh
 * looks. Every wasi check asks this once, so a check that finds a sysroot and
 * still cannot link fails rather than skipping as though there were none.
 */
const WASI_SYSROOT = [
  process.env.WASI_SYSROOT,
  "/usr/lib/wasi-sysroot",
  "/opt/wasi-sdk/share/wasi-sysroot",
  "/usr/share/wasi-sysroot",
].find((d) => d && fs.existsSync(path.join(d, "lib")))

/** `-g` end to end: the linked binary is read with the dumper when there is one. */
const HAS_LLVM_DWARFDUMP = has("llvm-dwarfdump")

/**
 * Whether this host's object format is Mach-O rather than ELF.
 *
 * Named once because two checks below differ by it, and both for the same
 * underlying reason: what a *linker* leaves behind is the platform's business,
 * so a check that reads a linked binary has to ask where the thing it wants
 * ended up, and a check about a link being refused has to ask which linker
 * refuses it. Neither is a fact about the compiler -- the IR is the same on
 * both -- which is why neither branches on the platform for what it asserts,
 * only for where it looks and for what did the refusing.
 */
const IS_MACHO = process.platform === "darwin"

/**
 * The file that holds a linked program's DWARF line table, which is not the
 * same file on both platforms.
 *
 * On ELF the executable carries `.debug_line` itself. On Mach-O it does not:
 * `clang -g` leaves the DWARF in the object files and the executable keeps only
 * a debug map naming them, so `llvm-dwarfdump --debug-line <exe>` prints the
 * section header with no table under it and says nothing at all about whether
 * `-g` worked. What holds the table is the `.dSYM` bundle `dsymutil` builds out
 * of that map, and the Darwin clang driver runs `dsymutil` itself whenever it
 * compiles and links in one step -- which is every link this suite makes --
 * precisely because the objects the map names are its own temporaries and it is
 * about to delete them.
 *
 * So the bundle beside the binary is the answer, and **running `dsymutil`
 * afterwards is not a fallback.** Measured on `macos-latest`: by then the
 * temporaries are gone, the tool warns `unable to open object file` once per
 * missing object, writes a bundle whose `.debug_line` is empty -- and exits 0.
 * Reaching for it would turn "there is no line table here" into "the line table
 * has no rows", which is the same failure wearing a worse message.
 *
 * Answering with the file rather than branching at each call site is what keeps
 * the two `-g` checks below asserting one property on both platforms: the table
 * names the `.ts` file it was compiled from, and it has at least one row.
 */
const lineTableOf = (exe) => {
  if (!IS_MACHO) {
    return { file: exe, where: "the linked binary" }
  }
  const bundle = `${exe}.dSYM`
  const inside = path.join(bundle, "Contents", "Resources", "DWARF", path.basename(exe))
  return fs.existsSync(inside)
    ? { file: inside, where: `${path.basename(bundle)}, the bundle beside the linked binary` }
    : { file: exe, where: `the linked binary, since no ${path.basename(bundle)} was written` }
}

/**
 * Print the run's accounting and exit with its verdict.
 *
 * It is a function because there are two places a run can end: the last check
 * in the file, and the build of the compiler under test below, without which
 * nothing after it can run. Both have to report the same way, because the whole
 * value of this line is that a reader can trust it -- and a run that stopped
 * early and printed a bare `N passed` would read exactly like a full one.
 *
 * The summary counts what did *not* run as well as what did. A skip is not a
 * failure -- a contributor without LLVM is meant to be able to run this -- but
 * it is also not a pass, and the difference decides how much a green run is
 * worth. `.claude/orientation.md` and `.claude/node.md` say so in prose; this
 * says it in the output, where it is read.
 */
const summarise = () => {
  const summary = [`${passes} passed`, `${failures} failed`]
  if (skipped.length > 0) {
    summary.push(`${skipped.length} skipped`)
  }
  if (delegated.length > 0) {
    summary.push(`${delegated.length} delegated`)
  }
  console.log(`\n${summary.join(", ")}.`)

  // Before the skip note, and apart from it, because the two say different
  // things: a skip is unproven, a delegation is proved by the job it names --
  // which is also why this run is only as green as that job is.
  if (delegated.length > 0) {
    console.log(
      `\nDelegated: ${delegated.length} check(s) are proved by another job of this CI run rather than by this one, ` +
        "so read this result together with that job's:\n" +
        delegated.map((d) => `  ${d.name}: ${d.provedBy}`).join("\n")
    )
  }

  if (skipped.length > 0) {
    const TOOLCHAIN = ["clang", "llc", "llvm-as", "opt", "ld.lld", "wasm-ld"]
    const absent = TOOLCHAIN.filter((tool) => !has(tool))
    console.log(
      absent.length > 0
        ? `\nDEGRADED: ${absent.length} of the ${TOOLCHAIN.length} LLVM 18 tools are missing (${absent.join(", ")}), so ` +
            `${skipped.length} section(s) were skipped rather than run. This result does NOT prove the toolchain-dependent\n` +
            "checks pass: assembly, native round trips, linking, the interop addons, the self-hosting oracles and the\n" +
            "differential suite are among them. Install LLVM 18 (docs/INSTALL.md) and run again before trusting a green run."
        : `\nNote: ${skipped.length} section(s) were skipped for reasons other than a missing LLVM toolchain ` +
            "(see the SKIP lines above); everything they cover is unproven by this run."
    )
  }

  process.exit(failures === 0 ? 0 : 1)
}

/**
 * The DWARF producer, with the version replaced by a placeholder.
 *
 * `-g` writes `producer: "nish <version>"` into the compile unit, so two
 * goldens would otherwise have to be regenerated at every release for a change
 * that is not a lowering at all -- and the release pull request, which is the
 * commit that bumps the version, would be red at itself. Applied to the golden
 * as well as to the emitted IR, so a golden written before this is still read
 * correctly. `llvm-as` runs on the emitted file rather than the golden, so the
 * placeholder never reaches a verifier.
 */
const normaliseProducer = (ir) => ir.replace(/producer: "nish [^"]*"/g, 'producer: "nish <version>"')

/** Module body with the `; ModuleID` / `source_filename` header removed. */
const stripHeader = (ir) =>
  ir
    .split("\n")
    .filter((l) => !l.startsWith(";") && !l.startsWith("source_filename"))
    .join("\n")
    .trim()

/**
 * Every `--json` object a compile printed. A line that does not parse is kept
 * as an error, so a garbled stream cannot read as a clean one.
 */
const diagnosticsOf = (stdout) =>
  String(stdout)
    .split("\n")
    .filter((line) => line.startsWith("{"))
    .map((line) => {
      try {
        return JSON.parse(line)
      } catch {
        return { severity: "error", code: "unparsed", message: line }
      }
    })

/** One `--json` diagnostic as a report line: `file:line:col CODE message`. */
const diagnosticLine = (d) => `${d.file}:${d.line}:${d.column} ${d.code} ${d.message}`

/**
 * Every module of the library under `dir` (`std/` by default), at any depth, as
 * `std/<path>` with `/` separators, sorted. Recursive because a module may live in
 * a subdirectory (`std/crypto/sha256.ts` is `nish/crypto/sha256`), and a check that
 * read only the top level would pass over it without saying so.
 */
const stdModuleFiles = (dir = path.join(root, "std")) =>
  fs
    .readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith(".ts"))
    .map((entry) =>
      ["std", ...path.relative(dir, path.join(entry.parentPath, entry.name)).split(path.sep)].join("/")
    )
    .sort()

/** A dotted version as numbers, for ordering releases. */
const semver = (v) => v.split(".").map(Number)

/** Whether dotted version `a` is at or before `b` (`0.4.0` is not after `0.5.0`). */
const notAfter = (a, b) => {
  const [x, y] = [semver(a), semver(b)]
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    if ((x[i] ?? 0) !== (y[i] ?? 0)) {
      return (x[i] ?? 0) < (y[i] ?? 0)
    }
  }
  return true
}

/** The canonical triple `--target host` resolves to on this machine, or undefined where there is none. */
const HOST_TRIPLE = {
  linux: { x64: "x86_64-unknown-linux-gnu", arm64: "aarch64-unknown-linux-gnu" },
  darwin: { x64: "x86_64-apple-darwin", arm64: "aarch64-apple-darwin" },
}[process.platform]?.[process.arch]

// The modes stage0 retired with it. Refused rather than ignored: a flag the
// suite no longer reads would run the whole suite and print a green summary
// that says nothing about what the flag asked for.
const RETIRED = ["--parity", "--verify-batch", "--batch-gate-only"].filter((flag) =>
  process.argv.includes(flag)
)
if (RETIRED.length > 0) {
  console.error(
    `tests/run.js: ${RETIRED.join(", ")} compared stage0 with stage1 and went with stage0 (R6); ` +
      "there is nothing left to compare"
  )
  process.exit(2)
}

// ---- Shards ------------------------------------------------------------------------
//
// `--shard <i>/<n>` splits one run between `n` CI jobs, because the link programs
// below are two thirds of the suite's wall clock and run one at a time. Every
// shard builds the compiler and runs everything before the link programs, which
// is under two minutes. Shard 1 then runs every section after them but the
// dealt ones (`DEALT_SECTIONS`: WP14 self-hosting and crypto-bench), and the
// link programs a later section reads the output of (`LINK_READ_LATER`). The
// dealt sections and the other link programs are dealt by their cost in
// `tests/shard-costs.json` (see `linkShard`), and every shard but 1 stops once
// its share is done. A filtered run (`node tests/run.js net_ --shard 2/3`)
// deals only the programs its filter selects. What a shard leaves to
// another is a delegation, named in its summary, and never a skip that reads as
// unproven or a check that silently was not made. No `--shard`, or
// `--shard 1/1`, is the whole suite.
const shardAt = process.argv.indexOf("--shard")
const shardSpec = shardAt >= 0 ? (process.argv[shardAt + 1] ?? "") : "1/1"
const [SHARD, SHARDS] = /^\d+\/\d+$/.test(shardSpec) ? shardSpec.split("/").map(Number) : [0, 0]
if (SHARDS < 1 || SHARD < 1 || SHARD > SHARDS) {
  console.error(`tests/run.js: --shard wants <i>/<n> with 1 <= i <= n, not ${shardSpec || "nothing"}`)
  process.exit(2)
}
/**
 * The CI job that proves what this shard leaves to shard `i`: the same job's
 * shard `i`, since more than one job is sharded (the \`test\` job's whole suite
 * and \`runtime-net\`'s \`net_\` sections).
 */
const shardJob = (i) => `shard ${i}/${SHARDS} of this job`

// ---- The compiler under test -----------------------------------------------------
//
// One stage1 for the whole run, linked by the seed: `--seed <nish>`, then
// `NISH_BOOTSTRAP`, then what `tests/self/seed.js` finds in the tree
// (`seedForOracle` says which, and says so on stderr when it had to fall back).
// Every check below spawns it, so without it nothing below can run: a machine
// with no clang cannot link it and the run is a counted skip that the DEGRADED
// banner explains, and a seed that cannot build `src/` is a failure, because
// that is the rolling freeze broken (WP19 G3).
const seed = HAS_CLANG
  ? seedForOracle(process.argv)
  : { error: "clang not found, and the compiler under test has to be linked" }
/** The seed as the tools this suite drives are handed it (`--seed <spec>`). */
const seedSpec = seed.label
if (seed.error !== undefined) {
  if (HAS_CLANG) {
    check("the compiler under test: a seed to build it with", false, seed.error)
  } else {
    skip(`every check: ${seed.error}`)
  }
  summarise()
}
fs.rmSync(`${NISH}.modules`, { recursive: true, force: true })
if (
  !check(
    `the compiler under test: the seed (${seed.label}) builds src/compile.ts into build/nish-test`,
    linkWith(seed, path.join("src", "compile.ts"), NISH) !== null,
    "(the seed's report is on stderr above)"
  )
) {
  summarise()
}

// ---- A. Golden cases -------------------------------------------------------------
//
// Every case is taken from its compile by the compiler under test to its native
// run, one case per job and `defaultJobs()` of them at a time (`runCase`). The
// cases are independent of each other and the sections after this one are not
// -- a later section reads the `.ll` a case left in `build/test` -- so every
// case has finished before the next section starts, and the checks are
// reported in corpus order, which keeps the output the same at any width.
const only = withoutSeed(process.argv.slice(2).filter((_, i) => i + 2 !== shardAt && i + 1 !== shardAt)).find(
  (arg) => !arg.startsWith("-")
)
const cases = fs
  .readdirSync(casesDir)
  .filter((f) => f.endsWith(".ts"))
  .map((f) => f.slice(0, -3))
  .sort()

/** The `.args` of a case as the compiler is handed them, or `[]`. */
const caseArgs = (name) => {
  const file = path.join(casesDir, `${name}.args`)
  return fs.existsSync(file) ? fs.readFileSync(file, "utf8").trim().split(/\s+/).filter(Boolean) : []
}

/**
 * `<name>.env`: one `NAME=value` per line, layered over the environment the
 * harness inherited. A case that reads the environment (`getenv`, WP19 R1)
 * cannot pin the answer itself — the language has no `setenv` — so the runner
 * is the only place the value can come from, and a golden that depended on
 * the developer's own environment would not be a golden. Blank lines and `#`
 * comments are ignored; `NAME=` sets an empty value, which is a *set*
 * variable and not the same as leaving it out, and a bare `NAME` unsets it.
 */
const caseEnv = (file) => {
  if (!fs.existsSync(file)) {
    return process.env
  }
  const env = { ...process.env }
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    const text = line.trim()
    if (text.length === 0 || text.startsWith("#")) {
      continue
    }
    const eq = text.indexOf("=")
    // A bare `NAME` takes the variable *away*, which `NAME=` cannot do: an
    // empty value is a set variable, and `getenv`'s third answer — unset — is
    // otherwise only as reliable as the developer's own environment.
    if (eq < 0) {
      delete env[text]
    } else if (eq > 0) {
      env[text.slice(0, eq)] = text.slice(eq + 1)
    }
  }
  return env
}

const selectedCases = cases.filter((name) => !only || name.includes(only))

/**
 * The lane a case's native program runs in: one program at a time, whatever
 * else section A has in flight.
 *
 * The compiles, assemblies and links around it are separate processes writing
 * separate files, but the programs share a world. Each runs from the repository
 * root, and some write the same file: `io_nish_import` and
 * `io_nish_import_global` both write and read back
 * `build/test/io_nish_import.txt`, and have to, because a check below requires
 * the two to emit the same IR. Side by side, one could read the other's file
 * half-written. So they take turns, as they did when the whole loop was
 * sequential; a program is a small part of its case's time, and the links of
 * the cases around it still overlap it.
 */
let nativeLane = Promise.resolve()
const inNativeLane = (job) => {
  const turn = nativeLane.then(job)
  nativeLane = turn
  return turn
}

/**
 * The bound on one native run of a case: a `tests/cases/` program with a `.out`
 * and a `tests/link/` program. Without one, a program that never exits hangs
 * the suite and the CI job with it until the job's own limit, and says nothing
 * about which case it was; a deliberate mutation on #402 did exactly that.
 * Measured over one whole `npm test` (742 runs): every case program finished in
 * under 0.7 s, and the slowest link programs are the `crypto_*_long_f64` family
 * at 10-12 s, `link/cg_sec_push_limit` (a 2 GiB array) at 13.2 s and
 * `link/crypto_ct_long_f64` at 28.1 s. 120 s is four times that slowest run,
 * room for a slower runner, and a hang is still named within two minutes.
 * SIGKILL, because a program stuck in a loop may be one that ignores SIGTERM.
 */
const NATIVE_RUN_LIMIT = { timeout: 120_000, killSignal: "SIGKILL" }

/**
 * This process's environment with `NISH_NUM_THREADS` set to `threads`, or
 * removed when `threads` is null, so a count the developer exported cannot
 * leak into a check that pins one.
 */
const envWithThreads = (threads) => {
  const { NISH_NUM_THREADS: _inherited, ...env } = process.env
  return threads === null ? env : { ...env, NISH_NUM_THREADS: threads }
}

/**
 * The runtime unit test built with `-DNISH_THREADS`: `{ status, stderr, exe }`.
 * Built once per process, on first use, by whichever section asks first, so
 * neither depends on the other having run (.claude/testing.md, "A filtered run's
 * count").
 */
let runtimeTestThreads = null
const buildRuntimeTestThreads = () => {
  if (runtimeTestThreads === null) {
    const exe = path.join(buildDir, "runtime_test_threads")
    const cc = spawnSync(
      "clang",
      [
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-O2",
        "-DNISH_THREADS=1",
        "-pthread",
        // Every translation unit, as its non-threaded sibling names them:
        // `runtime-test.c` exercises the file I/O, which lives in runtime-os.c
        // since the split, so naming only the core leaves `nish_write_file`,
        // `nish_append_file` and `nish_read_file` undefined at link time.
        ...RUNTIME_C,
        "tests/runtime-test.c",
        "-o",
        exe,
      ],
      { cwd: root, encoding: "utf8" }
    )
    runtimeTestThreads = { status: cc.status, stderr: cc.stderr, exe }
  }
  return runtimeTestThreads
}

/**
 * Run a case's native program under `limit`: spawn's `{ status, signal,
 * stdout, stderr }`, and `death`, which is null when the program exited and
 * otherwise the FAIL a caller reports instead of comparing output. A program
 * that ran into the bound and one killed by a signal before it (the OOM killer,
 * an abort) each fail under their own name, so neither reads as a wrong `.out`.
 * `limit` is a parameter for the "native run limit" self-check, which holds
 * this to its promise in under a second rather than in two minutes.
 */
/** How many times a link program with an expected.stderr runs at each pool size. */
const PANIC_ONCE_RUNS = 50

const runNative = async (name, exe, argv, opts = {}, limit = NATIVE_RUN_LIMIT) => {
  const started = Date.now()
  const run = await spawnAsync(exe, argv, { ...opts, ...limit })
  const ms = Date.now() - started
  let death = null
  if (run.signal === limit.killSignal && ms >= limit.timeout) {
    death = `${name}: the native run was killed after ${limit.timeout / 1000} s without exiting (NATIVE_RUN_LIMIT)`
  } else if (run.signal !== null) {
    death = `${name}: the native run died on ${run.signal} after ${ms} ms`
  }
  return { ...run, death }
}

/**
 * One golden case from its compile to its native run, with what it found kept
 * as a list of steps rather than printed.
 *
 * The cases run `defaultJobs()` at a time and finish in any order, so nothing
 * here may reach the run's output or its counters directly: the loop below
 * replays each case's steps in corpus order, and N jobs print what one did. A
 * step is a check, a line to print, or the link specimen `linkNative` would
 * have kept at that point -- which case is kept first decides what the
 * `runtime objects:` check replays, so that is settled in corpus order too
 * rather than by whichever link happened to start first. A passing check's
 * detail is dropped on the spot, since `check` prints one only for a failure,
 * so that a finished case waiting its turn does not hold two copies of its IR.
 *
 * Every file a case writes is named after it (`build/test/<name>.ll`, its
 * `.portability.ll`, its executable), so two cases in flight never share an
 * output; the one thing they can share is the world their programs run in,
 * which is what {@link inNativeLane} is for.
 */
const runCase = async (name) => {
  const src = path.join(casesDir, `${name}.ts`)
  const side = (ext) => path.join(casesDir, `${name}.${ext}`)
  const args = caseArgs(name)
  const outLl = path.join(buildDir, `${name}.ll`)
  const steps = []
  const expect = (label, ok, detail) => {
    steps.push({ kind: "check", label, ok, detail: ok ? undefined : detail })
  }
  const r = await spawnAsync(NISH, [src, "-o", outLl, ...args], { cwd: root })
  const done = { compiled: r, steps, panicFunctions: 0 }
  const stderr = String(r.stderr)

  if (fs.existsSync(side("err"))) {
    // One fragment per line; every one must appear (WP10: several errors from one compile).
    const needles = fs
      .readFileSync(side("err"), "utf8")
      .split("\n")
      .map((l) => l.trim())
      .filter(Boolean)
    const missing = needles.filter((n) => !stderr.includes(n))
    expect(
      `${name}: rejected with ${needles.map((n) => `"${n}"`).join(", ")}`,
      r.status === 1 && missing.length === 0,
      stderr || "(compiled successfully)"
    )
    return done
  }
  if (r.status !== 0) {
    expect(`${name}: compiles`, false, stderr)
    return done
  }
  // A `port_*` case exists for its warnings, and without the golden nothing
  // would compile it with the flag: it would pass while asserting nothing.
  if (name.startsWith("port_") && !fs.existsSync(side("portability"))) {
    expect(`${name}: has a .portability golden (an empty one for a quiet case)`, false)
  }
  if (fs.existsSync(side("portability"))) {
    // WP33: the warnings are off by default, so the case compiles a second
    // time with the flag, and its portability objects are the golden, one per
    // line and in report order. Paths are taken back to the repository's, as
    // for `.stdout`.
    const warnedLl = path.join(buildDir, `${name}.portability.ll`)
    const warned = await spawnAsync(NISH, [src, "-o", warnedLl, ...args, "--warn-portability", "--json"], {
      cwd: root,
      encoding: "utf8",
    })
    const want = fs.readFileSync(side("portability"), "utf8").trim()
    const got = warned.stdout
      .split("\n")
      .filter((l) => l.includes('"severity":"portability"'))
      .join("\n")
      .split(`${root}/`)
      .join("")
    expect(
      `${name}: --warn-portability --json matches .portability`,
      warned.status === 0 && got === want,
      `--- expected\n${want}\n--- actual (exit ${warned.status})\n${got}\n${warned.stderr}`
    )
    // Warnings never reach the IR (wp33 §1 rule 6): both compiles wrote the same bytes.
    expect(
      `${name}: --warn-portability changes no byte of the IR`,
      fs.existsSync(warnedLl) && fs.readFileSync(warnedLl, "utf8") === fs.readFileSync(outLl, "utf8"),
      "the two .ll files differ"
    )
  }
  if (fs.existsSync(side("caps.json"))) {
    // WP35: the capability report, compiled a second time for the same reason
    // the portability warnings are -- the flag is not in `.args`, because the
    // tools that compile `tests/cases/` with the last release would refuse it.
    // The report's paths are relative to the entry's directory, so the file is
    // compared as it is, byte for byte: that it reads the same from any
    // checkout is part of what it promises (docs/wp35-capabilities.md §5).
    const capsLl = path.join(buildDir, `${name}.caps.ll`)
    const capsJson = path.join(buildDir, `${name}.caps.json`)
    const reported = await spawnAsync(NISH, [src, "-o", capsLl, ...args, "--emit-capabilities", capsJson], {
      cwd: root,
      encoding: "utf8",
    })
    const want = fs.readFileSync(side("caps.json"), "utf8")
    const got = fs.existsSync(capsJson) ? fs.readFileSync(capsJson, "utf8") : ""
    expect(
      `${name}: --emit-capabilities matches .caps.json byte for byte`,
      reported.status === 0 && got === want,
      `--- expected\n${want}\n--- actual (exit ${reported.status})\n${got}\n${reported.stderr}`
    )
    // The report is read off the fixpoint and never written back into it.
    expect(
      `${name}: --emit-capabilities changes no byte of the IR`,
      fs.existsSync(capsLl) && fs.readFileSync(capsLl, "utf8") === fs.readFileSync(outLl, "utf8"),
      "the two .ll files differ"
    )
  }
  if (fs.existsSync(side("stdout"))) {
    // A dump flag (`--emit-ast`, `--emit-checked`): the compiler's stdout is the golden, no IR is written.
    // stage1 prints a module path the way it was handed one, and this suite
    // hands it absolute ones, so the checkout is taken back off: the goldens
    // name each module relative to the repository, as a user running from
    // the root would see it.
    const want = fs.readFileSync(side("stdout"), "utf8").trim()
    const got = String(r.stdout).split(`${root}/`).join("").trim()
    expect(`${name}: stdout matches .stdout`, got === want, `--- expected\n${want}\n--- actual\n${got}`)
    return done
  }

  // `-g` names the working directory in `DIFile`; keep the golden machine-independent.
  // It also names the compiler's version in the DWARF producer, which changes
  // at every release and is not a fact about the lowering -- so normalise it
  // the same way, and for the same reason one step further out: without this
  // the release pull request's own version bump turns `dbg_locals` and
  // `dbg_result` red, and a release cannot go green on itself. The version is
  // still pinned, by the `--version` checks and by the branding/package.json
  // equality check above; it is just not pinned once per golden.
  const actual = normaliseProducer(stripHeader(fs.readFileSync(outLl, "utf8")).split(root).join("<root>"))
  if (!fs.existsSync(side("ll"))) {
    if (process.env.UPDATE_GOLDENS) {
      fs.writeFileSync(side("ll"), actual + "\n")
      steps.push({ kind: "log", text: `WROTE ${name}.ll` })
    } else {
      expect(`${name}: has golden .ll (run with UPDATE_GOLDENS=1 to create)`, false)
      return done
    }
  }
  const expected = normaliseProducer(fs.readFileSync(side("ll"), "utf8").trim())
  expect(
    `${name}: IR matches golden`,
    actual === expected,
    `--- expected\n${expected}\n--- actual\n${actual}`
  )

  if (HAS_LLVM_AS) {
    const as = await spawnAsync("llvm-as", [outLl, "-o", "/dev/null"])
    expect(`${name}: llvm-as accepts IR`, as.status === 0, String(as.stderr))
  }

  // `--emit-panics`: every golden compiles a second time with the flag, which
  // must change no byte of the IR, and the sites it writes are held against
  // that IR (`tests/panics-oracle.js`). A `<name>.panics` file is the golden
  // of the list itself, paths taken back to the repository's. The flag is not
  // written into `.args`, for the reason `.portability`'s is not: the tools
  // that compile `tests/cases/` with the last release would refuse it.
  const panicsLl = path.join(buildDir, `${name}.panics.ll`)
  const panicsFile = path.join(buildDir, `${name}.panics.json`)
  const listed = await spawnAsync(NISH, [src, "-o", panicsLl, ...args, "--emit-panics", panicsFile], {
    cwd: root,
    encoding: "utf8",
  })
  const listedIr = fs.existsSync(panicsLl) ? fs.readFileSync(panicsLl, "utf8") : null
  const listText = fs.existsSync(panicsFile) ? fs.readFileSync(panicsFile, "utf8") : null
  if (listed.status !== 0 || listedIr === null || listText === null) {
    expect(`${name}: --emit-panics writes the sites`, false, `exit ${listed.status}\n${listed.stderr}`)
  } else {
    // The case is the program's only module that writes a `.ll`, so every
    // function of its own must be found in it (`panicOracle`'s `module`).
    const oracle = panicOracle(listedIr, JSON.parse(listText), src)
    done.panicFunctions = oracle.checked
    expect(
      `${name}: --emit-panics changes no byte of the IR, and agrees with it`,
      listedIr === fs.readFileSync(outLl, "utf8") && oracle.failures.length === 0,
      oracle.failures.length > 0 ? oracle.failures.join("\n") : "the two .ll files differ"
    )
    if (fs.existsSync(side("panics"))) {
      const want = fs.readFileSync(side("panics"), "utf8").trim()
      const got = listText.split(`${root}/`).join("").trim()
      expect(
        `${name}: --emit-panics matches .panics`,
        got === want,
        `--- expected\n${want}\n--- actual\n${got}`
      )
    }
  }

  // `--emit-arena`: a case with a `<name>.arena` golden compiles a third time
  // with the flag, which must change no byte of the IR, and the placements it
  // writes are held against the golden, paths taken back to the repository's.
  // Only those cases: the report reads facts the compile already has, so there
  // is nothing a corpus-wide run would find that the goldens do not pin.
  if (fs.existsSync(side("arena"))) {
    const arenaLl = path.join(buildDir, `${name}.arena.ll`)
    const arenaFile = path.join(buildDir, `${name}.arena.json`)
    const placed = await spawnAsync(NISH, [src, "-o", arenaLl, ...args, "--emit-arena", arenaFile], {
      cwd: root,
      encoding: "utf8",
    })
    if (placed.status !== 0 || !fs.existsSync(arenaLl) || !fs.existsSync(arenaFile)) {
      expect(`${name}: --emit-arena writes the placements`, false, `exit ${placed.status}\n${placed.stderr}`)
    } else {
      expect(
        `${name}: --emit-arena changes no byte of the IR`,
        fs.readFileSync(arenaLl, "utf8") === fs.readFileSync(outLl, "utf8"),
        "the two .ll files differ"
      )
      const want = fs.readFileSync(side("arena"), "utf8").trim()
      const got = fs.readFileSync(arenaFile, "utf8").split(`${root}/`).join("").trim()
      expect(
        `${name}: --emit-arena matches .arena`,
        got === want,
        `--- expected\n${want}\n--- actual\n${got}`
      )
    }
  }

  if (fs.existsSync(side("out"))) {
    const driver = fs.existsSync(side("c")) ? side("c") : DRIVER_C
    // WP5: a case with its own exported `main` is a whole program; link it without the driver.
    // Either spelling declares it (WP22): `export function main` or `export const main = (...) => ...`.
    const hasEntry = /\bexport\s+(?:function\s+main\b|const\s+main\s*=)/.test(fs.readFileSync(src, "utf8"))
    const exe = path.join(buildDir, name)
    // WP20 T0: a case compiled with `--threads` references `@nish_arena` as a
    // thread-local global, so runtime.c has to define it as one. The macro is
    // what `scripts/build.sh --threads` passes, and the link is still the check:
    // ELF refuses a non-TLS reference to a TLS definition, so a case that got
    // this wrong fails here rather than running with two arenas. Since the
    // runtime is now a prebuilt object, the macro is also what picks *which*
    // object -- and the `runtime objects:` checks below hold that choice up.
    const threads = args.includes("--threads") ? ["-DNISH_THREADS=1"] : []
    // -lm: Math.sin/cos/exp/log/pow lower to LLVM intrinsics that become libm calls (WP7).
    const line = linkLine(outLl, {
      driver: hasEntry ? null : driver,
      defines: threads,
      libm: true,
    })
    if (line.error !== null) {
      expect(`${name}: links natively`, false, line.error)
      return done
    }
    steps.push({ kind: "specimen", key: line.key, specimen: line.specimen })
    const cc = await spawnAsync("clang", [...line.args, "-o", exe], { cwd: root })
    if (cc.status !== 0) {
      expect(`${name}: links natively`, false, String(cc.stderr))
      return done
    }
    const argv = fs.existsSync(side("argv"))
      ? fs.readFileSync(side("argv"), "utf8").trim().split(/\s+/).filter(Boolean)
      : []
    // Timed inside the lane, so the wait for a turn is not counted as the run.
    const run = await inNativeLane(() => runNative(name, exe, argv, { env: caseEnv(side("env")) }))
    if (run.death !== null) {
      expect(run.death, false, `stdout so far:\n${run.stdout}${run.stderr}`)
      return done
    }
    const want = fs.readFileSync(side("out"), "utf8").trim()
    expect(
      `${name}: native output matches .out`,
      run.status === 0 && String(run.stdout).trim() === want,
      `--- expected\n${want}\n--- actual (exit ${run.status})\n${run.stdout}${run.stderr}`
    )
  }
  return done
}

/** Put one finished case's steps on the record, as the sequential loop would have. */
const reportCase = ({ steps }) => {
  for (const step of steps) {
    switch (step.kind) {
      case "check":
        check(step.label, step.ok, step.detail)
        break
      case "log":
        console.log(step.text)
        break
      case "specimen":
        keepSpecimen(step.key, step.specimen)
        break
      default:
        throw new Error(`section A: no step of kind ${step.kind}`)
    }
  }
}

// Each case is reported as soon as every case before it has been, so the log
// moves while the corpus runs and a slow case is still named where it sits.
const caseRuns = new Array(selectedCases.length).fill(null)
let reported = 0
await pool(selectedCases, defaultJobs(), async (name, at) => {
  caseRuns[at] = await runCase(name)
  while (reported < caseRuns.length && caseRuns[reported] !== null) {
    reportCase(caseRuns[reported])
    reported++
  }
})
// The bound on native runs, held to what it promises with a bound of half a
// second, because the real one takes two minutes to prove. `runNative` is the
// helper both case loops run their programs through, so a change that drops
// the limit, or turns a program that outlives it into a skip or a `.out`
// mismatch, fails here in about a second rather than hanging the next run that
// meets a loop. `sh -c 'kill -9 $$'` is a death before the bound: it must be
// named by its signal, not reported as the timeout.
if (!only || "native run limit".includes(only)) {
  const limit = { ...NATIVE_RUN_LIMIT, timeout: 500 }
  const started = Date.now()
  const slept = await runNative("native run limit", "sleep", ["3"], {}, limit)
  const ms = Date.now() - started
  check(
    "native run limit: a program that outlives the bound is killed at it and fails by name",
    slept.death ===
      "native run limit: the native run was killed after 0.5 s without exiting (NATIVE_RUN_LIMIT)" &&
      ms < 2500,
    `death: ${slept.death}\nreturned after ${ms} ms, status ${slept.status}, signal ${slept.signal}`
  )
  const killed = await runNative("native run limit", "sh", ["-c", "kill -9 $$"], {}, limit)
  check(
    "native run limit: a program killed by a signal before the bound fails naming the signal",
    killed.death !== null &&
      killed.death.startsWith("native run limit: the native run died on SIGKILL after "),
    `death: ${killed.death}\nstatus ${killed.status}, signal ${killed.signal}`
  )
}

/** Each selected case's own compile, in corpus order, for the checks below that read it again. */
const caseResults = caseRuns.map((run) => run.compiled)

// The oracle is only as good as its reading of the IR, so it is handed each
// panic path it claims to recognise, in a function listed as clean, and must
// refuse every one; and the same function with an unproven site, which it
// must leave alone.
{
  const fn = (panics) => ({ functions: [{ name: "f", symbol: "f", module: "m.ts", panics }] })
  const clean = fn([
    { kind: "oom", allowed: true },
    { kind: "unchecked", allowed: true },
    { kind: "index", proven: true },
  ])
  const unproven = fn([{ kind: "index", proven: false }])
  const define = (lines) => ["define internal i32 @f(i32 %x) {", ...lines, "  ret i32 0", "}"].join("\n")
  const paths = [
    "  call void @nish_panic_index(i64 %0, i64 %1)",
    "  call void @nish_panic_slice(i64 %0, i64 %1, i64 %2)",
    "  call void @nish_panic_div(i1 zeroext %0)",
    "  call void @nish_panic_overflow(i32 0)",
    "  %1 = call i8* @nish_read_file(i8* %0)",
    "  call void @nish_write_file(i8* %0, i8* %1)",
    "  call void @nish_append_file(i8* %0, i8* %1)",
    "  call void @nish_random_fill(%struct.nish_array* %0)",
    "  call void @nish_write(i8* %0, i32 2, i1 true)\n  call void @nish_exit(i32 1)",
    "ffi.nul:\n  call void @nish_panic(i8* %0)",
    "ffi.nul.3:\n  call void @nish_panic(i8* %0)",
  ]
  const missed = paths.filter((line) => panicOracle(define([line]), clean, null).failures.length !== 1)
  const flagged = paths.filter((line) => panicOracle(define([line]), unproven, null).failures.length > 0)
  const quiet = [
    "  call void @nish_write(i8* %0, i32 2, i1 false)",
    "  %1 = call i8* @nish_read_file_or_null(i8* %0)",
    "  call void @nish_exit(i32 %0)",
  ].filter((line) => panicOracle(define([line]), clean, null).failures.length > 0)
  check(
    "--emit-panics: the IR oracle refuses each panic path in a clean function, and nothing else",
    missed.length === 0 && flagged.length === 0 && quiet.length === 0,
    `missed: ${missed.join(" | ")}\nflagged despite a site: ${flagged.join(" | ")}\nnot a panic: ${quiet.join(" | ")}`
  )
  // A listed function the IR does not define: a failure for the module whose
  // IR is in hand, whatever its sites, and skipped for one of another module;
  // and the count of the module's own functions the link check asserts on.
  const absent = define([]).replace("@f(", "@g(")
  const own = [clean, unproven].map((report) => panicOracle(absent, report, "m.ts").failures.length)
  const other = [clean, unproven].map((report) => panicOracle(absent, report, "other.ts").failures.length)
  const counted = [panicOracle(absent, clean, "m.ts").own, panicOracle(absent, clean, "other.ts").own]
  check(
    "--emit-panics: the IR oracle fails a listed function its own module's IR does not define",
    own.every((n) => n === 1) && other.every((n) => n === 0) && counted[0] === 1 && counted[1] === 0,
    `failures for the module's own function: ${own.join(", ")}; for another module's: ${other.join(", ")}; own counted: ${counted.join(", ")}`
  )
}

// The oracle above passes vacuously on a function it never finds, so the run
// says how many it read: every golden with a clean function contributes, and
// a symbol spelling the oracle stopped recognising would take this to zero.
if (only === undefined) {
  const read = caseRuns.reduce((sum, run) => sum + run.panicFunctions, 0)
  check(
    `--emit-panics: the IR oracle read ${read} functions with nothing left that can panic`,
    read >= 500,
    "fewer than 500: the oracle is no longer finding the functions it is handed"
  )
}

// ---- Programs the world answers, built and run by the blocks below -----------------

/**
 * A `tests/cases/` program with a `main`, compiled into `dir` and linked against
 * the runtime objects this run already built (`linkNative`), rather than with
 * `--link`, which would build the runtime from source again for every case.
 * Answers the executable, or null once the failed link is a counted check.
 */
const buildCaseIn = (dir, name) => {
  const exe = path.join(dir, name)
  const ll = path.join(dir, `${name}.ll`)
  const r = spawnSync(NISH, [path.join(casesDir, `${name}.ts`), ...caseArgs(name), "-o", ll], {
    cwd: root,
    encoding: "utf8",
  })
  const cc = r.status === 0 ? linkNative(exe, ll, { libm: true }) : r
  return check(`${name}: links`, cc.status === 0, String(cc.stderr)) ? exe : null
}

/**
 * The same case's source run under `runtime/nish.mjs`. Under `node -e` the extra
 * arguments start at `process.argv[1]`, and the prelude's `process.argv` drops
 * index 0, so the case's name stands where the program path stands natively and
 * the arguments after it line up.
 */
const runCaseUnderPrelude = (name, args) =>
  runUnderPrelude(path.join(casesDir, `${name}.ts`), [name, ...args])

/**
 * `entry` run under `runtime/nish.mjs`, its `main` answering the exit status;
 * `args` follow `-e`'s script and `options` join `spawnSync`'s.
 */
const runUnderPrelude = (entry, args, exported = "main", options = {}) =>
  spawnSync(
    "node",
    [
      "--experimental-strip-types",
      "--no-warnings",
      "--import",
      path.join(root, "runtime", "nish.mjs"),
      "-e",
      `const m = await import(${JSON.stringify(entry)}); process.exit(m.${exported}());`,
      ...args,
    ],
    { cwd: root, encoding: "utf8", ...options }
  )

/** A spawned run's status and both streams, for a failed check's message. */
const shown = (r) => `exit ${r.status}\nstdout: ${r.stdout}\nstderr: ${r.stderr}`

// ---- The host builtins, against the clock, the kernel and Node (WP34 N3) ----------
//
// What a golden cannot say about `Date.now`, `crypto.getRandomValues`,
// `statMtimeSync` and the signal descriptor, because the answers are the world's
// rather than the program's. Each `tests/cases/os_*` program is built here with
// `--link` into a directory of its own, so no check depends on what section A left
// behind, and each claim is asked of the native binary and, where the TypeScript
// reading is class A, of the same source under `runtime/nish.mjs`.
if (!only || "os_host".includes(only)) {
  const osDir = path.join(buildDir, "os")
  fs.rmSync(osDir, { recursive: true, force: true })
  fs.mkdirSync(osDir, { recursive: true })
  const osNative = (exe, args) => spawnSync(exe, args, { cwd: root, encoding: "utf8" })
  const linesOf = (r) => r.stdout.split("\n").filter((l) => l.length > 0)

  // Date.now: a whole number of milliseconds held between two readings of Node's
  // own clock, taken either side of the run. Both are CLOCK_REALTIME floored to
  // the millisecond, so the bracket is exact rather than a tolerance: seconds,
  // microseconds or the monotonic clock would each fall outside it.
  const nowExe = buildCaseIn(osDir, "os_now")
  for (const [side, run] of [
    ["natively", (args) => osNative(nowExe, args)],
    ["under the prelude", (args) => runCaseUnderPrelude("os_now", args)],
  ]) {
    if (nowExe === null) {
      break
    }
    const before = Date.now()
    const r = run(["print"])
    const after = Date.now()
    const lines = linesOf(r)
    const t = Number(lines[2])
    check(
      `os_now: Date.now() ${side} is a whole millisecond between two readings of Node's clock`,
      r.status === 0 &&
        lines[0] === "true" &&
        lines[1] === "true" &&
        Number.isInteger(t) &&
        before <= t &&
        t <= after,
      `${before} <= ${lines[2]} <= ${after}?\n${shown(r)}`
    )
  }

  // getRandomValues: two draws in a run differ, two runs differ, and each draw
  // is 32 bytes of hex. The Node run fills through the prelude's wrapper, which
  // is what a plain array needs there.
  const randomExe = buildCaseIn(osDir, "os_random")
  if (randomExe !== null) {
    const draws = [
      osNative(randomExe, ["print"]),
      osNative(randomExe, ["print"]),
      runCaseUnderPrelude("os_random", ["print"]),
    ]
    const hexes = draws.map((r) => linesOf(r).slice(4))
    const all = hexes.flat()
    check(
      "os_random: every draw is 32 bytes, and no two draws agree across two native runs and one under the prelude",
      draws.every((r) => r.status === 0 && linesOf(r).slice(0, 4).join(" ") === "true 0 65536 4") &&
        hexes.every((h) => h.length === 2) &&
        all.every((h) => /^[0-9a-f]{64}$/.test(h)) &&
        new Set(all).size === all.length,
      draws.map(shown).join("\n")
    )
  }

  // The limit: 65,536 bytes fill, 65,537 panic, with the same words and status
  // under the prelude.
  const limitExe = buildCaseIn(osDir, "os_random_limit")
  if (limitExe !== null) {
    const words = "crypto.getRandomValues: 65537 bytes asked for, and one call fills at most 65536"
    for (const [side, r] of [
      ["natively", osNative(limitExe, [])],
      ["under the prelude", runCaseUnderPrelude("os_random_limit", [])],
    ]) {
      check(
        `os_random_limit: 65,537 bytes panic ${side}, after 65,536 filled`,
        r.status === 1 && r.stdout === "65536 filled\n" && r.stderr.includes(words),
        shown(r)
      )
    }
  }

  // statMtimeSync: a file whose mtime is set to a fraction of a millisecond, read
  // natively and under the prelude, and both held to `fs.statSync().mtimeMs`
  // printed as JavaScript prints it. The fraction is the point: a runtime that
  // truncated to milliseconds, or computed in another order, prints other digits.
  const mtimeExe = buildCaseIn(osDir, "os_mtime")
  if (mtimeExe !== null) {
    const file = path.join(osDir, "mtime.txt")
    fs.writeFileSync(file, "x")
    fs.utimesSync(file, 1700000000, 1700000000.1234567)
    const want = fs.statSync(file).mtimeMs
    check(
      "os_mtime: the fixture's mtime has a sub-millisecond fraction to read back",
      !Number.isInteger(want),
      `mtimeMs ${want}`
    )
    for (const [side, r] of [
      ["natively", osNative(mtimeExe, [file])],
      ["under the prelude", runCaseUnderPrelude("os_mtime", [file])],
    ]) {
      check(
        `os_mtime: statMtimeSync ${side} prints Node's mtimeMs, ${want}`,
        r.status === 0 && linesOf(r).join(" ") === `true true ${want}`,
        shown(r)
      )
    }
  }

  // The signal descriptor. The program prints `ready` once its descriptor is
  // made, and only then is the first signal sent, so nothing races the
  // `signalFd()` call; the second goes once the first has been read back. A lost
  // signal is a timeout and a SIGKILL, never a hang.
  const signalRun = (exe, first, second) =>
    new Promise((resolve) => {
      const child = spawn(exe, [], { cwd: root, stdio: ["ignore", "pipe", "pipe"] })
      let out = ""
      let err = ""
      let sent = 0
      let timedOut = false
      const timer = setTimeout(() => {
        timedOut = true
        child.kill("SIGKILL")
      }, 10000)
      child.stdout.on("data", (chunk) => {
        out += chunk
        const after = out.split("ready\n")
        if (sent === 0 && after.length > 1) {
          sent = 1
          child.kill(first)
        } else if (sent === 1 && after[1].includes("\n")) {
          sent = 2
          child.kill(second)
        }
      })
      child.stderr.on("data", (chunk) => {
        err += chunk
      })
      child.on("close", (code, signal) => {
        clearTimeout(timer)
        resolve({ code, signal, out, err, timedOut })
      })
    })
  for (const [name, first, second, want] of [
    ["os_signal", "SIGTERM", "SIGINT", "-1\ntrue\n-1\n143\nready\n15\n2\n"],
    ["os_signal_import", "SIGINT", "SIGTERM", "ready\n2\n15\n"],
  ]) {
    const exe = buildCaseIn(osDir, name)
    if (exe === null) {
      continue
    }
    const r = await signalRun(exe, first, second)
    check(
      `${name}: ${first} then ${second} are read back as their numbers, and the program exits 0`,
      !r.timedOut && r.code === 0 && r.out === want,
      `${r.timedOut ? "timed out after 10 s: a signal was lost\n" : ""}exit ${r.code} signal ${r.signal}\n` +
        `stdout: ${JSON.stringify(r.out)}\nwant:   ${JSON.stringify(want)}\nstderr: ${r.err}`
    )
  }
  // No synchronous reading exists under Node (docs/wp33-round-trip.md), and the
  // prelude says so rather than answering something else.
  const loud = runCaseUnderPrelude("os_signal", [])
  check(
    "os_signal: under the prelude signalFd fails loudly rather than answering",
    loud.status !== 0 && loud.stderr.includes("signalFd has no synchronous reading under Node"),
    shown(loud)
  )

  // WP34 N12: the core count and the memory size, natively and under the prelude.
  // Natively the count is the smallest of the online cores, the affinity mask and
  // the cgroup quota, so it is at most Node's `os.availableParallelism()` (the
  // mask alone); a positive NISH_NUM_THREADS caps it on both sides. The memory
  // size is the kernel's, the number `os.totalmem()` reads.
  const cpuExe = buildCaseIn(osDir, "os_cpu")
  const memoryExe = buildCaseIn(osDir, "os_memory")
  const nodeCores = os.availableParallelism()
  for (const [side, cpu, memory] of [
    ["natively", (args, env) => spawnSync(cpuExe, args, { cwd: root, encoding: "utf8", env }), (args) => osNative(memoryExe, args)],
    [
      "under the prelude",
      (args, env) => {
        const saved = process.env.NISH_NUM_THREADS
        process.env.NISH_NUM_THREADS = env.NISH_NUM_THREADS ?? ""
        const r = runCaseUnderPrelude("os_cpu", args)
        process.env.NISH_NUM_THREADS = saved ?? ""
        if (saved === undefined) {
          delete process.env.NISH_NUM_THREADS
        }
        return r
      },
      (args) => runCaseUnderPrelude("os_memory", args),
    ],
  ]) {
    if (cpuExe === null || memoryExe === null) {
      break
    }
    const unset = { ...process.env }
    delete unset.NISH_NUM_THREADS
    const free = cpu(["print"], unset)
    const cores = Number(linesOf(free)[1])
    check(
      `os_cpu: availableParallelism() ${side} is at least 1 and at most Node's ${nodeCores}`,
      free.status === 0 && linesOf(free)[0] === "true" && Number.isInteger(cores) && cores >= 1 && cores <= nodeCores,
      shown(free)
    )
    const capped = cpu(["print"], { ...unset, NISH_NUM_THREADS: "1" })
    check(
      `os_cpu: availableParallelism() ${side} is 1 under NISH_NUM_THREADS=1`,
      capped.status === 0 && linesOf(capped).join(" ") === "true 1",
      shown(capped)
    )
    const m = memory(["print"])
    check(
      `os_memory: totalMemory() ${side} is Node's os.totalmem(), ${os.totalmem()}`,
      m.status === 0 && linesOf(m).join(" ") === `true ${os.totalmem()}`,
      shown(m)
    )
  }

  // spawn, kill and waitPid under the prelude. A child is reaped by the event
  // loop, which a synchronous wait never returns to, so `spawn` and `waitPid`
  // fail loudly rather than answering; `kill` has a synchronous reading and
  // answers what runtime-os.c answers, -3 for a pid no process has and -22 for a
  // signal outside 0, 2, 9 and 15.
  const loudSpawn = runCaseUnderPrelude("os_spawn", [])
  check(
    "os_spawn: under the prelude spawn fails loudly rather than answering",
    loudSpawn.status !== 0 && loudSpawn.stderr.includes("`spawn` has no synchronous reading under Node"),
    shown(loudSpawn)
  )
  const reaper = path.join(osDir, "reaper.ts")
  fs.writeFileSync(
    reaper,
    "export const main = (): number => {\n  console.log(kill(2147483647, 0));\n  console.log(kill(1, 7));\n  console.log(kill(-1, 15));\n  console.log(waitPid(-1, 1)[0]);\n  return 0;\n};\n"
  )
  const reaped = runUnderPrelude(reaper, [])
  check(
    "waitPid: under the prelude kill answers -3 and -22, and waitPid then fails loudly rather than answering",
    reaped.status !== 0 &&
      reaped.stdout === "-3\n-22\n-22\n" &&
      reaped.stderr.includes("`waitPid` has no synchronous reading under Node"),
    shown(reaped)
  )
}

// A socket program of the `net_` blocks, run with `args`: `onChunk(out, child)` is
// called with everything it has printed so far each time it prints, and the answer
// comes once it exits, or once it has been killed after 10 s.
const runWatched = (exe, args, onChunk) =>
  new Promise((resolve) => {
    const child = spawn(exe, args, { cwd: root, stdio: ["ignore", "pipe", "pipe"] })
    let out = ""
    let err = ""
    let timedOut = false
    const timer = setTimeout(() => {
      timedOut = true
      child.kill("SIGKILL")
    }, 10000)
    child.stdout.on("data", (chunk) => {
      out += chunk
      onChunk(out, child)
    })
    child.stderr.on("data", (chunk) => {
      err += chunk
    })
    child.on("close", (code, signal) => {
      clearTimeout(timer)
      resolve({ code, signal, out, err, timedOut })
    })
  })

// `runWatched`, with `onPort(port)` called once the program prints `port <n>`; the
// answer waits for that promise as well as the exit. A program that prints no port
// is simply run, with `results` empty.
const runWithPort = async (exe, args, onPort) => {
  let talks = null
  const r = await runWatched(exe, args, (out) => {
    const port = /^port (\d+)\n/.exec(out)
    if (talks === null && port !== null) {
      talks = onPort(Number(port[1]))
    }
  })
  return { ...r, results: await (talks ?? Promise.resolve([])) }
}

// ---- `nish:net`, against Node's sockets (WP34 N5) ---------------------------------
//
// What a golden cannot say about the sockets, because the other end is the
// world's: `tests/cases/net_tcp_echo` listens, prints its port and echoes, and
// Node is the peer that connects, sends and reads the echo back. The program
// also measures the arena around both connections, which is the pass scope of
// its echo loop at work, and prints `flat` when the second, busy connection
// moved it no further than the first. The section-GC check here is the other
// half of the unit's budget: a program that calls no `nish:net` function links
// none of runtime-net.c.
if (!only || "net_tcp".includes(only)) {
  const netDir = path.join(buildDir, "net")
  fs.rmSync(netDir, { recursive: true, force: true })
  fs.mkdirSync(netDir, { recursive: true })

  // One connection that sends `messages` lines, each once the one before it has
  // come back, then ends its side; true when every byte came back in order.
  const talk = (port, messages) =>
    new Promise((resolve) => {
      const socket = net.connect(port, "127.0.0.1")
      let sent = ""
      let got = ""
      let next = 0
      const send = () => {
        if (next === messages) {
          socket.end()
          return
        }
        const line = `message ${next}\n`
        next++
        sent += line
        socket.write(line)
      }
      socket.on("connect", send)
      socket.on("data", (chunk) => {
        got += chunk
        if (got.length === sent.length) {
          send()
        }
      })
      socket.on("error", (e) => {
        got += `<${e.code}>`
      })
      socket.on("close", () => resolve(next === messages && got === sent))
    })
  const echoRun = (exe, rounds) =>
    runWithPort(exe, [], async (port) => {
      const results = []
      for (const messages of rounds) {
        results.push(await talk(port, messages))
      }
      return results
    })

  const echoExe = buildCaseIn(netDir, "net_tcp_echo")
  if (echoExe !== null) {
    const rounds = [1, 200]
    const echoed = (messages) => Array.from({ length: messages }, (_, i) => `message ${i}\n`).join("").length
    const want =
      rounds.map((m) => `peer 127.0.0.1\nechoed ${echoed(m)} bytes\nclosed 0\n`).join("") + "flat\n"
    const r = await echoRun(echoExe, rounds)
    const body = r.out.replace(/^port \d+\n/, "")
    check(
      "net_tcp_echo: Node's two connections come back byte for byte, both close cleanly, the arena stays flat, and the program exits 0",
      !r.timedOut && r.code === 0 && body === want && r.results.every((ok) => ok),
      `${r.timedOut ? "timed out after 10 s\n" : ""}exit ${r.code} signal ${r.signal}\n` +
        `connections: ${JSON.stringify(r.results)}\nstdout: ${JSON.stringify(r.out)}\n` +
        `want:   ${JSON.stringify(`port <n>\n${want}`)}\nstderr: ${r.err}`
    )
  }

  // No synchronous reading exists under Node (docs/wp33-round-trip.md), and the
  // prelude says so, naming the call, rather than answering -11 forever.
  const loud = runCaseUnderPrelude("net_tcp_calls", [])
  check(
    "net_tcp_calls: under the prelude netAddress fails loudly rather than answering",
    loud.status !== 0 && loud.stderr.includes("`netAddress` has no synchronous reading under Node"),
    shown(loud)
  )

  // Section GC keeps runtime-net.c out of a program that calls none of it. The
  // link is the speed profile's `--gc-sections` without its LTO, so no call is
  // inlined away (`-dead_strip`, its Darwin counterpart, there), and `nm` names
  // the functions the program still defines; the echo, which calls six of the
  // eight, is the control that shows a kept one is still there and that the
  // link drops anything at all.
  {
    // The runtime objects are built once for both links, with the sections split
    // so that each function can be dropped on its own.
    const rt = runtimeObjects(["-ffunction-sections", "-fdata-sections"])
    const exported = [
      "nish_net_address",
      "nish_net_local_port",
      "nish_tcp_listen",
      "nish_tcp_listen_flags",
      "nish_tcp_accept",
      "nish_net_read",
      "nish_net_write",
      "nish_net_shutdown",
      "nish_net_close",
      "nish_tcp_connect",
      "nish_connect_result",
      "nish_udp_bind",
      "nish_udp_send_to",
      "nish_udp_recv_from",
      "nish_poll_create",
      "nish_poll_add",
      "nish_poll_modify",
      "nish_poll_remove",
      "nish_poll_wait",
    ]
    const used = [
      "nish_net_local_port",
      "nish_tcp_listen",
      "nish_tcp_accept",
      "nish_net_read",
      "nish_net_write",
    ]
    const collected = (name, ll) => {
      const cc =
        rt.error === null
          ? spawnSync(
              "clang",
              [
                "-Wno-override-module",
                "-O2",
                "-ffunction-sections",
                "-fdata-sections",
                process.platform === "darwin" ? "-Wl,-dead_strip" : "-Wl,--gc-sections",
                ll,
                ...rt.objects,
                "-lm",
                "-o",
                path.join(netDir, `${name}.gc`),
              ],
              { cwd: root, encoding: "utf8" }
            )
          : { status: 1, stderr: rt.error }
      // Mach-O prefixes every C symbol with an underscore.
      const nm =
        cc.status === 0
          ? spawnSync(
              ["llvm-nm", "llvm-nm-18"].find(has) ?? "llvm-nm",
              ["-g", path.join(netDir, `${name}.gc`)],
              { encoding: "utf8" }
            )
          : null
      const defined = new Set(
        [...String(nm?.stdout ?? "").matchAll(/ T _?(nish_(?:net|tcp|udp|poll|connect)_\w+)$/gm)].map(
          (m) => m[1]
        )
      )
      const removed = exported.filter((f) => !defined.has(f))
      return { ok: cc.status === 0 && nm?.status === 0, removed, why: `${cc.stderr}${nm?.stderr ?? ""}` }
    }
    const quietLl = path.join(netDir, "net_quiet.ll")
    const quietTs = path.join(netDir, "net_quiet.ts")
    fs.writeFileSync(
      quietTs,
      'export const main = (): number => {\n  console.log("no sockets");\n  return 0;\n};\n'
    )
    const compiled = spawnSync(NISH, [quietTs, "-o", quietLl], { cwd: root, encoding: "utf8" })
    const none =
      compiled.status === 0
        ? collected("net_quiet", quietLl)
        : { ok: false, removed: [], why: compiled.stderr }
    // The echo's IR is the one `buildCaseIn` wrote above.
    const echo = collected("net_tcp_echo", path.join(netDir, "net_tcp_echo.ll"))
    check(
      "net_tcp: section GC drops every function of runtime-net.c from a program that calls none, and keeps the ones the echo calls",
      none.ok &&
        exported.every((f) => none.removed.includes(f)) &&
        echo.ok &&
        echo.removed.includes("nish_net_address") &&
        used.every((f) => !echo.removed.includes(f)),
      `dropped without nish:net: ${none.removed.join(" ")}\ndropped from the echo: ${echo.removed.join(" ")}\n` +
        `${none.why}${echo.why}`
    )
  }
}

// ---- `nish:net`'s client half, against its own server (WP34 N5, #357) -----------
//
// `tests/cases/net_tcp_connect` is a Nish client and a Nish server in one loop:
// the client's `tcpConnect` completes when the loop reports it writable, two
// exchanges of 1 and 200 messages come back byte for byte with the arena flat,
// and a port nobody listens on is refused, -111, read once. No peer is needed,
// so it could be an `.out`; it runs here instead because every step waits on
// the loop, and a lost wake must be a timeout and a SIGKILL, never a hung suite.
if (!only || "net_tcp_connect".includes(only)) {
  const netDir = path.join(buildDir, "net-connect")
  fs.rmSync(netDir, { recursive: true, force: true })
  fs.mkdirSync(netDir, { recursive: true })

  const connectExe = buildCaseIn(netDir, "net_tcp_connect")
  if (connectExe !== null) {
    const want =
      "short -22\nnot a descriptor -9\n" +
      "peer 127.0.0.1, end of stream 0\n".repeat(2) +
      "one: 1 intact, many: 200 intact\nflat\nrefused -111\nread once 0\n"
    // Nothing to answer as the output arrives: the program is its own peer.
    const r = await runWatched(connectExe, [], () => undefined)
    check(
      "net_tcp_connect: a Nish client connects through the loop to a Nish server, both exchanges come back intact, the arena stays flat, a closed port is refused once, and the program exits 0",
      !r.timedOut && r.code === 0 && r.out === want,
      `${r.timedOut ? "timed out after 10 s: a wake was lost\n" : ""}exit ${r.code} signal ${r.signal}\n` +
        `stdout: ${JSON.stringify(r.out)}\nwant:   ${JSON.stringify(want)}\nstderr: ${r.err}`
    )
  }

  const loud = runCaseUnderPrelude("net_tcp_connect", [])
  check(
    "net_tcp_connect: under the prelude tcpConnect fails loudly rather than answering",
    loud.status !== 0 && loud.stderr.includes("`tcpConnect` has no synchronous reading under Node"),
    shown(loud)
  )

  // `net_tcp_reuseport` imports from `nish:net`, a scheme Node's loader refuses
  // before any call runs, so the prelude is asked of the global instead.
  const flagsDir = path.join(buildDir, "net-prelude")
  fs.mkdirSync(flagsDir, { recursive: true })
  const flagsEntry = path.join(flagsDir, "listen-flags.ts")
  fs.writeFileSync(flagsEntry, 'export const main = (): number => tcpListenFlags("127.0.0.1", 0, 4, 1);\n')
  const loudFlags = runUnderPrelude(flagsEntry, [])
  check(
    "net_tcp_reuseport: under the prelude tcpListenFlags fails loudly rather than answering",
    loudFlags.status !== 0 &&
      loudFlags.stderr.includes("`tcpListenFlags` has no synchronous reading under Node"),
    shown(loudFlags)
  )
}

// ---- `nish:net` UDP, against Node's `dgram` (WP34 N5) -----------------------------
//
// `tests/cases/net_udp_echo` binds, prints its port and echoes each datagram to
// its sender; Node sends two rounds, one datagram at a time, and requires each
// back byte for byte, and the program prints `flat` when the second, busy round
// moved the arena no further than the first. `net_udp_offload` is the half only
// Linux has: Node counts the datagrams one segmented send becomes, and the
// program reports what one GRO receive returned and the ECN bits that arrived.
// Elsewhere those calls answer -95, which is the documented behaviour rather
// than a gap, so the check there requires each -95, and that none of those
// calls put a datagram on the wire while a plain send still does.
if (!only || "net_udp".includes(only)) {
  const netDir = path.join(buildDir, "net-udp")
  fs.rmSync(netDir, { recursive: true, force: true })
  fs.mkdirSync(netDir, { recursive: true })

  // One round: `count` datagrams, each sent once the one before it has come
  // back, then the empty datagram that ends the round; true when every one
  // came back unchanged.
  const datagram = (i) => `datagram ${i} ${"x".repeat(i % 97)}`
  const udpRound = (socket, port, count) =>
    new Promise((resolve) => {
      let next = 0
      let ok = true
      let sent = null
      const onMessage = (message) => {
        ok = ok && message.equals(sent)
        next++
        sendNext()
      }
      const sendNext = () => {
        if (next === count) {
          socket.off("message", onMessage)
          socket.send(Buffer.alloc(0), port, "127.0.0.1", () => resolve(ok))
          return
        }
        sent = Buffer.from(datagram(next))
        socket.send(sent, port, "127.0.0.1")
      }
      socket.on("message", onMessage)
      sendNext()
    })

  const echoExe = buildCaseIn(netDir, "net_udp_echo")
  if (echoExe !== null) {
    const rounds = [1, 200]
    const bytes = (count) =>
      Array.from({ length: count }, (_, i) => datagram(i).length).reduce((a, b) => a + b, 0)
    const want = rounds.map((c) => `echoed ${c} datagrams, ${bytes(c)} bytes\n`).join("") + "flat\n"
    const socket = dgram.createSocket("udp4")
    await new Promise((resolve) => socket.bind(0, "127.0.0.1", resolve))
    const r = await runWithPort(echoExe, [], async (port) => {
      const results = []
      for (const count of rounds) {
        results.push(await udpRound(socket, port, count))
      }
      return results
    })
    socket.close()
    const body = r.out.replace(/^port \d+\n/, "")
    check(
      "net_udp_echo: Node's datagrams come back byte for byte, both rounds end on an empty datagram, the arena stays flat, and the program exits 0",
      !r.timedOut &&
        r.code === 0 &&
        body === want &&
        r.results.length === rounds.length &&
        r.results.every((ok) => ok),
      `${r.timedOut ? "timed out after 10 s\n" : ""}exit ${r.code} signal ${r.signal}\n` +
        `rounds: ${JSON.stringify(r.results)}\nstdout: ${JSON.stringify(r.out)}\n` +
        `want:   ${JSON.stringify(`port <n>\n${want}`)}\nstderr: ${r.err}`
    )
  }

  const loud = runCaseUnderPrelude("net_udp_calls", [])
  check(
    "net_udp_calls: under the prelude udpBind fails loudly rather than answering",
    loud.status !== 0 && loud.stderr.includes("`udpBind` has no synchronous reading under Node"),
    shown(loud)
  )

  if (process.platform !== "linux") {
    // UDP_SEGMENT, UDP_GRO and the ECN control messages are Linux's, and the
    // runtime answers -95 for them here (docs/LANGUAGE.md): the program prints
    // each answer, and only its last, plain send reaches Node.
    const offloadExe = buildCaseIn(netDir, "net_udp_offload")
    if (offloadExe !== null) {
      const socket = dgram.createSocket("udp4")
      const arrived = []
      socket.on("message", (message) => arrived.push(message))
      await new Promise((resolve) => socket.bind(0, "127.0.0.1", resolve))
      const r = await runWithPort(offloadExe, [String(socket.address().port)], async () => [])
      // Darwin's loopback delivers asynchronously; give the plain datagram time to land.
      for (let wait = 0; wait < 40 && arrived.length === 0; wait++) {
        await new Promise((resolve) => setTimeout(resolve, 50))
      }
      socket.close()
      const answers =
        "gso sent -95\ngro bind -95\necn 1 sent -95\necn 2 sent -95\necn 3 sent -95\nplain sent 16\n"
      const pattern = Buffer.from(Array.from({ length: 16 }, (_, i) => i))
      check(
        `net_udp_offload: on ${process.platform} GSO, the GRO bind and every ECN mark answer -95 and send nothing, and a plain udpSendTo still arrives`,
        r.code === 0 && r.out === answers && arrived.length === 1 && arrived[0].equals(pattern),
        `${r.timedOut ? "timed out after 10 s\n" : ""}exit ${r.code} signal ${r.signal}\n` +
          `datagrams: ${JSON.stringify(arrived.map((m) => m.length))}\n` +
          `stdout: ${JSON.stringify(r.out)}\nwant: ${JSON.stringify(answers)}\nstderr: ${r.err}`
      )
    }
  } else {
    const offloadExe = buildCaseIn(netDir, "net_udp_offload")
    if (offloadExe !== null) {
      const socket = dgram.createSocket("udp4")
      const arrived = []
      let allArrived = null
      const four = new Promise((resolve) => {
        allArrived = resolve
      })
      socket.on("message", (message) => {
        arrived.push(message)
        if (arrived.length === 4) {
          allArrived()
        }
      })
      await new Promise((resolve) => socket.bind(0, "127.0.0.1", resolve))
      const r = await runWithPort(offloadExe, [String(socket.address().port)], async () => [])
      // The four datagrams were queued before the program printed a line, so
      // they are Node's to read; wait for the event loop to deliver them.
      let late = null
      await Promise.race([four, new Promise((resolve) => (late = setTimeout(resolve, 2000)))])
      clearTimeout(late)
      socket.close()
      const pattern = Buffer.from(Array.from({ length: 4800 }, (_, i) => i % 251))
      const whole = Buffer.concat(arrived)
      check(
        "net_udp_offload: one udpSendTo of 4,800 bytes with segment 1200 arrives at Node as four datagrams of 1,200",
        r.code === 0 &&
          r.out.startsWith("gso sent 4800\n") &&
          arrived.length === 4 &&
          arrived.every((m) => m.length === 1200) &&
          whole.equals(pattern),
        `${r.timedOut ? "timed out after 10 s\n" : ""}exit ${r.code} signal ${r.signal}\n` +
          `datagrams: ${JSON.stringify(arrived.map((m) => m.length))}\n` +
          `stdout: ${JSON.stringify(r.out)}\nstderr: ${r.err}`
      )
      const gro = /^gro (\d+) bytes, segment (\d+), intact true$/m.exec(r.out)
      check(
        "net_udp_offload: one udpRecvFrom on a socket bound with UDP_GRO returns at least two datagrams with meta[0] == 1200, and one without it a single datagram with meta[0] == 0",
        r.code === 0 &&
          gro !== null &&
          Number(gro[1]) >= 2400 &&
          Number(gro[1]) % 1200 === 0 &&
          gro[2] === "1200" &&
          r.out.includes("\nplain 1200 bytes, segment 0, intact true\n"),
        `exit ${r.code} signal ${r.signal}\nstdout: ${JSON.stringify(r.out)}\nstderr: ${r.err}`
      )
      const ecn = [1, 2, 3, 0].map((e) => `ecn ${e}: 16 bytes, ecn ${e}\n`).join("")
      check(
        "net_udp_offload: the ECN bits udpSendTo marks (1, 2, 3 and none) arrive in the receiver's meta[1]",
        r.code === 0 && r.out.endsWith(ecn),
        `exit ${r.code} signal ${r.signal}\nstdout: ${JSON.stringify(r.out)}\nwant the end: ${JSON.stringify(ecn)}\nstderr: ${r.err}`
      )
    }
  }
}

// ---- `nish:net` over both families, against Node (#355) ---------------------------
//
// Every other `net_` program binds 127.0.0.1, and a container without IPv6
// turns `"::"` into `0.0.0.0`, so this is the one that reaches the dual-stack
// code: `tests/cases/net_dual_stack` listens on `"::"` and Node connects over
// 127.0.0.1 and then ::1, and the program must name each peer in its address
// form, with Node's own port, and echo both. Then its `"::"` UDP socket marks a
// datagram to itself with each ECN value over each family, `IP_TOS` and then
// `IPV6_TCLASS`, and reads the mark back from `meta[1]`. A host whose `::1`
// cannot be listened on cannot run any of that, so the check prints why and
// passes rather than counting a skip: the dual-stack path is not missing
// there, it is the documented fallback.
if (!only || "net_dual_stack".includes(only)) {
  const netDir = path.join(buildDir, "net-dual")
  fs.rmSync(netDir, { recursive: true, force: true })
  fs.mkdirSync(netDir, { recursive: true })

  // What a failed listen on ::1 means. Only two codes say the host has no IPv6
  // loopback: EAFNOSUPPORT, a kernel without IPv6, and EADDRNOTAVAIL, IPv6
  // without ::1 on lo (`disable_ipv6`). Any other code (EMFILE, EACCES,
  // ENOBUFS, ...) is a fault on a host that may well have IPv6, so it fails
  // the check rather than passing it as not applicable.
  const ipv6Verdict = (code) => {
    if (code === null) {
      return "run"
    }
    return code === "EAFNOSUPPORT" || code === "EADDRNOTAVAIL" ? "absent" : "fault"
  }
  const verdicts = {
    EAFNOSUPPORT: "absent",
    EADDRNOTAVAIL: "absent",
    EMFILE: "fault",
    EACCES: "fault",
    ENOBUFS: "fault",
  }
  const wrong = Object.keys(verdicts).filter((code) => ipv6Verdict(code) !== verdicts[code])
  check(
    "net_dual_stack: the IPv6 probe passes only EAFNOSUPPORT and EADDRNOTAVAIL as a host without IPv6, and fails EMFILE, EACCES and ENOBUFS",
    wrong.length === 0 && ipv6Verdict(null) === "run",
    `misjudged: ${wrong.map((code) => `${code} as ${ipv6Verdict(code)}`).join(", ")}`
  )

  // The code a listen on ::1 fails with here, or null when it succeeds.
  const probeCode = await new Promise((resolve) => {
    const probe = net.createServer()
    probe.once("error", (e) => resolve(String(e.code)))
    probe.listen(0, "::1", () => probe.close(() => resolve(null)))
  })
  const ipv6 = ipv6Verdict(probeCode)

  // One connection to `host` that sends a line and waits for it back, then ends
  // its side; its local port, which the program must report, and whether the
  // line came back unchanged.
  const talkOver = (port, host) =>
    new Promise((resolve) => {
      const line = `over ${host}\n`
      const socket = net.connect(port, host)
      let got = ""
      let localPort = -1
      socket.on("connect", () => {
        localPort = socket.localPort
        socket.write(line)
      })
      socket.on("data", (chunk) => {
        got += chunk
        if (got.length === line.length) {
          socket.end()
        }
      })
      socket.on("error", (e) => {
        got += `<${e.code}>`
      })
      socket.on("close", () => resolve({ host, localPort, echoed: got === line, bytes: line.length }))
    })

  const dualExe = buildCaseIn(netDir, "net_dual_stack")
  if (ipv6 === "fault") {
    check(
      `net_dual_stack: listening on ::1 answers ${probeCode}, which is a fault rather than a host without IPv6`,
      false,
      "only EAFNOSUPPORT and EADDRNOTAVAIL mean there is no IPv6 loopback to test"
    )
  } else if (ipv6 === "absent") {
    console.log(
      `      net_dual_stack does not run here: listening on ::1 answers ${probeCode}, so "::" is IPv4's 0.0.0.0 on this host (docs/LANGUAGE.md); CI's ubuntu-latest has IPv6 and runs it`
    )
    check(
      `net_dual_stack: not applicable on a host without IPv6 (listening on ::1 answers ${probeCode})`,
      true,
      ""
    )
  } else if (dualExe !== null) {
    const r = await runWithPort(dualExe, [], async (port) => [
      await talkOver(port, "127.0.0.1"),
      await talkOver(port, "::1"),
    ])
    // Off Linux a send with a mark answers -95 and the mark is never read back.
    const udp = ["127.0.0.1", "::1"]
      .flatMap((host) =>
        [1, 2, 3, 0].map((ecn) =>
          process.platform !== "linux" && ecn > 0
            ? `udp to ${host}, ecn ${ecn}: sent -95\n`
            : `udp to ${host}, ecn ${ecn}: 8 bytes from ${host}, ecn ${ecn}\n`
        )
      )
      .join("")
    const want =
      r.results.map((t) => `peer ${t.host} port ${t.localPort}\nechoed ${t.bytes} bytes\n`).join("") + udp
    const body = r.out.replace(/^port \d+\n/, "")
    check(
      "net_dual_stack: a listener on :: accepts Node over 127.0.0.1 as the mapped form and over ::1 as ::1, with each peer's port, echoes both, and its :: UDP socket reads back every ECN mark over IPv4 and IPv6",
      !r.timedOut &&
        r.code === 0 &&
        r.results.length === 2 &&
        r.results.every((t) => t.echoed) &&
        body === want,
      `${r.timedOut ? "timed out after 10 s\n" : ""}exit ${r.code} signal ${r.signal}\n` +
        `connections: ${JSON.stringify(r.results)}\nstdout: ${JSON.stringify(r.out)}\n` +
        `want:   ${JSON.stringify(`port <n>\n${want}`)}\nstderr: ${r.err}`
    )
  }
}

// ---- The `nish:net` readiness loop, against Node and a signal (WP34 N5) ----------
//
// `tests/cases/net_loop_two` watches two UDP sockets and its `signalFd()` in one
// loop and prints both ports. Node writes to one socket, waits for the line that
// names the socket that woke, and only then writes to the other, so which wakes
// first is decided by Node rather than by timing: b then a, then a then b. Then it
// sends SIGTERM, which the loop wakes on through the signal descriptor, and the
// program exits 0 having printed `flat` when the arena stood where it did at the
// top of every pass. Nothing sleeps; a lost wake is a timeout and a SIGKILL,
// never a hang.
if (!only || "net_loop".includes(only)) {
  const netDir = path.join(buildDir, "net-loop")
  fs.rmSync(netDir, { recursive: true, force: true })
  fs.mkdirSync(netDir, { recursive: true })

  // The next action each time another `woke` line arrives: a datagram to the next
  // socket in `order`, or SIGTERM once every one has woken the loop.
  const loopRun = async (exe, order) => {
    const socket = dgram.createSocket("udp4")
    // How many `woke` lines the last action answered; -1 before the ports arrive.
    let acted = -1
    const r = await runWatched(exe, [], (out, child) => {
      const m = /^ports (\d+) (\d+)\n/.exec(out)
      const woke = out.split("\n").filter((line) => line.startsWith("woke ")).length
      if (m === null || woke === acted) {
        return
      }
      acted = woke
      if (woke < order.length) {
        const which = order[woke]
        socket.send(Buffer.from(`to ${which}`), Number(which === "a" ? m[1] : m[2]), "127.0.0.1")
      } else {
        child.kill("SIGTERM")
      }
    })
    socket.close()
    return r
  }

  const loopExe = buildCaseIn(netDir, "net_loop_two")
  if (loopExe !== null) {
    for (const order of [
      ["b", "a"],
      ["a", "b"],
    ]) {
      const want = `${order.map((w) => `woke ${w}: 4 bytes, events 1\n`).join("")}signal 15\nflat\n`
      const r = await loopRun(loopExe, order)
      const body = r.out.replace(/^ports \d+ \d+\n/, "")
      check(
        `net_loop_two: the loop wakes on ${order[0]} and then ${order[1]} as Node writes to them, then on SIGTERM through signalFd, the arena stays flat, and the program exits 0`,
        !r.timedOut && r.code === 0 && body === want,
        `${r.timedOut ? "timed out after 10 s: a wake was lost\n" : ""}exit ${r.code} signal ${r.signal}\n` +
          `stdout: ${JSON.stringify(r.out)}\nwant:   ${JSON.stringify(`ports <a> <b>\n${want}`)}\nstderr: ${r.err}`
      )
    }
  }

  const loud = runCaseUnderPrelude("net_loop_calls", [])
  check(
    "net_loop_calls: under the prelude pollCreate fails loudly rather than answering",
    loud.status !== 0 && loud.stderr.includes("`pollCreate` has no synchronous reading under Node"),
    shown(loud)
  )
}

// ---- `nish/net/tls-tcp`, against openssl s_client and Node's TLS (WP34 T2) -------
//
// What the Nish client in `tests/link/net_tls_record_tcp` cannot say: that a
// TLS 1.3 stack somebody else wrote completes a handshake with the carrier and
// moves data both ways. The same program run as `serve 4` listens, prints its
// port and serves four connections, one at a time: openssl s_client under each
// of the three suites — the first sending `K`, a KeyUpdate asking for one
// back, before its line — each echoed, and an HTTPS GET from Node, answered over
// the ALPN protocol it negotiates. Every client must finish with what it sent
// back, and the server must print one line per connection with the suite, ALPN
// and SNI it negotiated. The GET is Node's rather than curl's because it pins
// its suite, and macOS's curl, built on LibreSSL 3.3, has no `--tls13-ciphers`;
// Node carries its own OpenSSL on every platform. openssl is on CI's runners,
// so a missing one is a failure here rather than a skip.
if (!only || "net_tls_tcp".includes(only)) {
  const tlsDir = path.join(buildDir, "net-tls")
  fs.rmSync(tlsDir, { recursive: true, force: true })
  fs.mkdirSync(tlsDir, { recursive: true })
  const exe = path.join(tlsDir, "app")
  const built = spawnSync(
    NISH,
    [
      path.join(root, "tests", "link", "net_tls_record_tcp", "main.ts"),
      "-o",
      tlsDir + path.sep,
      "--link",
      exe,
    ],
    { cwd: root, encoding: "utf8" }
  )
  // The third-party client, by name; `has` asks the PATH for it.
  const openssl = "openssl"
  if (
    check("net_tls_tcp: the server links", built.status === 0, String(built.stderr)) &&
    check("net_tls_tcp: openssl is on PATH (CI's runners have it)", has(openssl), "missing: openssl")
  ) {
    const server = spawn(exe, ["serve", "4"], { cwd: root, stdio: ["ignore", "pipe", "pipe"] })
    let served = ""
    let serverErr = ""
    const serverTimer = setTimeout(() => server.kill("SIGKILL"), 60000)
    const serverDone = new Promise((resolve) =>
      server.on("close", (code, signal) => {
        clearTimeout(serverTimer)
        resolve({ code, signal })
      })
    )
    server.stderr.on("data", (chunk) => {
      serverErr += chunk
    })
    const port = await new Promise((resolve) => {
      server.stdout.on("data", (chunk) => {
        served += chunk
        const m = /^port (\d+)\n/.exec(served)
        if (m !== null) {
          resolve(Number(m[1]))
        }
      })
      server.on("close", () => resolve(0))
    })

    // One s_client: each step waits for `text` on a stream, then writes
    // `send` to its stdin, or ends it when `send` is null. The answer says
    // whether every step was reached and how the client exited.
    const sClient = (args, steps) =>
      new Promise((resolve) => {
        const child = spawn(
          openssl,
          ["s_client", "-connect", `127.0.0.1:${port}`, "-tls1_3", "-servername", "localhost", ...args],
          { stdio: ["pipe", "pipe", "pipe"] }
        )
        const unread = { stdout: "", stderr: "" }
        let at = 0
        let all = ""
        const timer = setTimeout(() => child.kill("SIGKILL"), 15000)
        const advance = () => {
          while (at < steps.length) {
            const [stream, text, send] = steps[at]
            const i = unread[stream].indexOf(text)
            if (i < 0) {
              return
            }
            unread[stream] = unread[stream].slice(i + text.length)
            at++
            if (send === null) {
              child.stdin.end()
            } else {
              child.stdin.write(send)
            }
          }
        }
        child.stdout.on("data", (chunk) => {
          all += chunk
          unread.stdout += chunk
          advance()
        })
        child.stderr.on("data", (chunk) => {
          all += chunk
          unread.stderr += chunk
          advance()
        })
        child.on("close", (code, signal) => {
          clearTimeout(timer)
          resolve({ code, signal, reached: at === steps.length, all })
        })
      })
    // The handshake summary s_client prints ends with this line; it reads
    // stdin only after it.
    const summary = "Verify return code"
    const sessions = [
      [
        "TLS_AES_128_GCM_SHA256, with a KeyUpdate asking for one back first",
        ["-ciphersuites", "TLS_AES_128_GCM_SHA256"],
        [
          ["stdout", summary, "K\n"],
          ["stderr", "KEYUPDATE", "hello 128\n"],
          ["stdout", "hello 128\n", null],
        ],
      ],
      [
        "TLS_CHACHA20_POLY1305_SHA256",
        ["-ciphersuites", "TLS_CHACHA20_POLY1305_SHA256"],
        [
          ["stdout", summary, "hello chacha\n"],
          ["stdout", "hello chacha\n", null],
        ],
      ],
      [
        "TLS_AES_256_GCM_SHA384",
        ["-ciphersuites", "TLS_AES_256_GCM_SHA384"],
        [
          ["stdout", summary, "hello 256\n"],
          ["stdout", "hello 256\n", null],
        ],
      ],
    ]
    for (const [what, args, steps] of sessions) {
      const r = port > 0 ? await sClient(args, steps) : { code: null, signal: null, reached: false, all: "" }
      check(
        `net_tls_tcp: openssl s_client -tls1_3 under ${what}: the handshake completes, the line comes back, and it exits 0`,
        r.reached && r.code === 0,
        `exit ${r.code} signal ${r.signal}, every step reached: ${r.reached}\n${r.all.slice(-1500)}`
      )
    }
    // The suite is pinned, not preferred: `ciphers` naming one TLS 1.3 suite is
    // all the client offers, so a server that picked another would fail the
    // handshake rather than pass the check. The server's certificate is
    // self-signed, as it was under curl's `-k`.
    /** @type {{ error: string, status: number, suite: string, alpn: string | false, body: string }} */
    const got =
      port > 0
        ? await new Promise((resolve) => {
            const out = { error: "", status: 0, suite: "", alpn: false, body: "" }
            const req = https.get(
              {
                host: "127.0.0.1",
                port,
                path: "/",
                servername: "localhost",
                rejectUnauthorized: false,
                minVersion: "TLSv1.3",
                maxVersion: "TLSv1.3",
                ciphers: "TLS_AES_256_GCM_SHA384",
                // biome-ignore lint/style/useNamingConvention: Node's own option name
                ALPNProtocols: ["http/1.1"],
                agent: false,
                timeout: 15000,
              },
              (res) => {
                out.status = res.statusCode ?? 0
                out.suite = res.socket.getCipher().standardName
                out.alpn = res.socket.alpnProtocol
                res.setEncoding("utf8")
                res.on("data", (chunk) => {
                  out.body += chunk
                })
                res.on("end", () => resolve(out))
                res.on("error", (e) => resolve({ ...out, error: e.message }))
              }
            )
            req.on("timeout", () => req.destroy(new Error("timed out")))
            req.on("error", (e) => resolve({ ...out, error: e.message }))
          })
        : { error: "no port", status: 0, suite: "", alpn: false, body: "" }
    check(
      "net_tls_tcp: an HTTPS GET pinned to TLS_AES_256_GCM_SHA384 negotiates that suite and http/1.1, and reads the page",
      got.error === "" &&
        got.status === 200 &&
        got.suite === "TLS_AES_256_GCM_SHA384" &&
        got.alpn === "http/1.1" &&
        got.body === "hello from nish/net/tls-tcp\n",
      JSON.stringify(got)
    )
    const ended = await serverDone
    // 4865, 4867 and 4866 are TLS_AES_128_GCM_SHA256, TLS_CHACHA20_POLY1305_SHA256
    // and TLS_AES_256_GCM_SHA384; each s_client sent close_notify, and the GET,
    // which reads to the end of the answer, closed after the server did.
    const want =
      "closed: suite 4865 alpn - sni localhost sent 0 received -1 client-closed true\n" +
      "closed: suite 4867 alpn - sni localhost sent 0 received -1 client-closed true\n" +
      "closed: suite 4866 alpn - sni localhost sent 0 received -1 client-closed true\n" +
      "closed: suite 4866 alpn http/1.1 sni localhost sent 0 received -1 client-closed false\n"
    const body = served.replace(/^port \d+\n/, "")
    check(
      "net_tls_tcp: the server reports each connection's suite, ALPN and SNI, sends no alert, and exits 0",
      ended.code === 0 && body === want,
      `exit ${ended.code} signal ${ended.signal}\nstdout: ${JSON.stringify(body)}\nwant:   ${JSON.stringify(want)}\nstderr: ${serverErr}`
    )
  }
}

// ---- A `nish:` import is the same builtin, not another one -----------------------
// The whole claim a builtin module makes: importing a name *renames* a builtin
// rather than introducing one, so the program that imports and the program that
// reaches for the global have to emit the same body. A golden cannot say that —
// two goldens generated together only prove they were generated together — so
// the two outputs are compared directly, with the one line that is allowed to
// differ (the source file each was compiled from) taken out.
// Both cases have to be in the run: a filter such as `port_` selects
// `io_nish_import_global` alone, and the comparison would read a stale file or none.
if (selectedCases.includes("io_nish_import") && selectedCases.includes("io_nish_import_global")) {
  const ir = (name) => {
    const file = path.join(buildDir, `${name}.ll`)
    return fs.existsSync(file)
      ? stripHeader(fs.readFileSync(file, "utf8")).split(root).join("<root>").trim()
      : null
  }
  const imported = ir("io_nish_import")
  const global = ir("io_nish_import_global")
  check(
    "io_nish_import: the imported spelling emits the IR the global one does",
    imported !== null && imported === global,
    imported === null
      ? "(one of the two cases did not compile)"
      : `--- global\n${global}\n--- imported\n${imported}`
  )
}

// ---- A refused `const` is one diagnostic (#275) --------------------------------------
// A `.err` is a substring match, so it cannot see a cascade after the line it
// names. A `const` whose initializer is refused is declared as the error type,
// and each case here uses one afterwards; the count is what says those uses
// stayed silent rather than each reporting `Unknown identifier` or `Unknown function`.
for (const name of [
  "reject_const_refused_initializer",
  "reject_rng_array_zero_fill",
  "reject_arrow_as_value",
]) {
  if (only && !name.includes(only)) {
    continue
  }
  // A case renamed or deleted fails here rather than leaving the check empty.
  const at = selectedCases.indexOf(name)
  if (at < 0) {
    check(
      `${name}: the refusal is the only diagnostic, and the uses after it are silent`,
      false,
      "(no such case)"
    )
    continue
  }
  // The compile the case loop already ran: one summary line per error.
  const r = caseResults[at]
  const errors = String(r.stderr)
    .split("\n")
    .filter((l) => /:\d+:\d+: error: /.test(l))
  check(
    `${name}: the refusal is the only diagnostic, and the uses after it are silent`,
    r.status === 1 && errors.length === 1,
    String(r.stderr)
  )
}

// ---- A computed key cut short is one syntax error (#348) -------------------------------
// The same blind spot for the parser: the literal skips the broken property to
// its `,` and parses the next one, where abandoning the literal would report
// every token after it.
if (!only || "reject_computed_skip".includes(only)) {
  const at = selectedCases.indexOf("reject_computed_skip")
  const r = at < 0 ? null : caseResults[at]
  const errors =
    r === null
      ? []
      : String(r.stderr)
          .split("\n")
          .filter((l) => /:\d+:\d+: (syntax )?error: /.test(l))
  check(
    "reject_computed_skip: the broken key is the only diagnostic, and the property after it parses",
    r !== null && r.status === 1 && errors.length === 1,
    r === null ? "(no such case)" : String(r.stderr)
  )
}

// ---- WP10: diagnostics ------------------------------------------------------------
// Every CompileError prints `file:line:col: error: <msg>` and then a source excerpt:
// the offending line and a caret line (`^` at the start column, `~` to the node end).
if (!only || "diagnostics".includes(only)) {
  const mm = spawnSync(
    NISH,
    [path.join(casesDir, "reject_type_mismatch.ts"), "-o", path.join(buildDir, "diag_mismatch.ll")],
    { cwd: root }
  )
  const mmLines = String(mm.stderr).split("\n")
  // `a + true` (8 chars) starts at column 40 of line 1, so the caret sits after 39 spaces.
  check(
    "diagnostics: excerpt shows the offending source line",
    mmLines[1] === "  1 | function f(a: number): number { return a + true; }",
    mm.stderr
  )
  check(
    "diagnostics: caret line marks `a + true` under column 40",
    mmLines[2] === "    | " + " ".repeat(39) + "^~~~~~~~",
    mm.stderr
  )

  const synSrc = path.join(buildDir, "diag_syntax.ts")
  fs.writeFileSync(synSrc, "function f( ; {\n  return 1;\n}\n")
  const syn = spawnSync(NISH, [synSrc, "-o", path.join(buildDir, "diag_syntax.ll")], { cwd: root })
  const synErr = String(syn.stderr)
  // stage1's parser stops at the `;` that cannot start a parameter, so the
  // excerpt is the first line with the caret under it. (A `{` opens a
  // destructured parameter, which the checker refuses, since WP33 R1.)
  check(
    "diagnostics: syntax errors keep the `syntax error:` prefix and add the excerpt",
    syn.status === 1 &&
      synErr.includes(":1:13: syntax error: ") &&
      synErr.includes("  1 | function f( ; {\n    |             ^"),
    synErr
  )

  // Multi-error reporting: every independent error is printed, in source order, then a count.
  const multiSrc = path.join(casesDir, "reject_multi_error.ts")
  const multi = spawnSync(NISH, [multiSrc, "-o", path.join(buildDir, "diag_multi.ll")], { cwd: root })
  const multiErr = String(multi.stderr)
  const summaries = multiErr.split("\n").filter((l) => /:\d+:\d+: error: /.test(l))
  check(
    "diagnostics: three independent errors are all reported, in source order, with a `3 errors` line",
    multi.status === 1 &&
      summaries.length === 3 &&
      summaries.map((l) => Number(l.split(":")[1])).join(",") === "2,6,11" &&
      multiErr.trim().endsWith("3 errors"),
    multiErr
  )
  check(
    "diagnostics: a lone error prints no count line (single-error output unchanged)",
    !String(mm.stderr).includes("error\n1 error") && String(mm.stderr).split("\n").length === 4,
    mm.stderr
  )

  // The report stops at 20 errors and says how many more there are.
  const manySrc = path.join(buildDir, "diag_many.ts")
  fs.writeFileSync(
    manySrc,
    Array.from({ length: 25 }, (_, i) => `function f${i}(a: number): number { return a + true; }`).join(
      "\n"
    ) + "\n"
  )
  const many = spawnSync(NISH, [manySrc, "-o", path.join(buildDir, "diag_many.ll")], { cwd: root })
  const manyErr = String(many.stderr)
  check(
    "diagnostics: 25 errors print 20, then `...and 5 more errors` and `25 errors`",
    many.status === 1 &&
      manyErr.split("\n").filter((l) => /:\d+:\d+: error: /.test(l)).length === 20 &&
      manyErr.includes("\n...and 5 more errors\n25 errors"),
    manyErr
  )

  // --json: one object per line on stdout, nothing on stderr, no excerpt, exit code unchanged.
  const js = spawnSync(NISH, [multiSrc, "-o", path.join(buildDir, "diag_multi.ll"), "--json"], {
    cwd: root,
    encoding: "utf8",
  })
  let objects = []
  try {
    objects = js.stdout
      .trim()
      .split("\n")
      .map((l) => JSON.parse(l))
  } catch {
    objects = []
  }
  check(
    "diagnostics: --json prints one JSON object per error on stdout with file/line/column/endLine/endColumn/severity/message",
    js.status === 1 &&
      js.stderr === "" &&
      objects.length === 3 &&
      objects.every(
        (o) =>
          o.file === multiSrc &&
          o.severity === "error" &&
          typeof o.message === "string" &&
          !o.message.includes("|")
      ) &&
      objects[0].line === 2 &&
      objects[0].column === 10 &&
      objects[0].endLine === 2 &&
      objects[0].endColumn === 18,
    js.stdout + js.stderr
  )
  const jsSyn = spawnSync(NISH, [synSrc, "-o", path.join(buildDir, "diag_syntax.ll"), "--json"], {
    cwd: root,
    encoding: "utf8",
  })
  check(
    "diagnostics: --json syntax errors carry the `syntax error:` prefix in `message`",
    jsSyn.status === 1 &&
      jsSyn.stdout.startsWith("{") &&
      JSON.parse(jsSyn.stdout.split("\n")[0]).message.startsWith("syntax error: "),
    jsSyn.stdout + jsSyn.stderr
  )

  // ---- stable diagnostic codes ---------------------------------------------
  // `code` is what a tool keys on instead of the prose, so it has to mean the
  // same rule next release. The registry is `src/codes.ts`, and the generator's
  // `--check` is what says it is well formed.
  const codesGen = spawnSync("node", [path.join(root, "scripts", "gen-diagnostic-codes.mjs"), "--check"], {
    cwd: root,
    encoding: "utf8",
  })
  check(
    "codes: scripts/gen-diagnostic-codes.mjs --check accepts the registry",
    codesGen.status === 0,
    codesGen.stdout + codesGen.stderr
  )

  // ...and that it refuses what `codeFor` would misread (issue #107). The live
  // registry is copied with one line broken, and `--check` has to reject each
  // copy and name the table. A stray string with no other half is skipped by
  // the pair reader, so it would pass for well-formed while every later rule
  // took its neighbour's code; a gap in NL9xxx is a performance rule that lost
  // its number.
  const codesLive = fs.readFileSync(path.join(root, "src", "codes.ts"), "utf8")
  const codesStray = '  "a fragment that nobody gave a code to",\n'
  const codesMutations = [
    [
      "a stray fragment in diagnosticRules",
      "diagnosticRules",
      (t) => t.replace("const diagnosticRules = (): string[] => [\n", (open) => open + codesStray),
    ],
    [
      "a stray fragment in performanceRules",
      "performanceRules",
      (t) => t.replace("const performanceRules = (): string[] => [\n", (open) => open + codesStray),
    ],
    ["a gap in the NL9xxx codes", "performanceRules", (t) => t.replace('"NL9010",', '"NL9011",')],
    [
      "a stray fragment in portabilityRules",
      "portabilityRules",
      (t) => t.replace("const portabilityRules = (): string[] => [\n", (open) => open + codesStray),
    ],
    ["a gap in the NL8xxx codes", "portabilityRules", (t) => t.replace('"NL8006",', '"NL8012",')],
    [
      "a stray fragment in deprecationRules",
      "deprecationRules",
      (t) => t.replace("const deprecationRules = (): string[] => [\n", (open) => open + codesStray),
    ],
    ["a gap in the NL7xxx codes", "deprecationRules", (t) => t.replace('"NL7001",', '"NL7002",')],
    [
      "a deprecation code outside deprecationRules",
      "diagnosticRules",
      (t) => t.replace('"NL2186",', '"NL7002",'),
    ],
    [
      "a non-deprecation code inside deprecationRules",
      "deprecationRules",
      (t) => t.replace('"NL7001",', '"NL2186",'),
    ],
    [
      "a portability code outside portabilityRules",
      "diagnosticRules",
      (t) => t.replace('"NL2186",', '"NL8012",'),
    ],
    [
      "a non-portability code inside portabilityRules",
      "portabilityRules",
      (t) => t.replace('"NL8006",', '"NL2395",'),
    ],
  ]
  for (const [i, [what, table, mutate]] of codesMutations.entries()) {
    const copy = path.join(buildDir, `codes-mutation-${i}.ts`)
    const mutated = mutate(codesLive)
    fs.writeFileSync(copy, mutated)
    const r = spawnSync("node", [path.join(root, "scripts", "gen-diagnostic-codes.mjs"), "--check", copy], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      `codes: --check rejects ${what}`,
      mutated !== codesLive && r.status === 1 && r.stderr.includes(`\`${table}\``),
      mutated === codesLive ? "the mutation did not apply" : r.stdout + r.stderr
    )
  }

  // The parse itself is `scripts/codes-registry.js`, shared with the
  // generator and with `tests/diagnostic-coverage.js` -- three copies of one
  // regex is how the first two drifted apart (issue #96), and that module's
  // header is where the story lives. It raises on a registry whose shape has
  // moved, which is caught here rather than left to propagate: a harness that
  // throws on this line proves nothing about the thousand checks after it.
  const registryOf = (text, label) => {
    try {
      return { pairs: parseCodesRegistry(text, label), error: null }
    } catch (err) {
      return { pairs: [], error: err.message }
    }
  }
  const registryText = fs.readFileSync(path.join(root, "src", "codes.ts"), "utf8")
  const registryRead = registryOf(registryText, "src/codes.ts")
  const registryCodes = registryRead.pairs.map((p) => `${p.code} ${JSON.stringify(p.fragment)}`)
  check(
    `codes: src/codes.ts reads as a registry (${registryCodes.length} rules)`,
    registryRead.error === null && registryCodes.length > 0,
    registryRead.error ?? "an empty registry"
  )
  // A number handed out once is never handed to a different rule.
  const dupCodes = registryCodes.map((p) => p.split(" ")[0]).filter((c, i, a) => a.indexOf(c) !== i)
  check("codes: every rule has its own number", dupCodes.length === 0, `reused: ${dupCodes.join(", ")}`)

  // The reader's two promises, demonstrated rather than taken on trust, because
  // both have already failed here: a registry read at the wrong indentation was
  // read as *empty* rather than as changed, and an empty registry then passed
  // for a covered one. The live table is handed to the reader twice more,
  // reindented and then flattened, so both properties are pinned against real
  // data rather than against a fixture that can drift from it.
  const reindented = registryOf(
    registryText.replace(/^ {2}/gm, "    "),
    "src/codes.ts reindented to four spaces"
  )
  check(
    "codes: the registry reader is indentation-agnostic",
    reindented.error === null && reindented.pairs.length === registryCodes.length,
    reindented.error ??
      `${registryCodes.length} rules as written, ${reindented.pairs.length} after reindenting`
  )

  const flattened = registryOf(
    registryText.replace(/^[ \t]+/gm, ""),
    "src/codes.ts with its indentation stripped"
  )
  check(
    "codes: a registry the reader cannot parse raises rather than reading as empty",
    flattened.error !== null,
    `it answered ${flattened.pairs.length} pairs for a table the pattern cannot match; an empty ` +
      "registry must not be able to pass for a covered one"
  )

  const jsCode = JSON.parse(js.stdout.split("\n")[0])
  check(
    `codes: --json carries a code (${jsCode.code}) and the human summary line does not`,
    /^NL\d{4}$/.test(jsCode.code) &&
      jsCode.code !== "NL0000" &&
      !manyErr.includes(jsCode.code) &&
      !many.stderr.includes("NL"),
    `${js.stdout.split("\n")[0]}\n---\n${manyErr.split("\n")[0]}`
  )
  check(
    "codes: a syntax error is NL0001, whatever the parser worded it as",
    JSON.parse(jsSyn.stdout.split("\n")[0]).code === "NL0001",
    jsSyn.stdout
  )

  // Coverage over every code in the registry, not only over the ones some
  // rejection happens to reach (WP19 G2.4). `tests/diagnostic-coverage.js`
  // compiles the negatives, the `perf_*` positives and its own
  // `tests/wordings/` corpus, reads the `code` out of every `--json` object,
  // and requires each of the registry's codes to be either provoked or named
  // in one of its registers with a reason. Two outcomes are declared per case
  // rather than in general: `parser_refusals.txt` for the constructs stage1's
  // parser turns down before the phase that owns the rule can word it (§A3),
  // and `stage1_divergence.txt` for the programs whose answer is not yet the
  // one the case pins. `--strict-refusals` is what makes both lists
  // shrink-only: a case that starts agreeing fails until the line naming it
  // is deleted.
  //
  // The uncoded remainder is still the backlog, pinned so it can shrink but not
  // grow: such a message is built entirely out of interpolations and has no
  // literal run long enough to identify a rule. Adding one is a matter of
  // giving the message words of its own, not of editing the table -- which is
  // what took this from 8 to 1 over `tests/cases`: `` `${fn}` expects ${a}, got
  // ${b} `` was eight of them, and now reads `expects an argument of type
  // ${a}`, a run a code can be derived from.
  //
  // None now. The last was the empty statement of
  // `tests/wordings/nl2260_empty_statement`, which stage1 answered with
  // ``Unsupported statement `;` ``, quoting the statement with no words of its
  // own; the statement dispatch's fallback names the syntax kind in NL2260's
  // sentence since #320. It was five until #174 gave the duplicate-symbol
  // wordings -- a duplicate export, the same one reached through an import,
  // and a duplicate internal name -- codes of their own (NL3024, NL3026), and
  // two until WP32 S5 gave an import of a name a module does not export
  // (`tests/link/unknown_export`, `reject_map_extras_unknown_export`) NL2376.
  // A new one is named on stdout by the run, so the answer is a registry
  // entry, or a literal run of its own first.
  const UNCODED_BACKLOG = 0
  const wordings = spawnSync(
    "node",
    [
      path.join(root, "tests", "diagnostic-coverage.js"),
      "--compiler",
      path.relative(root, NISH),
      "--strict-refusals",
      "--require-coverage",
      ...(process.env.UPDATE_GOLDENS === "1" ? ["--update"] : []),
    ],
    { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
  )
  const wordingsSummary = wordings.stdout.trim().split("\n").pop() ?? ""
  check(
    `codes: every registry code is provoked by a program, declared, or explained (${wordingsSummary})`,
    wordings.status === 0,
    `${wordings.stdout}${wordings.stderr}`
  )
  const uncodedCount = Number(/uncoded=(\d+)/.exec(wordingsSummary)?.[1] ?? Number.NaN)
  check(
    `codes: the uncoded backlog is ${uncodedCount} message(s), and may not grow past ${UNCODED_BACKLOG}`,
    Number.isFinite(uncodedCount) && uncodedCount <= UNCODED_BACKLOG,
    wordings.stdout
  )
  const jsOk = spawnSync(
    NISH,
    [path.join(casesDir, "cf_fib.ts"), "-o", path.join(buildDir, "diag_json_ok.ll"), "--json"],
    { cwd: root, encoding: "utf8" }
  )
  check(
    "diagnostics: --json on a clean program prints nothing on stdout and exits 0",
    jsOk.status === 0 && jsOk.stdout === "",
    jsOk.stdout + jsOk.stderr
  )

  // -g: the IR verifies, and a linked debug binary carries a DWARF line table naming the .ts file.
  // The golden is compiled by the cases loop above, which a `node tests/run.js
  // <sub>` run may have filtered out; verifying a file that was never written
  // reports a failure about the filter rather than about the compiler.
  const dbgLocalsIr = path.join(buildDir, "dbg_locals.ll")
  if (has("opt") && fs.existsSync(dbgLocalsIr)) {
    const v = spawnSync("opt", ["-passes=verify", "-disable-output", dbgLocalsIr])
    check("dbg_locals: opt -passes=verify accepts the -g IR", v.status === 0, String(v.stderr))
  }
  // A class reached only through an imported class's signatures is described
  // against the file that *declares* it, not against the importer: two
  // `DIFile`s in one module, and the composite naming the second. Before this,
  // `Entry`'s declaration offset was looked up in main.ts's line table and a
  // debugger was sent to a line in the wrong source.
  const reachDir = path.join(buildDir, "dbg_reachable") + path.sep
  fs.rmSync(reachDir, { recursive: true, force: true })
  const reach = spawnSync(
    NISH,
    [path.join(root, "tests", "link", "reachable_struct", "main.ts"), "-o", reachDir, "-g"],
    { cwd: root, encoding: "utf8" }
  )
  const reachIr =
    reach.status === 0 && fs.existsSync(path.join(reachDir, "main.ll"))
      ? fs.readFileSync(path.join(reachDir, "main.ll"), "utf8")
      : ""
  const libFile =
    /^(![0-9]+) = !DIFile\(filename: "[^"]*reachable_struct[/\\]lib\.ts", directory: "\."\)$/m.exec(reachIr)
  check(
    "-g: a class reached through an import is described against the file that declares it",
    libFile !== null && reachIr.includes(`name: "Entry", file: ${libFile[1]}, line: 4,`),
    reach.stderr +
      reachIr
        .split("\n")
        .filter((l) => l.includes("DIFile") || l.includes('name: "Entry"'))
        .join("\n")
  )

  const dbgSrc = path.join(buildDir, "dbg_main.ts")
  fs.writeFileSync(
    dbgSrc,
    "function fib(n: number): number {\n  if (n < 2) return n;\n  return fib(n - 1) + fib(n - 2);\n}\n\nexport function main(): number {\n  const x = fib(10);\n  return x - 55;\n}\n"
  )
  const exe = path.join(buildDir, "dbg_main")
  const link = spawnSync(NISH, [dbgSrc, "-g", "--link", exe, "--profile", "debug"], {
    cwd: root,
    encoding: "utf8",
  })
  check(
    "-g --link --profile debug builds a binary that exits 0",
    link.status === 0 && spawnSync(exe).status === 0,
    link.stderr
  )
  if (link.status === 0) {
    // `lineTableOf` is what makes this one check on two object formats: it
    // answers with the file the platform put the table in, and the assertion
    // under it is the same sentence either way.
    const table = lineTableOf(exe)
    const dumpers = [
      ["llvm-dwarfdump", ["--debug-line", table.file]],
      ["objdump", ["--dwarf=decodedline", table.file]],
    ]
    const tool = dumpers.find(([t]) => has(t))
    if (!tool) {
      skip("-g: neither llvm-dwarfdump nor objdump is installed; line table not inspected")
    } else {
      const dump = spawnSync(tool[0], tool[1], { encoding: "utf8" })
      const out = dump.stdout
      // A row of the line table for our file: `<address> <line> <column> ...` (dwarfdump) or `dbg_main.ts <line> <addr>` (objdump).
      const hasRow =
        tool[0] === "llvm-dwarfdump"
          ? /^0x[0-9a-f]+\s+[1-9]\d*\s+\d+/m.test(out)
          : /dbg_main\.ts\s+[1-9]\d*\s+0x/.test(out)
      check(
        `${tool[0]}: the line table names dbg_main.ts and has at least one row (read from ${table.where})`,
        dump.status === 0 && out.includes("dbg_main.ts") && hasRow,
        out.slice(0, 2000) + dump.stderr
      )
    }
  }
  // The speed profile keeps the DWARF too: -g disables the strip step of
  // build.sh. Read through `lineTableOf` for the reason the check above does:
  // on Mach-O the stripping the profile would have done is `-Wl,-x` on the
  // executable, and the table `-g` produced is in the bundle next to it, so
  // looking only at the executable would report every Darwin build as
  // stripped whether or not it was.
  const speed = spawnSync(NISH, [dbgSrc, "-g", "--link", `${exe}.speed`], {
    cwd: root,
    encoding: "utf8",
  })
  const speedTable = speed.status === 0 ? lineTableOf(`${exe}.speed`) : null
  const symbols =
    speedTable !== null && has("llvm-dwarfdump")
      ? spawnSync("llvm-dwarfdump", ["--debug-line", speedTable.file], { encoding: "utf8" }).stdout
      : ""
  check(
    "-g --link (speed profile) is not stripped: the line table survives " +
      `(read from ${speedTable === null ? "the linked binary" : speedTable.where})`,
    speed.status === 0 && (!has("llvm-dwarfdump") || symbols.includes("dbg_main.ts")),
    speed.stderr + symbols.slice(0, 500)
  )
}

// ---- WP15 §8: the `performance` diagnostic class -----------------------------------
// Warnings, not errors: a program that trips one still compiles and still exits 0.
// They print `file:line:col: performance: <text>` with the same excerpt an error
// gets, carry `"severity":"performance"` in `--json`, and `--no-warn-performance`
// silences the class without changing one byte of the IR. The guard cases matter
// most: a warning that fires where the compiler already did the right thing is what
// teaches people to ignore a whole diagnostic class.
if (!only || "performance".includes(only)) {
  /** Compile one case to its own output file and hand back the whole result. */
  const compile = (name, out, extra = []) =>
    spawnSync(NISH, [path.join(casesDir, `${name}.ts`), "-o", path.join(buildDir, out), ...extra], {
      cwd: root,
      encoding: "utf8",
    })
  const summaries = (text) => text.split("\n").filter((l) => /:\d+:\d+: performance: /.test(l))
  /** The `line:col` of each summary line, comma-joined -- the shape every check below pins. */
  const positions = (lines) => lines.map((l) => /:(\d+):(\d+): /.exec(l).slice(1, 3).join(":")).join(",")

  // The order of the stream, before any rule in it. The warning list is sorted
  // by file, then by position, then by diagnostic code, and `diag_order` is the
  // case that needs the sort: a generic's body is checked when one of its
  // instantiations is finished, so the walk *finds* the warning at line 26
  // after the one at line 36 and reported them that way until WP15's remainder.
  // The pair at 44:41 is the second key — two analyses at one position, ordered
  // by their code rather than by which of them ran. `--json` is a
  // machine-readable stream, so both are a contract, not a presentation detail.
  const order = compile("diag_order", "diag_order.ll")
  const orderLines = summaries(order.stderr)
  check(
    "performance: the warnings of one file are reported by position and then by code, whatever order the analysis found them in",
    order.status === 0 &&
      orderLines.length === 4 &&
      positions(orderLines) === "26:5,36:5,44:41,44:41" &&
      orderLines[0].includes("performance: `s` is rebuilt from its own value") &&
      orderLines[1].includes("performance: `out` is rebuilt from its own value") &&
      orderLines[2].includes("performance: this `*` is computed in i32 and can overflow it") &&
      orderLines[3].includes("performance: this computes with overflow"),
    order.stderr
  )

  // The key `diag_order` could pin but not falsify: a **pass-1** warning beside
  // pass-2 ones in a file that reads in neither order. A struct's layout is
  // known when its members are collected, so the analysis hands the sink the
  // two padding warnings first -- `Slot` at 26 and `Frame` at 42 -- and only
  // then the two accumulators at 20 and 36. Reported by position they come out
  // 20, 26, 36, 42, which is the file read top to bottom; with the sort removed
  // the padding pair leads, which is what WP15 §8 said blocked the tenth rule
  // until the order was written down.
  const passReport = compile("diag_order_pass1", "diag_order_pass1_report.ll")
  const passLines = summaries(passReport.stderr)
  check(
    "performance: a pass-1 warning is reported at its place in source order, not ahead of every pass-2 warning in its file",
    passReport.status === 0 &&
      passLines.length === 4 &&
      positions(passLines) === "20:5,26:14,36:5,42:14" &&
      passLines[0].includes("performance: `out` is rebuilt from its own value") &&
      passLines[1].includes("performance: `Slot` is 24 bytes and would be 16") &&
      passLines[2].includes("performance: `s` is rebuilt from its own value") &&
      passLines[3].includes("performance: `Frame` is 24 bytes and would be 16"),
    passReport.stderr
  )

  // The tenth rule (NL9010). §8's hint column asks for three things -- the size
  // the struct is, the size the same fields reach in their best order, and that
  // order -- so the whole sentence is the check rather than the words it opens
  // with. A `class` and an `interface` of identical shape, because a layout is a
  // layout and the rule may not be a rule about classes; the interface's hint
  // carries the second half of its rewrite, since reordering an interface alone
  // is what stops an implementer compiling.
  const pad = compile("perf_padding", "perf_padding_report.ll")
  const padLines = summaries(pad.stderr)
  const padSentence = (name, report) =>
    `performance: \`${name}\` is 24 bytes and would be 16 with the same fields in a different order, so 8 bytes ` +
    "of every value are padding the alignment rules insert and nothing reads: declare the fields widest first " +
    `\u2014 \`${report}\``
  const implementersTail =
    " \u2014 here and in any class that `implements` it, since the interface's fields are its implementers' " +
    "first fields"
  check(
    "performance: a struct a reordering would shrink warns once, naming both sizes and the order that reaches the smaller one",
    pad.status === 0 &&
      padLines.length === 2 &&
      positions(padLines) === "14:14,20:18" &&
      padLines[0].endsWith(padSentence("Mixed", "size: f64, count: i32, flag: boolean")) &&
      padLines[1].endsWith(padSentence("Row", "weight: f64, index: i32, live: boolean") + implementersTail),
    pad.stderr
  )

  // A class that `implements` an interface (#108): the interface's fields stay
  // first and only the fields after them are reordered, so the sentence names
  // the prefix it keeps and an order that starts with it. `Tagged` implements
  // two interfaces and the longer one, declared below it, is the prefix.
  const suffix = compile("perf_padding_suffix", "perf_padding_suffix_report.ll")
  const suffixLines = summaries(suffix.stderr)
  const suffixSentence = (name, iface, report) =>
    `performance: \`${name}\` is 40 bytes and would be 32 with the same fields in a different order, so 8 bytes ` +
    "of every value are padding the alignment rules insert and nothing reads: keep the first 2 fields where " +
    `\`implements ${iface}\` puts them and declare the rest in this order \u2014 \`${report}\``
  check(
    "performance: a class that implements an interface warns when reordering only the fields after the interface's shrinks it",
    suffix.status === 0 &&
      suffixLines.length === 2 &&
      positions(suffixLines) === "15:14,31:14" &&
      suffixLines[0].endsWith(suffixSentence("Wide", "Base", "a: i32, b: f64, d: f64, c: i32, e: i32")) &&
      suffixLines[1].endsWith(
        suffixSentence("Tagged", "Late", "id: i32, at: f64, weight: f64, count: i32, flag: boolean")
      ),
    suffix.stderr
  )

  // A prefix that ends off alignment leaves a gap the class's narrow fields can
  // fill, so the best suffix is not widest first. Each sentence names the order
  // that fills the gap and the size that order measures to: 24 for `FourGap` and
  // `OneGap`, which widest first leaves at 32, and 40 for `Mixed`, where widest
  // first reaches only 48. With one field kept the sentence says so in the
  // singular.
  const gap = compile("perf_padding_suffix_gap", "perf_padding_suffix_gap_report.ll")
  const gapLines = summaries(gap.stderr)
  const gapSentence = (name, size, packed, iface, report) =>
    `performance: \`${name}\` is ${size} bytes and would be ${packed} with the same fields in a different order, ` +
    `so ${size - packed} bytes of every value are padding the alignment rules insert and nothing reads: keep the ` +
    `first field where \`implements ${iface}\` puts it and declare the rest in this order \u2014 \`${report}\``
  check(
    "performance: a class whose interface prefix ends off alignment is told the order that fills the gap, and the size it reaches",
    gap.status === 0 &&
      gapLines.length === 3 &&
      positions(gapLines) === "14:14,27:14,42:14" &&
      gapLines[0].endsWith(gapSentence("FourGap", 32, 24, "Four", "a: i32, c: i32, b: f64, d: f64")) &&
      gapLines[1].endsWith(
        gapSentence("OneGap", 32, 24, "One", "a: boolean, c: boolean, d: i32, b: f64, e: f64")
      ) &&
      gapLines[2].endsWith(
        gapSentence(
          "Mixed",
          56,
          40,
          "One",
          "a: boolean, r: u8, u: u16, f: f32, s: string, xs: i32[], n: Item | null, q: i64"
        )
      ),
    gap.stderr
  )

  const str = compile("perf_str_concat_loop", "perf_str.ll")
  const strLines = summaries(str.stderr)
  // `for`, `while`, a nested loop whose accumulator is declared one level out,
  // and `do` — each is a loop, and a template hole copies as much as `+` does.
  check(
    "performance: every self-accumulating string assignment in a loop warns, naming the variable and the `string[]` + `join` rewrite",
    str.status === 0 &&
      strLines.length === 4 &&
      positions(strLines) === "7:5,14:5,24:7,33:5" &&
      strLines[0].includes(
        "performance: `out` is rebuilt from its own value on every iteration of this loop"
      ) &&
      strLines[1].includes("performance: `tagged` is rebuilt from its own value") &&
      strLines[2].includes("performance: `row` is rebuilt from its own value") &&
      strLines[3].includes("performance: `tail` is rebuilt from its own value") &&
      strLines.every((l) =>
        l.includes("collect the pieces in a `string[]` and `join` them after the loop")
      ) &&
      str.stderr.includes("\n4 performance warnings\n"),
    str.stderr
  )
  check(
    "performance: a warning carries the same caret excerpt an error does",
    str.stderr.includes('  7 |     out = out + "ab";\n    |     ^~~\n'),
    str.stderr
  )

  const alloc = compile("perf_alloc_loop", "perf_alloc.ll")
  const allocLines = summaries(alloc.stderr)
  check(
    "performance: a dynamically sized `new Array<T>(n)` in a loop warns and names the hoist and the arena scope",
    alloc.status === 0 &&
      allocLines.length === 1 &&
      allocLines[0].includes(
        ":10:11: performance: `row` allocates a dynamically sized array on every iteration of this loop"
      ) &&
      allocLines[0].includes(
        "hoist the allocation above the loop and reuse it, or open the loop body with `using a = arena()`"
      ),
    alloc.stderr
  )

  // Memory that is allocated and then dropped. The function loses its arena
  // scope as well, so both the dropped value and everything else the body
  // allocated live until the program exits.
  const drop = compile("perf_arena_drop", "perf_arena_drop.ll")
  const dropLines = summaries(drop.stderr)
  check(
    "performance: an allocation assigned over an allocation warns once per dropped value, naming both rewrites",
    drop.status === 0 &&
      dropLines.length === 3 &&
      positions(dropLines) === "15:3,17:3,21:3" &&
      dropLines[0].includes(
        "`p` already holds an allocation and this one drops it: nothing can reach the old value from here and " +
          "nothing frees it, and assigning a local is also what stops this function from releasing its arena " +
          "memory at all, so both allocations live until the program exits. Give each value its own `const`, or " +
          "bracket the body in a block that opens with `using a = arena()`"
      ) &&
      dropLines[1].includes("`xs` already holds an allocation") &&
      dropLines[2].includes("`s` already holds an allocation"),
    drop.stderr
  )

  // NL9016: a local declared outside a loop and handed a new allocation on
  // every pass. `last` was declared holding a literal, which NL9003 lets go, so
  // this is the drop nothing reported. The pointer-returning `lastLabel` warns
  // as well, an inner loop warns for a local of the outer one, and `row`, which
  // was declared holding an allocation, is NL9003's alone: one line, one warning.
  const passDrop = compile("perf_arena_pass_drop", "perf_arena_pass_drop_report.ll")
  const passDropLines = summaries(passDrop.stderr)
  check(
    "performance: an allocation dropped on every pass of a loop warns, and a line NL9003 reports stays NL9003's",
    passDrop.status === 0 &&
      passDropLines.length === 4 &&
      positions(passDropLines) === "18:5,26:5,34:7,45:5" &&
      passDropLines[1].includes(
        "`last` is given a new allocation on every pass of this loop and drops the one the pass before gave it: " +
          "nothing can reach that value again and nothing frees it while the loop runs, so memory grows with every " +
          "pass. Declare `last` with `const` inside the loop when only its pass reads it, or keep what the last " +
          "pass needs as numbers and build the value once after the loop"
      ) &&
      passDropLines[0].includes("`label` is given a new allocation on every pass") &&
      passDropLines[2].includes("`at` is given a new allocation on every pass") &&
      passDropLines[3].includes("`row` already holds an allocation and this one drops it"),
    passDrop.stderr
  )

  // The arithmetic rules. These are not advice about speed: each one is a
  // program that does not compute what it was written to compute, and the
  // message has to name the rewrite all the same.
  const over = compile("perf_overflow", "perf_overflow.ll")
  const overLines = summaries(over.stderr)
  check(
    "performance: `toI64(a * b)` and a shift count at the operand width both warn, each naming its rewrite",
    over.status === 0 &&
      overLines.length === 2 &&
      overLines[0].includes(
        "this `*` is computed in i32 and can overflow it before `toI64` widens the result, so the conversion " +
          "never sees the product the line was written for: convert the operands first, as `toI64(a) * toI64(b)`"
      ) &&
      overLines[1].includes(
        "the shift count 32 is at or beyond the 32 bits of the operand, so it is masked to 0 and this shifts by that instead"
      ),
    over.stderr
  )

  // Reported on the innermost expression that overflows: the third constant
  // here is `100000 * 100000 + 1`, and only the `*` is named, because the `+`
  // merely inherits a value that has already gone wrong.
  const consts = compile("perf_overflow_const", "perf_overflow_const.ll")
  const constLines = summaries(consts.stderr)
  check(
    "performance: a constant that does not fit its i32 warns once per innermost overflow, naming the value and the range",
    consts.status === 0 &&
      constLines.length === 3 &&
      positions(constLines) === "8:15,9:19,12:18" &&
      constLines[0].includes(
        "this computes with overflow: the result 2147483648 does not fit in i32 (the range is -2147483648 to " +
          "2147483647), and signed overflow panics when it runs rather than wrapping: widen the operands with " +
          "`toI64` first, or use --wrapping for two's-complement arithmetic"
      ) &&
      constLines[2].includes("the result 10000000000 does not fit in i32"),
    consts.stderr
  )

  // `--wrapping` makes the wrap the defined answer, so the constant rule has
  // nothing left to say and must not argue with the flag. What is left is the
  // flag's own deprecation (NL9015), once, at the top of the entry.
  const wrapped = compile("perf_overflow_wrapping", "perf_overflow_wrapping.ll", ["--wrapping"])
  const wrappedLines = summaries(wrapped.stderr)
  check(
    "performance: --wrapping silences the constant-overflow warning, which is only about the panic, and says once that it is deprecated",
    wrapped.status === 0 &&
      wrappedLines.length === 1 &&
      wrappedLines[0].includes(":1:1: performance: --wrapping is deprecated") &&
      wrappedLines[0].includes("`wrappingAdd`, `wrappingSub` and `wrappingMul` from `nish:unsafe`"),
    wrapped.stderr
  )

  // WP15 §2: a bounds check the proof could not remove. The three shapes are the
  // three ways a fact dies — a second array with its own length, a call that may
  // move `len`, and a cursor that walks down — and each message names the guard
  // that would prove both ends.
  const bounds = compile("perf_bounds_loop", "perf_bounds_loop.ll")
  const boundsLines = summaries(bounds.stderr)
  check(
    "performance: a bounds check that survived the proof warns once per access, naming the guard",
    bounds.status === 0 &&
      boundsLines.length === 3 &&
      positions(boundsLines) === "12:24,20:36,28:24" &&
      boundsLines[0].includes(
        "`i` is not proven to be in range for `ys` here, so this access keeps its bounds check"
      ) &&
      boundsLines[1].includes("`j` is not proven to be in range for `zs`") &&
      boundsLines[2].includes("`k` is not proven to be in range for `ws`") &&
      boundsLines.every((l) =>
        l.includes("proves both ends, and an unsigned index needs only the upper one")
      ),
    bounds.stderr
  )

  // An offset index that keeps its check warns too, and names a guard on the
  // sum: `ys[i + 1]` under a loop bounded by `xs` warns, and `xs[i + 1]`, which
  // the loop condition proves, is quiet.
  const offsets = compile("perf_bounds_offset", "perf_bounds_offset.ll")
  const offsetLines = summaries(offsets.stderr)
  check(
    "performance: an offset index that survived the proof warns, naming a guard on the sum",
    offsets.status === 0 &&
      offsetLines.length === 1 &&
      positions(offsetLines) === "11:36" &&
      offsetLines[0].includes("`i + 1` is not proven to be in range for `ys` here") &&
      offsetLines[0].includes("`if (i >= 0 && i + 1 < ys.length)` proves both ends"),
    offsets.stderr
  )

  // WP15 §4/§8: a `substring` bound the proof could not place in [0, s.length]
  // keeps JavaScript's clamp, and is reported once per bound -- so the one call
  // here, with neither end proven, warns twice and names each bound.
  const clamp = compile("perf_clamp", "perf_clamp.ll")
  const clampLines = summaries(clamp.stderr)
  check(
    "performance: an unfolded `substring` clamp warns once per bound, naming the bound and the guard",
    clamp.status === 0 &&
      clampLines.length === 2 &&
      positions(clampLines) === "25:33,25:39" &&
      clampLines[0].includes(
        "`from` is not provably within `s`, so this `substring` bound keeps the clamp"
      ) &&
      clampLines[1].includes("`to` is not provably within `s`") &&
      clampLines.every((l) => l.includes("or use `slice`, which has no clamp at all")),
    clamp.stderr
  )

  // The clamp is the semantics, not a check, so the flag that removes every
  // bounds check must leave both the clamp and its warning exactly as they were;
  // the only line it adds is its own deprecation (NL9014).
  const clampUnchecked = compile("perf_clamp", "perf_clamp_unchecked.ll", ["--unchecked-indexing"])
  const clampUncheckedLines = summaries(clampUnchecked.stderr)
  check(
    "performance: --unchecked-indexing changes neither the substring clamp nor its warning",
    clampUnchecked.status === 0 &&
      clampUncheckedLines.length === 3 &&
      clampUncheckedLines[0].includes(":1:1: performance: --unchecked-indexing is deprecated") &&
      clampUncheckedLines.slice(1).join("\n") === clampLines.join("\n") &&
      stripHeader(fs.readFileSync(path.join(buildDir, "perf_clamp_unchecked.ll"), "utf8")) ===
        stripHeader(fs.readFileSync(path.join(buildDir, "perf_clamp.ll"), "utf8")),
    clampUnchecked.stderr
  )

  // The proof is worth an instruction count, not just a quieter build: the two
  // proven calls in perf_clamp_quiet lose a clamp pair each -- four pairs, so
  // eight of the twenty-four calls -- and the two shapes with nothing to prove
  // keep all six of theirs. Compiled here rather than read off the goldens
  // section, so that `node tests/run.js performance` stands on its own.
  const clampQuietCompile = compile("perf_clamp_quiet", "perf_clamp_quiet.ll")
  const clampQuietIr =
    clampQuietCompile.status === 0 ? fs.readFileSync(path.join(buildDir, "perf_clamp_quiet.ll"), "utf8") : ""
  const clampCalls = (clampQuietIr.match(/call i64 @llvm\.(smin|smax)\.i64/g) ?? []).length
  check(
    "performance: a proven substring bound emits no clamp at all (8 of 24 intrinsic calls left out)",
    clampQuietCompile.status === 0 && clampCalls === 16,
    `llvm.smin/smax calls in perf_clamp_quiet.ll: ${clampCalls}, expected 16\n${clampQuietCompile.stderr}`
  )

  // WP15 §8: --no-strict-exports keeps a non-exported function an external
  // symbol. Reported at the call and only inside a loop; the exported callee
  // and the call outside the loop in the same file must stay silent.
  const inline = compile("perf_inline", "perf_inline.ll", ["--no-strict-exports"])
  const inlineLines = summaries(inline.stderr)
  check(
    "performance: --no-strict-exports warns at a call in a loop to a function the module does not export",
    inline.status === 0 &&
      inlineLines.length === 1 &&
      inlineLines[0].includes("`step` is called here inside a loop and `--no-strict-exports` keeps it an") &&
      inlineLines[0].includes("drop `--no-strict-exports`, and a function this module does not export is"),
    inline.stderr
  )

  // The default is the rewrite the message names, so it must say nothing.
  const inlineDefault = compile("perf_inline", "perf_inline_default.ll")
  check(
    "performance: the default (--strict-exports) is the rewrite, so the same file reports nothing",
    inlineDefault.status === 0 && summaries(inlineDefault.stderr).length === 0,
    inlineDefault.stderr
  )

  // The guards, with the flag given, so what is tested is the guards.
  const inlineQuiet = compile("perf_inline_quiet", "perf_inline_quiet.ll", ["--no-strict-exports"])
  check(
    "performance: perf_inline_quiet takes no slow path with a faster form to name, so nothing is reported",
    inlineQuiet.status === 0 && summaries(inlineQuiet.stderr).length === 0,
    inlineQuiet.stderr
  )

  // The foreign shape is the one the `exported` test alone got wrong, and a
  // count of zero above cannot say the shape was still in the file. `abs` is
  // `declare`d rather than defined, so the `declare` line is what proves this
  // case still carries it -- a silent case that stopped containing the shape
  // it guards is the failure mode a zero-warning assertion has.
  // A `declare function` is external because C defines it, not because this
  // module withheld an `export` -- and `exported` is always false for one, so
  // testing it alone reported a C call in a loop and named two rewrites that
  // were both impossible. `perf_inline_foreign` holds the foreign call and an
  // ordinary non-exported call in the *same* loop, so the one surviving
  // diagnostic is what says the `foreign` guard is not too wide.
  const inlineForeign = compile("perf_inline_foreign", "perf_inline_foreign.ll", ["--no-strict-exports"])
  const foreignLines = summaries(inlineForeign.stderr)
  check(
    "performance: a `declare function` in a loop is silent, and the ordinary call beside it still warns",
    inlineForeign.status === 0 &&
      foreignLines.length === 1 &&
      foreignLines[0].includes("`step` is called here inside a loop and `--no-strict-exports` keeps it an"),
    inlineForeign.stderr
  )

  // And *why* it must be silent, rather than only that it is: the flag has no
  // linkage to withdraw from a `declare`, so every `declare` line the emitter
  // writes is the same under the flag as under the default. There is nothing
  // for the message's two rewrites to change, which is what makes a warning
  // here a warning about a cost nobody is paying.
  const foreignDefault = compile("perf_inline_foreign", "perf_inline_foreign_default.ll")
  // The foreign ones: the runtime's and LLVM's own declarations follow what the
  // module calls, and under the flag an exported function proves less of its
  // arithmetic, so more of it is checked (src/ranges.ts takes no entry facts in
  // an open build).
  const declaresIn = (f) =>
    (fs.readFileSync(path.join(buildDir, f), "utf8").match(/^declare .*$/gm) ?? [])
      .filter((line) => !/@(llvm\.|nish_)/.test(line))
      .join("\n")
  check(
    "performance: --no-strict-exports leaves a `declare function` byte for byte as the default emits it",
    inlineForeign.status === 0 &&
      foreignDefault.status === 0 &&
      declaresIn("perf_inline_foreign.ll") === declaresIn("perf_inline_foreign_default.ll") &&
      /^declare i32 @abs\(i32\)$/m.test(declaresIn("perf_inline_foreign.ll")),
    `flagged:\n${declaresIn("perf_inline_foreign.ll")}\ndefault:\n${declaresIn("perf_inline_foreign_default.ll")}`
  )

  // The flag removes every check, so there is no surviving one to report; what
  // is left is the flag's own deprecation (NL9014), once, at the top of the entry.
  const boundsOff = compile("perf_bounds_loop", "perf_bounds_off.ll", ["--unchecked-indexing"])
  const boundsOffLines = summaries(boundsOff.stderr)
  check(
    "performance: --unchecked-indexing leaves no bounds check to warn about, and says once that it is deprecated",
    boundsOff.status === 0 &&
      boundsOffLines.length === 1 &&
      boundsOffLines[0].includes(":1:1: performance: --unchecked-indexing is deprecated") &&
      boundsOffLines[0].includes("`uncheckedGet` and `uncheckedSet` from `nish:unsafe`"),
    boundsOff.stderr
  )

  // The false-positive guards. Each of these compiles loops that concatenate or
  // allocate where the faster form is already what the compiler emits, or where the
  // program genuinely asked for the memory, so it must say nothing at all.
  for (const name of [
    "perf_str_concat_quiet",
    "perf_alloc_quiet",
    "perf_overflow_quiet",
    "perf_arena_quiet",
    // A search loop, a value kept in an array or in the node that replaces it,
    // a local of the pass, an assignment of no allocation and a loop that runs
    // once: none of them drops a value on every pass, so NL9016 is silent.
    "perf_arena_pass_quiet",
    // Every index proven, so no check survives and nothing is reported.
    "perf_bounds_quiet",
    // Every index proven through a hoisted `toI32(w.length)`, the spelling that
    // compiles in both number modes; the `_f64` twin runs under its `.args`.
    "perf_bounds_toi32",
    "perf_bounds_toi32_f64",
    // Literal spellings neither compiler folds: normalising them in stage0 would
    // fold exactly what stage1 refuses, and only one of the two would warn.
    "perf_overflow_spelling",
    // Every `substring` bound either proven -- in which case the clamp is gone
    // from the IR, not merely quiet -- or with no guard anybody could write.
    "perf_clamp_quiet",
    // Structs that are already as small as their fields make them, a class
    // whose only padding is in the interface prefix it may not permute, and a
    // generic instantiation, whose order is not the author's to choose.
    "perf_padding_quiet",
    // A class whose padding is all inside its interface prefix, with the
    // fields it adds already widest first: nothing the author may reorder.
    "perf_padding_suffix_quiet",
  ]) {
    const quiet = compile(name, `${name}.ll`, caseArgs(name))
    check(
      `performance: ${name} takes no slow path with a faster form to name, so nothing is reported`,
      quiet.status === 0 && summaries(quiet.stderr).length === 0,
      quiet.stderr
    )
  }

  // #216: the arena-loop warning (NL9011) names the loops that neither a scope
  // around each pass nor one around the function reclaims, in a function of any
  // return type, and names what refused both. `tally` stores into memory on
  // every pass, `drain` calls a function that releases the arena, and
  // `collect`, which returns a pointer, grows an array older than the pass;
  // `quiet`'s passes are scoped and say nothing. `perf_arena_control` is the
  // silence the issue found untested: a function that brackets its own passes
  // with `Arena.mark()` / `Arena.release(m)` gets no warning although it
  // returns a pointer and stores a string, and neither does a pointer-returning
  // function whose passes the compiler scopes.
  const arenaLoop = compile("perf_arena_loop", "perf_arena_loop_report.ll")
  const arenaLoopLines = summaries(arenaLoop.stderr)
  check(
    "mem_loop_scope: NL9011 names each loop no scope reclaims, and what refused its passes and its function",
    arenaLoop.status === 0 &&
      arenaLoopLines.length === 3 &&
      positions(arenaLoopLines) === "25:14,39:14,48:18" &&
      arenaLoopLines[0].includes(
        "`makeList` leaves arena memory behind on every pass of this loop, which cannot release it after each " +
          "pass because the allocation on line 26 is stored into memory, where this analysis stops following it, " +
          "and neither can `tally` when it returns, so all of it lives as long as the caller's memory does"
      ) &&
      arenaLoopLines[1].includes(
        "because it calls `flush`, which releases or resets the arena, and neither can `drain`"
      ) &&
      arenaLoopLines[2].includes(
        "because line 48 grows `lengths`, an array older than the pass, and `collect` cannot release it when it " +
          "returns because it returns a value that is not a number, a boolean, an enum or nothing"
      ),
    arenaLoop.stderr
  )
  const arenaControl = compile("perf_arena_control", "perf_arena_control_report.ll")
  check(
    "mem_loop_scope: no NL9011 under Arena control, nor for a pointer-returning loop whose passes are scoped",
    arenaControl.status === 0 && summaries(arenaControl.stderr).length === 0,
    arenaControl.stderr
  )
  // A call inside a `using a = arena()` block leaves nothing behind once the
  // block releases, whatever refused the pass and the function their scopes.
  const arenaUsing = compile("perf_arena_using", "perf_arena_using_report.ll")
  check(
    "mem_loop_scope: no NL9011 for a call inside a `using a = arena()` block",
    arenaUsing.status === 0 && summaries(arenaUsing.stderr).length === 0,
    arenaUsing.stderr
  )

  // #216's acceptance, as a peak resident set rather than as `Arena.used()`:
  // `mem_loop_scope_chunk`'s pointer-returning loop allocates more than an
  // arena chunk on every pass, so every release frees a chunk through
  // `nish_arena_release` rather than rewinding `off`. Kept, 2000 passes are
  // about 160 MB; released, the peak at 2000 is the peak at 20. The bound is a
  // ratio rather than a size, so the runtime's own footprint can move freely.
  if (has("clang")) {
    const chunk = compile("mem_loop_scope_chunk", "mem_loop_scope_chunk_rss.ll")
    const exe = path.join(buildDir, "mem_loop_scope_chunk")
    const rssExe = path.join(buildDir, "rss")
    const cc =
      chunk.status === 0 ? linkNative(exe, path.join(buildDir, "mem_loop_scope_chunk_rss.ll")) : chunk
    const rc = spawnSync("clang", ["-O2", path.join(root, "bench", "rss.c"), "-o", rssExe], {
      encoding: "utf8",
    })
    const peak = (rounds) => {
      const r = spawnSync(rssExe, [exe, String(rounds)], { encoding: "utf8" })
      return r.status === 0 ? Number(r.stdout.trim()) : -1
    }
    const few = cc.status === 0 && rc.status === 0 ? peak(20) : -1
    const many = cc.status === 0 && rc.status === 0 ? peak(2000) : -1
    check(
      "mem_loop_scope: a pass that pushes an arena chunk frees it, so 2000 passes peak where 20 do",
      few > 0 && many > 0 && many < few * 2,
      `peak at 20 passes: ${few}, at 2000: ${many}\n${cc.stderr}${rc.stderr}`
    )
  } else {
    skip("mem_loop_scope: the peak resident set run needs clang")
  }

  // Only the length converts to a length: the conversion of anything else
  // leaves the check, and the warning, where they were.
  const toI32Loop = compile("perf_bounds_toi32_loop", "perf_bounds_toi32_loop_report.ll")
  const toI32LoopLines = summaries(toI32Loop.stderr)
  check(
    "performance: `toI32` of something that is not a length proves nothing, and each access warns",
    toI32Loop.status === 0 &&
      toI32LoopLines.length === 2 &&
      positions(toI32LoopLines) === "14:33,23:17" &&
      toI32LoopLines[0].includes("`i` is not proven to be in range for `s` here") &&
      toI32LoopLines[1].includes("`j` is not proven to be in range for `xs` here"),
    toI32Loop.stderr
  )

  // A user function named `toI32` wins over the builtin and answers what it
  // likes, here one past the length. The warning says the check stayed, and
  // the run says it had to: the last pass panics instead of reading past `s`.
  const toI32User = compile("perf_bounds_toi32_user", "perf_bounds_toi32_user_report.ll")
  const toI32UserLines = summaries(toI32User.stderr)
  check(
    "performance: a user function named `toI32` is not trusted as the length, so the access warns",
    toI32User.status === 0 &&
      toI32UserLines.length === 1 &&
      positions(toI32UserLines) === "14:30" &&
      toI32UserLines[0].includes("`i` is not proven to be in range for `s` here"),
    toI32User.stderr
  )
  if (has("clang") && toI32User.status === 0) {
    const exe = path.join(buildDir, "perf_bounds_toi32_user")
    const cc = linkNative(exe, path.join(buildDir, "perf_bounds_toi32_user_report.ll"))
    const run = cc.status === 0 ? spawnSync(exe, { encoding: "utf8" }) : null
    check(
      "perf_bounds_toi32_user: the kept check stops the pass past the end — exits 1 with `index out of range: 3 >= 3`",
      run !== null &&
        run.status === 1 &&
        run.stderr.includes("index out of range: 3 >= 3") &&
        run.stdout === "97\n98\n99\n",
      run ? `exit ${run.status}\nstdout: ${run.stdout}\nstderr: ${run.stderr}` : cc.stderr
    )
  } else {
    skip("perf_bounds_toi32_user: the panic run needs clang")
  }

  // `std/text` is imported into every program that reads lines, so a warning
  // from inside it is a warning about code the user cannot change. A program
  // importing every export — read off the module, so a new one is covered the
  // day it lands — must compile silent from `std/text.ts` in both number
  // modes: the checks are proven away, which is not the same as silenced.
  const textExports = [
    ...fs.readFileSync(path.join(root, "std", "text.ts"), "utf8").matchAll(/^export const (\w+)/gm),
  ].map((m) => m[1])
  const textUser = path.join(buildDir, "std_text_importer.ts")
  fs.writeFileSync(
    textUser,
    `import { ${textExports.join(", ")} } from "nish/text";\n\nexport const main = (): i32 => 0;\n`
  )
  for (const mode of ["i32", "f64"]) {
    const outDir = path.join(buildDir, `std_text_importer_${mode}`)
    const run = spawnSync(NISH, [textUser, "-o", `${outDir}/`, "--number-mode", mode], {
      cwd: root,
      encoding: "utf8",
    })
    const fromText = summaries(run.stderr).filter((l) => l.includes("std/text.ts:"))
    check(
      `performance: a program importing all ${textExports.length} exports of nish/text compiles with no warning from std/text.ts (--number-mode ${mode})`,
      run.status === 0 &&
        textExports.length > 0 &&
        fs.existsSync(path.join(outDir, "text.ll")) &&
        fromText.length === 0 &&
        !run.stderr.includes("more performance warnings"),
      run.stderr
    )
  }

  // The zero gate. What ships is held to no performance warning at all: every
  // module of the standard library, which is compiled into each program that
  // imports it, and every example, which is what a reader copies. Both are
  // discovered from their directories, so a module or an example added later
  // is gated the day it lands without anybody editing a list, and each is
  // compiled in both number modes, because a warning can be one mode's alone.
  // The warnings are read from `--json` by their `severity` and `code`, never
  // from the report, whose wording may change and whose length is capped
  // (`.claude/testing.md`). A check proven away is what clears this; there is
  // no `--no-warn-performance` anywhere in it, and none in the gated sources.
  //
  // A few programs are written for one number mode and do not compile in the
  // other at all. Each is named with the diagnostic code that refuses it, so a
  // refusal for any other reason still fails, and a listed program that starts
  // compiling fails too, until it comes off the list and the gate holds it.
  const PERF_GATE_REFUSED = new Map([
    ["examples/argv.ts f64", "NL2140"], // `main` answers `number`, which is f64 there
    ["examples/arrays.ts f64", "NL2021"], // `i * i` is f64 there, and `out` is an Int32Array
    ["examples/hello.ts f64", "NL2140"],
    ["examples/multi/main.ts f64", "NL2140"],
    ["examples/nbody.ts i32", "NL2008"], // written for f64 (its `// smoke: args` line): `Math.sqrt` of an i32
  ])
  // The walker the gate reads `std/` through reaches a module in a subdirectory,
  // proven on a tree of its own so the claim does not wait for one to exist.
  {
    const fixture = fs.mkdtempSync(path.join(os.tmpdir(), "nish-std-walk-"))
    fs.mkdirSync(path.join(fixture, "crypto", "hash"), { recursive: true })
    for (const file of ["top.ts", "crypto/inner.ts", "crypto/hash/deep.ts", "crypto/notes.md", "README.md"]) {
      fs.writeFileSync(path.join(fixture, file), "")
    }
    fs.mkdirSync(path.join(fixture, "looks.ts"))
    const found = stdModuleFiles(fixture)
    const want = ["std/crypto/hash/deep.ts", "std/crypto/inner.ts", "std/top.ts"]
    fs.rmSync(fixture, { recursive: true, force: true })
    check(
      "performance gate: the std/ walker finds a module at every depth, and nothing that is not one",
      JSON.stringify(found) === JSON.stringify(want),
      `found ${JSON.stringify(found)}, wanted ${JSON.stringify(want)}`
    )
  }
  const gateSources = [
    ...stdModuleFiles(),
    // The corpus's own discovery, which already reads a directory with a
    // `main.ts` as one program (`examples/multi/`).
    ...corpusPrograms()
      .map((file) => path.relative(root, file).split(path.sep).join("/"))
      .filter((file) => file.startsWith("examples/")),
  ].sort()
  const gateRuns = gateSources.flatMap((source) => ["i32", "f64"].map((mode) => ({ source, mode })))
  const gateResults = await pool(gateRuns, defaultJobs(), ({ source, mode }) =>
    spawnAsync(
      NISH,
      [
        source,
        "-o",
        `${path.join(buildDir, "perf_gate", mode, source.replace(/[/.]/g, "_"))}/`,
        "--number-mode",
        mode,
        "--json",
      ],
      { cwd: root, encoding: "utf8" }
    )
  )
  for (const [at, { source, mode }] of gateRuns.entries()) {
    const result = gateResults[at]
    const diagnostics = diagnosticsOf(result.stdout)
    const refusedBy = PERF_GATE_REFUSED.get(`${source} ${mode}`)
    if (refusedBy !== undefined) {
      const codes = diagnostics.filter((d) => d.severity === "error").map((d) => d.code)
      check(
        `performance gate: ${source} is written for the other number mode and does not compile under --number-mode ${mode} (${refusedBy}, as recorded)`,
        result.status === 1 && codes.includes(refusedBy),
        result.status === 0
          ? `it compiles now: take "${source} ${mode}" out of PERF_GATE_REFUSED in tests/run.js so the gate holds it`
          : `refused for another reason than ${refusedBy}:\n${diagnostics.map(diagnosticLine).join("\n")}${result.stderr}`
      )
      continue
    }
    const warnings = diagnostics.filter((d) => d.severity === "performance")
    check(
      `performance gate: ${source} compiles with no performance warning (--number-mode ${mode})`,
      result.status === 0 && warnings.length === 0,
      result.status !== 0
        ? `it does not compile:\n${diagnostics.map(diagnosticLine).join("\n")}${result.stderr}`
        : `${warnings.length} performance warning(s); prove each check away rather than silencing it ` +
            `(.claude/testing.md, "The performance gate"):\n${warnings.map(diagnosticLine).join("\n")}`
    )
  }

  // What ships calls nothing deprecated either: a deprecation in `std/` would
  // reach every program that imports the module, and one in an example is
  // what a reader copies.
  const deprecated = gateRuns.flatMap(({ source, mode }, at) =>
    diagnosticsOf(gateResults[at].stdout)
      .filter((d) => d.severity === "deprecation")
      .map((d) => `${diagnosticLine(d)} (--number-mode ${mode}, ${source})`)
  )
  check(
    `performance gate: none of the ${gateSources.length} std/ modules and examples calls anything deprecated`,
    gateSources.length > 0 && deprecated.length === 0,
    deprecated.join("\n")
  )

  // The flag decides what is printed and nothing else.
  const off = compile("perf_str_concat_loop", "perf_str_off.ll", ["--no-warn-performance"])
  check(
    "performance: --no-warn-performance silences the class and leaves the IR byte-identical",
    off.status === 0 &&
      summaries(off.stderr).length === 0 &&
      stripHeader(fs.readFileSync(path.join(buildDir, "perf_str_off.ll"), "utf8")) ===
        stripHeader(fs.readFileSync(path.join(buildDir, "perf_str.ll"), "utf8")),
    off.stderr
  )

  // --json: one object per warning on stdout, with a severity a tool can filter on.
  const js = compile("perf_alloc_loop", "perf_alloc_json.ll", ["--json"])
  const jsLines = js.stdout.trim().length > 0 ? js.stdout.trim().split("\n") : []
  let jsObj = null
  try {
    jsObj = JSON.parse(jsLines[0])
  } catch {
    jsObj = null
  }
  check(
    'performance: --json prints one object per warning on stdout with "severity":"performance", and exits 0',
    js.status === 0 &&
      jsLines.length === 1 &&
      jsObj !== null &&
      jsObj.severity === "performance" &&
      jsObj.line === 10 &&
      jsObj.column === 11 &&
      !jsObj.message.includes("|"),
    js.stdout + js.stderr
  )

  // An error report is never diluted with advice about code that is about to change.
  const mixedSrc = path.join(buildDir, "perf_mixed.ts")
  fs.writeFileSync(
    mixedSrc,
    'export function test(): number {\n  let s = "";\n  for (let i = 0; i < 2; i = i + 1) {\n    s = s + "x";\n  }\n  return s;\n}\n'
  )
  const mixed = spawnSync(NISH, [mixedSrc, "-o", path.join(buildDir, "perf_mixed.ll")], {
    cwd: root,
    encoding: "utf8",
  })
  check(
    "performance: a compilation that failed prints its errors and none of its warnings",
    mixed.status === 1 && mixed.stderr.includes(": error: ") && summaries(mixed.stderr).length === 0,
    mixed.stderr
  )

  // The report is capped exactly where the error report is.
  const manySrc = path.join(buildDir, "perf_many.ts")
  fs.writeFileSync(
    manySrc,
    Array.from(
      { length: 25 },
      (_, i) =>
        `export function f${i}(): number {\n  let s = "";\n  for (let j = 0; j < 2; j = j + 1) {\n    s = s + "x";\n  }\n  return s.length;\n}`
    ).join("\n") + "\n"
  )
  const many = spawnSync(NISH, [manySrc, "-o", path.join(buildDir, "perf_many.ll")], {
    cwd: root,
    encoding: "utf8",
  })
  check(
    "performance: 25 warnings print 20, then `...and 5 more performance warnings` and `25 performance warnings`",
    many.status === 0 &&
      summaries(many.stderr).length === 20 &&
      many.stderr.includes("\n...and 5 more performance warnings\n25 performance warnings"),
    many.stderr
  )
}

// #207's criteria 1 and 2, measured by hand there and pinned here (#325). The
// AWFY harness is built as bench/run.mjs builds it, and no port calls `Arena`:
// what each inner iteration allocates is handed back by the automatic arena
// scope of the scalar-returning function that called the allocating one (#210,
// `settleScope` in src/attributes.ts). #207 measured 1.002x and 1.00x; with
// that scope switched off, Storage 1 1000 peaks at 390 MB and List 1 100000 at
// 49 MB, against under 2 MB for each. Like `mem_loop_scope_chunk`, the bound is
// a ratio between two runs of one binary, so the runtime's footprint can move.
if (!only || "mem_awfy".includes(only)) {
  if (has("clang")) {
    const dir = path.join(buildDir, "mem_awfy")
    const exe = path.join(dir, "harness")
    const rssExe = path.join(dir, "rss")
    fs.rmSync(dir, { recursive: true, force: true })
    const built = spawnSync(
      NISH,
      [
        path.join("bench", "awfy", "main.ts"),
        "-o",
        `${path.relative(root, path.join(dir, "awfy"))}${path.sep}`,
        "--link",
        path.relative(root, exe),
        "--profile",
        "speed",
      ],
      { cwd: root, encoding: "utf8" }
    )
    const rc = spawnSync("clang", ["-O2", path.join(root, "bench", "rss.c"), "-o", rssExe], {
      encoding: "utf8",
    })
    const ready = built.status === 0 && rc.status === 0
    const peak = (args) => {
      const r = spawnSync(rssExe, [exe, ...args], { encoding: "utf8" })
      return r.status === 0 ? Number(r.stdout.trim()) : -1
    }
    for (const [name, small, large] of [
      ["Storage", "1", "1000"],
      ["List", "10", "100000"],
    ]) {
      const few = ready ? peak([name, "1", small]) : -1
      const many = ready ? peak([name, "1", large]) : -1
      check(
        `mem_awfy: AWFY ${name} at ${large} inner iterations peaks within 1.25x of ${name} at ${small}`,
        few > 0 && many > 0 && many <= few * 1.25,
        `peak of \`harness ${name} 1 ${small}\`: ${few} KB, of \`harness ${name} 1 ${large}\`: ${many} KB\n${built.status === 0 ? "" : built.stderr}${rc.stderr}`
      )
    }
  } else {
    skip("mem_awfy: the peak resident set runs need clang")
  }
}

// ---- WP33: the `portability` diagnostic class --------------------------------------
// Warnings about the program's TypeScript reading rather than about this build:
// where the same source, run under Node, runs to the end and answers
// differently. Off by default and turned on with `--warn-portability`; printed
// `file:line:col: portability: <text>` with the usual excerpt, or with
// `"severity":"portability"` under `--json`, after the performance warnings and
// on the same streams. The rows themselves are pinned by the `port_*` cases'
// `.portability` goldens; what is checked here is the class.
if (!only || "portability".includes(only) || only.startsWith("port_")) {
  const compile = (source, out, extra = []) =>
    spawnSync(NISH, [source, "-o", path.join(buildDir, out), ...extra], { cwd: root, encoding: "utf8" })
  const summaries = (text) => text.split("\n").filter((l) => /:\d+:\d+: portability: /.test(l))
  const objects = (stdout) => stdout.split("\n").filter((l) => l.startsWith("{"))
  const zeroFill = path.join(casesDir, "port_array_zero_fill.ts")

  // Off by default: without the flag the case says nothing, in either form.
  // (That it costs the IR nothing is checked per `port_*` case, beside its golden.)
  const plain = compile(zeroFill, "port_class_plain.ll")
  const plainJson = compile(zeroFill, "port_class_plain_json.ll", ["--json"])
  const warned = compile(zeroFill, "port_class_warned.ll", ["--warn-portability"])
  check(
    "portability: off by default -- port_array_zero_fill says nothing without --warn-portability, in either form",
    plain.status === 0 &&
      summaries(plain.stderr).length === 0 &&
      plainJson.status === 0 &&
      objects(plainJson.stdout).length === 0,
    plain.stderr + plainJson.stdout
  )

  // The human form: the summary line, the excerpt under it, and the count, and
  // a warned program still exits 0.
  const warnedLines = warned.stderr.split("\n")
  check(
    "portability: the human report is `file:line:col: portability: <text>`, an excerpt, and a count, and exits 0",
    warned.status === 0 &&
      summaries(warned.stderr).length === 6 &&
      warnedLines[0] ===
        `${zeroFill}:10:18: portability: \`new Array<i32>(side * side)\` is filled with zeros here, and with holes in TypeScript, which read back as \`undefined\`` &&
      warnedLines[1] === "  10 |     this.cells = new Array<i32>(side * side);" &&
      warnedLines[2] === "     |                  ^~~~~~~~~~~~~~~~~~~~~~~~~~~" &&
      warned.stderr.includes("\n6 portability warnings\n"),
    warned.stderr
  )

  // A program with an error gets the error report and nothing else: advice
  // about code that does not compile is noise.
  const brokenSrc = path.join(buildDir, "port_class_error.ts")
  fs.writeFileSync(
    brokenSrc,
    "export const main = (): number => {\n  const xs = new Array<f64>(3);\n  return xs.length + true;\n};\n"
  )
  const broken = compile(brokenSrc, "port_class_error.ll", ["--warn-portability"])
  const brokenJson = compile(brokenSrc, "port_class_error_json.ll", ["--warn-portability", "--json"])
  check(
    "portability: a program with an error prints no portability warning, in either form",
    broken.status === 1 &&
      broken.stderr.includes(": error: ") &&
      !broken.stderr.includes("portability") &&
      brokenJson.status === 1 &&
      objects(brokenJson.stdout).length > 0 &&
      objects(brokenJson.stdout).every((l) => JSON.parse(l).severity === "error"),
    broken.stderr + brokenJson.stdout
  )

  // The two warning classes are independent in both directions, and when both
  // print, performance comes first. The program has one of each: a string
  // rebuilt in a loop (NL9002) and a zero-filled array (NL8005).
  const bothSrc = path.join(buildDir, "port_class_both.ts")
  fs.writeFileSync(
    bothSrc,
    'export const main = (): number => {\n  let s = "";\n  for (let i = 0; i < 3; i = i + 1) {\n    s = s + "x";\n  }\n  const xs = new Array<f64>(3);\n  return s.length + xs.length;\n};\n'
  )
  const both = compile(bothSrc, "port_class_both.ll", ["--warn-portability"])
  const bothJson = compile(bothSrc, "port_class_both_json.ll", ["--warn-portability", "--json"])
  const quietPerf = compile(bothSrc, "port_class_quiet_perf.ll", [
    "--warn-portability",
    "--no-warn-performance",
  ])
  const perfOnly = compile(bothSrc, "port_class_perf_only.ll")
  const severities = objects(bothJson.stdout).map((l) => `${JSON.parse(l).severity} ${JSON.parse(l).code}`)
  check(
    "portability: printed after the performance warnings, on stderr, and as objects on stdout under --json",
    both.status === 0 &&
      both.stderr.indexOf(": performance: ") >= 0 &&
      both.stderr.indexOf(": performance: ") < both.stderr.indexOf(": portability: ") &&
      bothJson.status === 0 &&
      severities.join(",") === "performance NL9002,portability NL8005",
    both.stderr + bothJson.stdout + bothJson.stderr
  )
  check(
    "portability: --no-warn-performance does not silence it, and it does not bring performance back",
    quietPerf.status === 0 &&
      summaries(quietPerf.stderr).length === 1 &&
      !quietPerf.stderr.includes(": performance: "),
    quietPerf.stderr
  )
  check(
    "portability: without the flag the performance warning alone prints",
    perfOnly.status === 0 &&
      perfOnly.stderr.includes(": performance: ") &&
      !perfOnly.stderr.includes("portability"),
    perfOnly.stderr
  )

  // The cap the performance report has, with the class's own words.
  const manySrc = path.join(buildDir, "port_class_many.ts")
  fs.writeFileSync(
    manySrc,
    Array.from(
      { length: 25 },
      (_, i) => `export const f${i} = (n: i32): i32 => new Array<i32>(n).length;`
    ).join("\n") + "\n"
  )
  const many = compile(manySrc, "port_class_many.ll", ["--warn-portability"])
  check(
    "portability: 25 warnings print 20, then `...and 5 more portability warnings` and `25 portability warnings`",
    many.status === 0 &&
      summaries(many.stderr).length === 20 &&
      many.stderr.includes("\n...and 5 more portability warnings\n25 portability warnings"),
    many.stderr
  )
}

// ---- The `deprecation` diagnostic class (NL7xxx) -----------------------------------
// A call the language still compiles, to the bytes it always did, and is going
// to take away: `Arena.release` and `Arena.reset`, whose undefined behaviour
// `using a = arena()` replaces with a check. On by default with no flag to turn
// it off, printed `file:line:col: deprecation: <text>` with the usual excerpt,
// or with `"severity":"deprecation"` and its NL7xxx code under `--json`, ahead
// of the other two warning classes and on the same streams. It never changes
// the exit code, and a program with an error prints none.
if (!only || "deprecation".includes(only) || "mem_arena_builtins".includes(only)) {
  const compile = (source, out, extra = []) =>
    spawnSync(NISH, [source, "-o", path.join(buildDir, out), ...extra], { cwd: root, encoding: "utf8" })
  const summaries = (text) => text.split("\n").filter((l) => /:\d+:\d+: deprecation: /.test(l))
  const builtins = path.join(casesDir, "mem_arena_builtins.ts")
  const tail =
    "is still referenced is undefined behaviour the compiler does not check. Bracket the work with " +
    "`using a = arena()`, which releases on every exit of its block and refuses whatever would outlive it"

  // The human form: one summary per call, the excerpt under it, and the count,
  // and the program still compiles, to the IR its golden pins.
  const warned = compile(builtins, "deprecation_builtins.ll")
  const warnedLines = warned.stderr.split("\n")
  check(
    "deprecation: Arena.release and Arena.reset each warn `file:line:col: deprecation: <text>`, with an excerpt and a count, and exit 0",
    warned.status === 0 &&
      summaries(warned.stderr).length === 2 &&
      warnedLines[0] ===
        `${builtins}:27:3: deprecation: \`Arena.release\` is deprecated: releasing to a mark while anything allocated after it ${tail}` &&
      warnedLines[1] === "  27 |   Arena.release(m);" &&
      warnedLines[2] === "     |   ^~~~~~~~~~~~~~~~" &&
      warnedLines[3] ===
        `${builtins}:31:3: deprecation: \`Arena.reset\` is deprecated: resetting the arena while anything allocated in it ${tail}` &&
      warned.stderr.includes("\n2 deprecation warnings\n") &&
      stripHeader(fs.readFileSync(path.join(buildDir, "deprecation_builtins.ll"), "utf8")) ===
        stripHeader(fs.readFileSync(path.join(casesDir, "mem_arena_builtins.ll"), "utf8")),
    warned.stderr
  )

  // --json: one object per call on stdout, keyed by its code and severity.
  const json = compile(builtins, "deprecation_builtins_json.ll", ["--json"])
  const jsonObjects = diagnosticsOf(json.stdout)
  check(
    "deprecation: under --json each call is one object with code NL7001 and severity `deprecation`, and exit 0",
    json.status === 0 &&
      jsonObjects.length === 2 &&
      jsonObjects.every((o) => o.code === "NL7001" && o.severity === "deprecation") &&
      jsonObjects.map((o) => `${o.line}:${o.column}-${o.endLine}:${o.endColumn}`).join(",") ===
        "27:3-27:19,31:3-31:16" &&
      jsonObjects[0].message.startsWith("`Arena.release` is deprecated: ") &&
      jsonObjects[1].message.startsWith("`Arena.reset` is deprecated: ") &&
      summaries(json.stderr).length === 0,
    json.stdout + json.stderr
  )

  // `Arena.mark` and `Arena.used` are not deprecated: they read the arena and
  // free nothing.
  const readsSrc = path.join(buildDir, "deprecation_reads.ts")
  fs.writeFileSync(
    readsSrc,
    "export const main = (): i32 => {\n  const m = Arena.mark();\n  return Arena.used() >= m ? 0 : 1;\n};\n"
  )
  const reads = compile(readsSrc, "deprecation_reads.ll")
  const readsJson = compile(readsSrc, "deprecation_reads_json.ll", ["--json"])
  check(
    "deprecation: Arena.mark and Arena.used alone print nothing, in either form",
    reads.status === 0 &&
      summaries(reads.stderr).length === 0 &&
      readsJson.status === 0 &&
      diagnosticsOf(readsJson.stdout).length === 0,
    reads.stderr + readsJson.stdout
  )

  // A program with an error gets the error report and nothing else.
  const brokenSrc = path.join(buildDir, "deprecation_error.ts")
  fs.writeFileSync(
    brokenSrc,
    "export const main = (): i32 => {\n  const m = Arena.mark();\n  Arena.release(m);\n  return m + true;\n};\n"
  )
  const broken = compile(brokenSrc, "deprecation_error.ll")
  const brokenJson = compile(brokenSrc, "deprecation_error_json.ll", ["--json"])
  check(
    "deprecation: a program with an error prints no deprecation warning, in either form",
    broken.status === 1 &&
      broken.stderr.includes(": error: ") &&
      !broken.stderr.includes(": deprecation: ") &&
      brokenJson.status === 1 &&
      diagnosticsOf(brokenJson.stdout).length > 0 &&
      diagnosticsOf(brokenJson.stdout).every((d) => d.severity === "error"),
    broken.stderr + brokenJson.stdout
  )

  // A generic body is checked once per instantiation, and the call it holds is
  // still one call in the source: it warns once.
  const genericSrc = path.join(buildDir, "deprecation_generic.ts")
  fs.writeFileSync(
    genericSrc,
    "const keep = <T>(x: T): T => {\n  const m = Arena.mark();\n  Arena.release(m);\n  return x;\n};\n\n" +
      'export const main = (): i32 => {\n  const s = keep("ab");\n  return keep(s.length);\n};\n'
  )
  const generic = compile(genericSrc, "deprecation_generic.ll", ["--json"])
  check(
    "deprecation: a call in a generic body instantiated twice warns once",
    generic.status === 0 &&
      diagnosticsOf(generic.stdout)
        .filter((o) => o.severity === "deprecation")
        .map((o) => `${o.code} ${o.line}:${o.column}`)
        .join(",") === "NL7001 3:3",
    generic.stdout + generic.stderr
  )

  // Independent of the performance class in both directions, and printed
  // before it. The program has one of each: a string rebuilt in a loop
  // (NL9002) and an `Arena.reset()`.
  const bothSrc = path.join(buildDir, "deprecation_both.ts")
  fs.writeFileSync(
    bothSrc,
    'export const main = (): number => {\n  let s = "";\n  for (let i = 0; i < 3; i = i + 1) {\n    s = s + "x";\n  }\n  const n = s.length;\n  Arena.reset();\n  return n;\n};\n'
  )
  const both = compile(bothSrc, "deprecation_both.ll")
  const bothJson = compile(bothSrc, "deprecation_both_json.ll", ["--json"])
  const quietPerf = compile(bothSrc, "deprecation_quiet_perf.ll", ["--no-warn-performance"])
  check(
    "deprecation: printed before the performance warnings, on stderr, and as objects on stdout under --json",
    both.status === 0 &&
      both.stderr.indexOf(": deprecation: ") >= 0 &&
      both.stderr.indexOf(": deprecation: ") < both.stderr.indexOf(": performance: ") &&
      bothJson.status === 0 &&
      diagnosticsOf(bothJson.stdout)
        .map((d) => `${d.severity} ${d.code}`)
        .join(",") === "deprecation NL7001,performance NL9002",
    both.stderr + bothJson.stdout + bothJson.stderr
  )
  check(
    "deprecation: --no-warn-performance does not silence it",
    quietPerf.status === 0 &&
      summaries(quietPerf.stderr).length === 1 &&
      !quietPerf.stderr.includes(": performance: "),
    quietPerf.stderr
  )

  // The cap the other reports have, with the class's own words.
  const manySrc = path.join(buildDir, "deprecation_many.ts")
  fs.writeFileSync(
    manySrc,
    Array.from({ length: 25 }, (_, i) => `export const f${i} = (): void => {\n  Arena.reset();\n};`).join(
      "\n"
    ) + "\n"
  )
  const many = compile(manySrc, "deprecation_many.ll")
  check(
    "deprecation: 25 warnings print 20, then `...and 5 more deprecation warnings` and `25 deprecation warnings`",
    many.status === 0 &&
      summaries(many.stderr).length === 20 &&
      many.stderr.includes("\n...and 5 more deprecation warnings\n25 deprecation warnings"),
    many.stderr
  )

  // `--fix` answers what is left as a plain run would, warnings included: no
  // fix applies to a deprecated call, so the file stays as it is and each call
  // still warns, in either form.
  const fixDir = path.join(buildDir, "deprecation-fix")
  fs.rmSync(fixDir, { recursive: true, force: true })
  fs.mkdirSync(fixDir, { recursive: true })
  const fixSrc = path.join(fixDir, "mem_arena_builtins.ts")
  fs.copyFileSync(builtins, fixSrc)
  const fixed = spawnSync(NISH, ["--fix", fixSrc], { cwd: root, encoding: "utf8" })
  const fixedJson = spawnSync(NISH, ["--fix", "--json", fixSrc], { cwd: root, encoding: "utf8" })
  check(
    "deprecation: --fix leaves Arena.release and Arena.reset as written and still warns for each, in either form, and exits 0",
    fixed.status === 0 &&
      summaries(fixed.stderr).length === 2 &&
      fixed.stderr.includes(`${fixSrc}:27:3: deprecation: \`Arena.release\` is deprecated: `) &&
      fixed.stderr.includes(`${fixSrc}:31:3: deprecation: \`Arena.reset\` is deprecated: `) &&
      fixedJson.status === 0 &&
      diagnosticsOf(fixedJson.stdout)
        .map((d) => `${d.severity} ${d.code} ${d.line}:${d.column}`)
        .join(",") === "deprecation NL7001 27:3,deprecation NL7001 31:3" &&
      fs.readFileSync(fixSrc, "utf8") === fs.readFileSync(builtins, "utf8"),
    fixed.stderr + fixedJson.stdout + fixedJson.stderr
  )

  // `nish run` prints it too, ahead of the program's own output: the author
  // of a script is the reader who has to hear it.
  if (HAS_CLANG) {
    const ran = spawnSync(NISH, ["run", builtins], {
      cwd: root,
      encoding: "utf8",
      env: { ...process.env, XDG_CACHE_HOME: path.join(buildDir, "deprecation-run-cache") },
    })
    check(
      "deprecation: `nish run` prints the warnings on stderr and runs the program, whose stdout is its own",
      ran.status === 0 &&
        summaries(ran.stderr).length === 2 &&
        ran.stdout === fs.readFileSync(path.join(casesDir, "mem_arena_builtins.out"), "utf8"),
      ran.stdout + ran.stderr
    )
  } else {
    skip("deprecation: `nish run` needs clang")
  }
}

// ---- Machine-applicable fixes: tests/fix/ --------------------------------------------
// A diagnostic may carry `fix`, a list of edits that `nish --fix` applies
// (`src/fix.ts`, AGENTS.md "Machine-readable surfaces"). Each case runs on a copy
// in a directory of its own, because `--fix` rewrites the file it is given:
// `<name>.ts` must come out as `<name>.fixed.ts` byte for byte and that must
// compile clean, and `<name>.nofix.ts` must be reported with no `fix` key and
// come out untouched. A directory is a case with more than one file, for what
// the command line decides: which files are named, and which may be rewritten.
// `tests/fix/README.md` is the table.
{
  // A case's sidecar, trimmed, or `fallback` when it has none.
  const sidecar = (file, fallback) => (fs.existsSync(file) ? fs.readFileSync(file, "utf8").trim() : fallback)
  // A plain run exits 1 on an error and 0 on a program whose only diagnostics
  // are warnings, so a warning's fix names its plain status in `plain-exit`.
  const plainExit = (file) => Number(sidecar(file, "1"))
  // `code` names the diagnostic a case is about, so a case whose diagnostic
  // stopped firing fails rather than passing for having nothing to fix.
  // After the fix it is checked the other way: a fixed program no longer
  // reports it, so a fix that leaves its own diagnostic standing fails.
  const codeCheck = (name, file, run, present = true) => {
    const code = sidecar(file, "")
    if (code.length > 0) {
      check(
        present ? `fix ${name}: reports ${code}` : `fix ${name}: the fixed program no longer reports ${code}`,
        diagnosticsOf(run.stdout).some((d) => d.code === code) === present,
        shown(run)
      )
    }
  }
  const fixDir = path.join(root, "tests", "fix")
  // Every file of a directory case, as paths relative to it, depth first.
  const filesUnder = (dir, prefix = "") =>
    fs
      .readdirSync(path.join(dir, prefix), { withFileTypes: true })
      .flatMap((e) =>
        e.isDirectory() ? filesUnder(dir, path.join(prefix, e.name)) : [path.join(prefix, e.name)]
      )
      .sort()
  // A case's `node-modules/` is its `node_modules/`, renamed so git keeps it.
  const workPath = (rel) => rel.replace(/^node-modules(?=\/)/, "node_modules")
  const CONTROL = new Set(["argv", "code", "exit", "plain-exit", "rewrites", "same-as-plain"])
  for (const name of fs.readdirSync(fixDir).sort()) {
    const caseDir = path.join(fixDir, name)
    if (!fs.statSync(caseDir).isDirectory() || (only && !name.includes(only) && !"fix".includes(only))) {
      continue
    }
    const work = fs.mkdtempSync(path.join(os.tmpdir(), "nish-fix-"))
    const sources = filesUnder(caseDir).filter((f) => f.endsWith(".ts") && !f.endsWith(".fixed.ts"))
    for (const rel of filesUnder(caseDir).filter((f) => !CONTROL.has(f) && !f.endsWith(".fixed.ts"))) {
      fs.mkdirSync(path.dirname(path.join(work, workPath(rel))), { recursive: true })
      fs.copyFileSync(path.join(caseDir, rel), path.join(work, workPath(rel)))
    }
    const argv = fs.readFileSync(path.join(caseDir, "argv"), "utf8").trim().split(/\s+/)
    const exitFile = path.join(caseDir, "exit")
    const wantExit = fs.existsSync(exitFile) ? Number(fs.readFileSync(exitFile, "utf8").trim()) : 0
    // `same-as-plain`: what --fix finally reports is what a plain run reports
    // about the files it leaves, byte for byte, which a plain run that stops at
    // its first refused root may say before it reaches any fix.
    const samePlain = fs.existsSync(path.join(caseDir, "same-as-plain"))
    if (!samePlain) {
      const plain = spawnSync(NISH, ["--json", ...argv, "-o", "plain/"], { cwd: work, encoding: "utf8" })
      check(
        `fix ${name}: --json carries a \`fix\``,
        plain.status === plainExit(path.join(caseDir, "plain-exit")) &&
          diagnosticsOf(plain.stdout).some((d) => Array.isArray(d.fix) && d.fix.length > 0),
        shown(plain)
      )
      codeCheck(name, path.join(caseDir, "code"), plain)
    }
    const fixed = spawnSync(NISH, ["--fix", "--json", ...argv], { cwd: work, encoding: "utf8" })
    // Each source comes out as its `.fixed.ts`, or byte-identical when it has none.
    const wrong = sources.filter((rel) => {
      const expectedFile = path.join(caseDir, rel.replace(/\.ts$/, ".fixed.ts"))
      const expected = fs.readFileSync(fs.existsSync(expectedFile) ? expectedFile : path.join(caseDir, rel))
      return !fs.readFileSync(path.join(work, workPath(rel))).equals(expected)
    })
    check(
      `fix ${name}: --fix exits ${wantExit}, rewrites each file with a .fixed.ts to it and leaves every other byte-identical`,
      fixed.status === wantExit && wrong.length === 0,
      `${shown(fixed)}\nnot as expected: ${wrong.join(", ")}`
    )
    const rewritesFile = path.join(caseDir, "rewrites")
    if (fs.existsSync(rewritesFile)) {
      const want = Number(fs.readFileSync(rewritesFile, "utf8").trim())
      const rewrites = fixed.stderr.split("\n").filter((l) => l.startsWith("fixed ")).length
      check(`fix ${name}: --fix rewrites a file ${want} times`, rewrites === want, shown(fixed))
    }
    if (samePlain) {
      const plainJson = spawnSync(NISH, ["--json", ...argv, "-o", "plain/"], { cwd: work, encoding: "utf8" })
      check(
        `fix ${name}: --fix --json reports what a plain --json run reports about the result, byte for byte`,
        fixed.status === plainJson.status && fixed.stdout === plainJson.stdout,
        `--fix:\n${shown(fixed)}\nplain:\n${shown(plainJson)}`
      )
      codeCheck(name, path.join(caseDir, "code"), plainJson)
      // The human report too, from a second --fix with nothing left to apply.
      const again = spawnSync(NISH, ["--fix", ...argv], { cwd: work, encoding: "utf8" })
      const plainHuman = spawnSync(NISH, [...argv, "-o", "plain/"], { cwd: work, encoding: "utf8" })
      check(
        `fix ${name}: --fix reports what a plain run reports about the result, byte for byte`,
        again.status === plainHuman.status &&
          again.stdout === plainHuman.stdout &&
          again.stderr === plainHuman.stderr,
        `--fix:\n${shown(again)}\nplain:\n${shown(plainHuman)}`
      )
    } else if (wantExit === 0) {
      const clean = spawnSync(NISH, ["--json", ...argv, "-o", "clean/"], { cwd: work, encoding: "utf8" })
      check(
        `fix ${name}: the fixed program compiles with no error and nothing left to fix`,
        clean.status === 0 &&
          diagnosticsOf(clean.stdout).every((d) => d.severity !== "error" && !("fix" in d)),
        shown(clean)
      )
      codeCheck(name, path.join(caseDir, "code"), clean, false)
    } else {
      // What --fix may not apply is still reported, fix and all.
      check(
        `fix ${name}: the fix --fix may not apply is still reported with it`,
        diagnosticsOf(fixed.stdout).some((d) => Array.isArray(d.fix) && d.fix.length > 0),
        shown(fixed)
      )
    }
    fs.rmSync(work, { recursive: true, force: true })
  }
  const inputs = fs
    .readdirSync(fixDir)
    .filter((f) => f.endsWith(".ts") && !f.endsWith(".fixed.ts"))
    .sort()
  for (const file of inputs) {
    const noFix = file.endsWith(".nofix.ts")
    const name = file.slice(0, -(noFix ? ".nofix.ts" : ".ts").length)
    if (only && !name.includes(only) && !"fix".includes(only)) {
      continue
    }
    const work = fs.mkdtempSync(path.join(os.tmpdir(), "nish-fix-"))
    const input = fs.readFileSync(path.join(fixDir, file))
    fs.writeFileSync(path.join(work, file), input)
    const plain = spawnSync(NISH, ["--json", file, "-o", "plain.ll"], { cwd: work, encoding: "utf8" })
    const plainObjects = diagnosticsOf(plain.stdout)
    const fixed = spawnSync(NISH, ["--fix", "--json", file], { cwd: work, encoding: "utf8" })
    const after = fs.readFileSync(path.join(work, file))
    const wantPlain = plainExit(path.join(fixDir, `${name}.plain-exit`))
    codeCheck(name, path.join(fixDir, `${name}.code`), plain)
    if (noFix) {
      // A refused shape must name the diagnostic it was written for: with
      // nothing to apply, a case whose diagnostic stopped firing, or that
      // another diagnostic now stops first, would otherwise pass for having
      // no fix.
      check(
        `fix ${name}: ${name}.code names the diagnostic the refused shape is about`,
        sidecar(path.join(fixDir, `${name}.code`), "").length > 0
      )
      check(
        `fix ${name}: reported with no \`fix\` key`,
        plain.status === wantPlain && plainObjects.length > 0 && plainObjects.every((d) => !("fix" in d)),
        shown(plain)
      )
      check(
        `fix ${name}: --fix leaves the file byte-identical and exits as the plain compile does`,
        fixed.status === plain.status && after.equals(input) && fixed.stdout === plain.stdout,
        shown(fixed)
      )
    } else {
      const expected = fs.readFileSync(path.join(fixDir, `${name}.fixed.ts`))
      check(
        `fix ${name}: --json carries a \`fix\``,
        plain.status === wantPlain && plainObjects.some((d) => Array.isArray(d.fix) && d.fix.length > 0),
        shown(plain)
      )
      check(
        `fix ${name}: --fix exits 0 and writes ${name}.fixed.ts byte for byte`,
        fixed.status === 0 && after.equals(expected),
        `${shown(fixed)}\nwrote:\n${after}`
      )
      const roundsFile = path.join(fixDir, `${name}.rounds`)
      if (fs.existsSync(roundsFile)) {
        const want = Number(fs.readFileSync(roundsFile, "utf8").trim())
        const rounds = fixed.stderr.split("\n").filter((l) => l.startsWith(`fixed ${file} `)).length
        check(`fix ${name}: --fix takes ${want} rounds`, rounds === want, shown(fixed))
      }
      fs.writeFileSync(path.join(work, `${name}.fixed.ts`), expected)
      // A directory, so a fixed program that imports a module (`nish/threads`) is
      // written as one `.ll` per module rather than refused for being several.
      const clean = spawnSync(NISH, ["--json", `${name}.fixed.ts`, "-o", "fixed/"], {
        cwd: work,
        encoding: "utf8",
      })
      check(
        `fix ${name}: ${name}.fixed.ts compiles with no error and nothing left to fix`,
        clean.status === 0 &&
          diagnosticsOf(clean.stdout).every((d) => d.severity !== "error" && !("fix" in d)),
        shown(clean)
      )
      codeCheck(name, path.join(fixDir, `${name}.code`), clean, false)
      // `<name>.stdout`: the fix changes nothing the program does. The input
      // and its `.fixed.ts` are linked and run, and both print this and exit
      // with `<name>.run-exit` (default 0), which for an index out of range is
      // the runtime's index error before the fix and the guard's panic after.
      const stdoutFile = path.join(fixDir, `${name}.stdout`)
      if (fs.existsSync(stdoutFile) && !HAS_CLANG) {
        skip(`fix ${name}: the round trip needs clang`)
      } else if (fs.existsSync(stdoutFile)) {
        const want = fs.readFileSync(stdoutFile, "utf8")
        const wantRun = Number(sidecar(path.join(fixDir, `${name}.run-exit`), "0"))
        fs.writeFileSync(path.join(work, `${name}.orig.ts`), input)
        for (const source of [`${name}.orig.ts`, `${name}.fixed.ts`]) {
          const exe = path.join(work, source.replace(/\.ts$/, ""))
          const built = spawnSync(NISH, [source, "-o", `${exe}.ll`, "--link", exe], {
            cwd: work,
            encoding: "utf8",
          })
          const ran = built.status === 0 ? spawnSync(exe, [], { encoding: "utf8" }) : built
          check(
            `fix ${name}: ${source} prints ${name}.stdout and exits ${wantRun}`,
            built.status === 0 && ran.status === wantRun && ran.stdout === want,
            shown(ran)
          )
        }
      }
    }
    fs.rmSync(work, { recursive: true, force: true })
  }
}

// ---- WP5: link -------------------------------------------------------------------
// Multi-module programs in tests/link/<name>/. `main.ts` is the entry; the program is
// compiled with `-o <dir>/` (one .ll per module) and `--link` (scripts/build.sh, speed
// profile) into build/test/link/<name>/app. Nothing can print yet (console.log is
// WP3), so each program returns its result from `main` and the harness compares the
// process exit code with `expected.code`; `expected.out` is the expected stdout
// (empty for now). Other optional files:
//   expected.err   compile must fail and stderr must contain this text
//   expected.json  beside expected.err: the `--json` diagnostics of the refused compile,
//                  one object per line and paths relative to the repository, compared
//                  whole. One needle pins one diagnostic; this pins a program that has
//                  to be refused at several sites (tests/nish/run.ts reads only the
//                  needle, so expected.err keeps it)
//   expected.ir    lines (substring match) that must appear in some emitted module
//   expected.caps.json  the `--emit-capabilities` report, byte for byte (WP35)
//   expected.portability  the `--warn-portability --json` portability objects, one per
//                  line, as a case's `.portability` (WP33): a second compile with the
//                  flag, which must write the same modules byte for byte. It is here for
//                  a program a case cannot be, one that imports `nish/threads`
//   args           extra CLI flags (e.g. --strict-exports)
//   <module>.ll    golden IR for that module (header stripped, like tests/cases). Only a
//                  module with a golden is compared, so there is no missing one to write;
//                  `--update-link-goldens` rewrites each golden that differs from what
//                  this run's compiler emitted, prints `WROTE link/<name>/<module>.ll`,
//                  and compares again. Narrow it with a filter
//                  (`node tests/run.js <name> --update-link-goldens`) and read the diff
//                  before committing it, as for any regenerated golden.
// Every positive test is also assembled (llvm-as), verified (opt -passes=verify),
// and checked for cross-module attribute agreement: each `declare` of a user
// function in an importer must match the exporter's `define` attribute for attribute.
const linkDir = path.join(root, "tests", "link")
const linkTests = fs.existsSync(linkDir)
  ? fs
      .readdirSync(linkDir)
      .filter((d) => fs.existsSync(path.join(linkDir, d, "main.ts")))
      .sort()
  : []
const HAS_OPT = has("opt")
const UPDATE_LINK_GOLDENS = process.argv.includes("--update-link-goldens")

/** Parse `define`/`declare` headers into { name -> { kind, sig, attrs } } with attribute groups resolved. */
const functionHeaders = (ir) => {
  const groups = new Map()
  for (const m of ir.matchAll(/^attributes (#\d+) = \{ (.*) \}$/gm)) {
    groups.set(m[1], m[2])
  }
  const out = new Map()
  // `$` is part of a symbol name, not a word character: WP18 mangles an
  // instantiation as `identity$i32`, and a pattern without it silently found no
  // cross-module generic at all — which is exactly the pair this check exists
  // to compare since G7 put the `define` and the `declare` in two modules.
  // `hidden` is WP29's: a private function another module's instantiation
  // calls is in the link but exported from nothing, and its `declare` in that
  // module has the same signature and attributes as any other.
  for (const m of ir.matchAll(
    /^(define|declare) (?:internal |hidden )?(.*?) @([\w.$]+)\((.*?)\)(?: (#\d+))?(?: \{)?$/gm
  )) {
    const params = m[4].replace(/ %[\w.]+(?=,|$)/g, "") // drop parameter names: declares have none
    out.set(m[3], { kind: m[1], sig: `${m[2]} (${params})`, attrs: m[5] ? (groups.get(m[5]) ?? m[5]) : "" })
  }
  return out
}

/** `indexOfAny`'s refused sets, each a link program and the panic it ends in (read after the loop). */
const INDEX_OF_ANY_REFUSALS = [
  ["std_text_index_of_any_empty_set", "indexOfAny: the set must hold 1 to 16 bytes"],
  ["std_text_index_of_any_long_set", "indexOfAny: the set must hold 1 to 16 bytes"],
  ["std_text_index_of_any_non_ascii_set", "indexOfAny: every byte of the set must be ASCII"],
]

/**
 * The link programs whose output a check after the loop reads: by path, from
 * `build/test/link/<name>/`. They always run in shard 1, the shard that makes
 * those checks; a new check that reads another program's output adds its name
 * here, or it reads nothing in a sharded run.
 */
const LINK_READ_LATER = [
  "net_tls_resume_bench",
  "par_dst_short",
  "par_map_idle",
  "par_map_join_small",
  "par_map_reclaim",
  "par_map_release",
  "range_export",
  "range_export_dts",
  "range_export_foreign",
  "range_export_header",
  "range_export_napi",
  "range_export_napi_async",
  "range_export_unproven",
  ...INDEX_OF_ANY_REFUSALS.map(([name]) => name),
  "std_json_conformance",
  "std_json_tokenizer",
  "std_json_typed",
  "std_json_value",
  "thread_channel_string_many",
  "thread_scope_reclaim",
  "thread_task_release",
  "unsafe_flag_scope",
]
/**
 * The sections after the link programs that are dealt like them rather than
 * run by shard 1: each runs in the shard `sectionShard` names, sits before the
 * point where every other shard stops, and reads nothing a section after that
 * point writes. The key is its cost's in `tests/shard-costs.json`; `selected`
 * says whether the run's filter selects it, which is also whether it is dealt.
 */
const DEALT_SECTIONS = {
  selfHosting: {
    name: "the WP14 self-hosting section",
    selected: !only || "selfhost".includes(only) || only.includes("self"),
  },
  cryptoBench: { name: "the crypto-bench section", selected: !only || "crypto-bench".includes(only) },
}
/**
 * The shard each link program runs in, and the shard each of `DEALT_SECTIONS`
 * runs in: a greedy deal by cost, so that the shards finish together.
 * `tests/shard-costs.json` holds the seconds each piece took in a CI shard --
 * `link` per program, one entry per dealt section under its key, and
 * `shardOne` for what only shard 1 runs: every other section after the link
 * programs and its job's steps after the suite. Shard 1 starts with that and
 * its `LINK_READ_LATER` programs; the rest go largest first, ties by name, each
 * to the shard with the least so far (the lowest number of those tied). A
 * program the table does not name yet costs the table's median, so a new one
 * moves the deal without waiting for a measurement. The deal reads nothing a
 * run measures, so every shard of one CI run computes the same one.
 *
 * A filtered run deals only what its filter selects, and starts shard 1 at
 * nothing, since the sections it alone runs are filtered too: dealt from the
 * whole table, the 188 `net_` programs the macOS `runtime-net` job runs fell
 * 1.3, 4.2, 7.4 and 7.6 minutes to its four shards rather than about 5 each.
 */
const { linkShard, sectionShard } = (() => {
  const costs = JSON.parse(fs.readFileSync(path.join(root, "tests", "shard-costs.json"), "utf8"))
  const known = Object.values(costs.link).sort((a, b) => a - b)
  const cost = (name) => costs.link[name] ?? known[known.length >> 1] ?? 1
  const shardOf = new Map()
  const load = Array.from({ length: SHARDS }, () => 0)
  load[0] = only ? 0 : costs.shardOne
  const items = Object.entries(DEALT_SECTIONS)
    .filter(([, section]) => section.selected)
    .map(([key]) => ({ section: key, cost: costs[key] ?? 1 }))
  for (const name of linkTests) {
    if (only && !name.includes(only)) {
      continue
    }
    if (SHARDS === 1 || LINK_READ_LATER.includes(name)) {
      shardOf.set(name, 1)
      load[0] += cost(name)
    } else {
      items.push({ name, cost: cost(name) })
    }
  }
  const label = (item) => item.name ?? item.section
  items.sort((a, b) => b.cost - a.cost || label(a).localeCompare(label(b)))
  const sections = new Map()
  for (const item of items) {
    const least = load.indexOf(Math.min(...load))
    load[least] += item.cost
    if (item.section !== undefined) {
      sections.set(item.section, least + 1)
    } else {
      shardOf.set(item.name, least + 1)
    }
  }
  return { linkShard: (name) => shardOf.get(name), sectionShard: (key) => sections.get(key) }
})()
/**
 * `--delegate-ir-checks`, which the macOS `runtime-net` job passes: of each link
 * program, link it and run it, and leave every check of the compile -- the
 * module goldens, llvm-as and opt, the declare/define agreement, expected.ir,
 * `--warn-portability`, `--emit-panics`, the capability report, and the
 * programs that are a rejection and nothing else -- to the `test` job, which
 * runs every tests/link program on Linux with the same compiler. Those checks
 * read the compiler's output, not the host, and were a third of that job's
 * link programs' time (run 39878648000). Honoured only under GitHub Actions, as `--delegate-fixed-point` is:
 * from a terminal the flag names a job that is not running, so every check
 * runs here. A check in the WP14 section holds ci.yml to it.
 */
const DELEGATE_IR_CHECKS = process.argv.includes("--delegate-ir-checks") && process.env.GITHUB_ACTIONS === "true"
let irDelegated = 0
const linkDealtAway = linkTests.filter((name) => (!only || name.includes(only)) && linkShard(name) !== SHARD)

for (const name of linkTests) {
  if (only && !name.includes(only)) {
    continue
  }
  if (linkShard(name) !== SHARD) {
    continue
  }
  const dir = path.join(linkDir, name)
  const side = (f) => path.join(dir, f)
  const read = (f) => fs.readFileSync(side(f), "utf8")
  const args = fs.existsSync(side("args")) ? read("args").trim().split(/\s+/).filter(Boolean) : []
  const outDir = path.join(buildDir, "link", name) + path.sep
  const exe = path.join(outDir, "app")
  fs.rmSync(outDir, { recursive: true, force: true })
  // WP35: the report is written beside the modules by the same compile, since
  // nothing here compares the IR of a second one.
  const capsJson = path.join(outDir, "capabilities.json")
  const capsArgs =
    !DELEGATE_IR_CHECKS && fs.existsSync(side("expected.caps.json")) ? ["--emit-capabilities", capsJson] : []
  if (DELEGATE_IR_CHECKS && fs.existsSync(side("expected.err"))) {
    irDelegated++
    continue
  }
  const r = spawnSync(NISH, [side("main.ts"), "-o", outDir, "--link", exe, ...args, ...capsArgs], {
    cwd: root,
  })
  const stderr = String(r.stderr)

  if (fs.existsSync(side("expected.err"))) {
    const needle = read("expected.err").trim()
    check(
      `link/${name}: rejected with "${needle}"`,
      r.status === 1 && stderr.includes(needle),
      stderr || "(compiled successfully)"
    )
    if (fs.existsSync(side("expected.json"))) {
      const json = spawnSync(NISH, [side("main.ts"), "-o", outDir, "--json", ...args], {
        cwd: root,
        encoding: "utf8",
      })
      const got = json.stdout.split(`${root}/`).join("").trim()
      const want = read("expected.json").trim()
      check(
        `link/${name}: --json reports every diagnostic in expected.json, and no other`,
        json.status === 1 && got === want,
        `--- expected\n${want}\n--- actual (exit ${json.status})\n${got}\n${json.stderr}`
      )
    }
    continue
  }
  if (r.status !== 0) {
    check(`link/${name}: compiles and links`, false, stderr)
    continue
  }
  if (DELEGATE_IR_CHECKS) {
    irDelegated++
  } else {
    // The `--emit-panics` compile below reads nothing this loop writes, so it
    // runs while the modules are checked rather than after them. Nothing between
    // here and its `await` leaves the iteration, so no compile outlives its program.
    const panicsDir = path.join(buildDir, "link-panics", name) + path.sep
    fs.rmSync(panicsDir, { recursive: true, force: true })
    const panicsFile = path.join(panicsDir, "panics.json")
    const listing = spawnAsync(NISH, [side("main.ts"), "-o", panicsDir, ...args, "--emit-panics", panicsFile], {
      cwd: root,
      encoding: "utf8",
    })

    const modules = fs
      .readdirSync(outDir)
      .filter((f) => f.endsWith(".ll"))
      .sort()
      .map((f) => ({ file: f, ir: fs.readFileSync(path.join(outDir, f), "utf8") }))
    // A program that imports std/net is about a hundred modules, and llvm-as and
    // opt read each one alone, so they run `defaultJobs()` modules at a time; the
    // checks are still made in module order, so the output is the sequential
    // loop's. One at a time they were a fifth of the runtime-net job's wall clock.
    const verified = await pool(modules, defaultJobs(), async (m) => ({
      as: HAS_LLVM_AS ? await spawnAsync("llvm-as", [path.join(outDir, m.file), "-o", "/dev/null"]) : null,
      v: HAS_OPT ? await spawnAsync("opt", ["-passes=verify", "-disable-output", path.join(outDir, m.file)]) : null,
    }))
    for (const [i, m] of modules.entries()) {
      if (fs.existsSync(side(m.file))) {
        const actual = stripHeader(m.ir)
        if (UPDATE_LINK_GOLDENS && read(m.file).trim() !== actual) {
          fs.writeFileSync(side(m.file), `${actual}\n`)
          console.log(`WROTE link/${name}/${m.file}`)
        }
        const expected = read(m.file).trim()
        check(
          `link/${name}: ${m.file} matches golden`,
          actual === expected,
          `--- expected\n${expected}\n--- actual\n${actual}`
        )
      }
      const { as, v } = verified[i]
      if (as !== null) {
        check(`link/${name}: llvm-as accepts ${m.file}`, as.status === 0, String(as.stderr))
      }
      if (v !== null) {
        check(`link/${name}: opt -passes=verify accepts ${m.file}`, v.status === 0, String(v.stderr))
      }
    }

    if (fs.existsSync(side("expected.portability"))) {
      const warnedDir = path.join(buildDir, "link", `${name}.portability`) + path.sep
      fs.rmSync(warnedDir, { recursive: true, force: true })
      const warned = spawnSync(
        NISH,
        [side("main.ts"), "-o", warnedDir, ...args, "--warn-portability", "--json"],
        {
          cwd: root,
          encoding: "utf8",
        }
      )
      const want = read("expected.portability").trim()
      const got = warned.stdout
        .split("\n")
        .filter((l) => l.includes('"severity":"portability"'))
        .join("\n")
        .split(`${root}/`)
        .join("")
      check(
        `link/${name}: --warn-portability --json matches expected.portability`,
        warned.status === 0 && got === want,
        `--- expected\n${want}\n--- actual (exit ${warned.status})\n${got}\n${warned.stderr}`
      )
      check(
        `link/${name}: --warn-portability changes no byte of the IR`,
        modules.every(
          (m) =>
            fs.existsSync(path.join(warnedDir, m.file)) &&
            fs.readFileSync(path.join(warnedDir, m.file), "utf8") === m.ir
        ),
        "the modules differ"
      )
    }

    // Cross-module attribute agreement: importer `declare` == exporter `define`.
    const defines = new Map()
    for (const m of modules) {
      for (const [sym, h] of functionHeaders(m.ir)) {
        if (h.kind === "define") {
          defines.set(sym, { ...h, file: m.file })
        }
      }
    }
    let declares = 0
    const mismatches = []
    for (const m of modules) {
      for (const [sym, h] of functionHeaders(m.ir)) {
        if (h.kind !== "declare" || !defines.has(sym)) {
          continue // runtime declares have no define here
        }
        declares++
        const d = defines.get(sym)
        if (h.sig !== d.sig || h.attrs !== d.attrs) {
          mismatches.push(
            `${m.file}: declare ${h.sig} { ${h.attrs} }\n${d.file}: define  ${d.sig} { ${d.attrs} }`
          )
        }
      }
    }
    check(
      `link/${name}: ${declares} imported declare(s) match their define(s) attribute for attribute`,
      declares > 0 && mismatches.length === 0,
      mismatches.join("\n") || "(no cross-module declares found)"
    )

    if (fs.existsSync(side("expected.ir"))) {
      const all = modules.map((m) => m.ir).join("\n")
      const missing = read("expected.ir")
        .split("\n")
        .map((l) => l.trim())
        .filter(Boolean)
        .filter((l) => !all.includes(l))
      check(
        `link/${name}: emitted IR contains every expected.ir line`,
        missing.length === 0,
        missing.map((l) => `missing: ${l}`).join("\n")
      )
    }

    // `--emit-panics` over the whole program, std/ and dependency modules
    // included, held against the IR of every module the same compile wrote
    // (`tests/panics-oracle.js`), and against `expected.panics` where the
    // program has one. Without `--link`, so the program is not linked twice:
    // the list and the IR come from one compile, which is all the oracle needs.
    // That compile was started beside the module checks above (`listing`).
    const listed = await listing
    if (listed.status !== 0 || !fs.existsSync(panicsFile)) {
      check(`link/${name}: --emit-panics writes the sites`, false, `exit ${listed.status}\n${listed.stderr}`)
    } else {
      const listText = fs.readFileSync(panicsFile, "utf8")
      const ir = fs
        .readdirSync(panicsDir)
        .filter((f) => f.endsWith(".ll"))
        .map((f) => fs.readFileSync(path.join(panicsDir, f), "utf8"))
        .join("\n")
      // The entry is named by the path it was given, `side("main.ts")`, and its
      // `.ll` is among those joined above, so its own functions are held to the
      // drift check too; a module of a library that writes no `.ll` of its own
      // stays skipped (`panicOracle`'s `module`).
      const oracle = panicOracle(ir, JSON.parse(listText), side("main.ts"))
      check(
        `link/${name}: --emit-panics agrees with the IR of every module, the entry's functions all defined`,
        oracle.failures.length === 0 && oracle.own > 0,
        oracle.own > 0
          ? oracle.failures.join("\n")
          : `no listed function names ${side("main.ts")} as its module`
      )
      if (fs.existsSync(side("expected.panics"))) {
        const want = read("expected.panics").trim()
        const got = listText.split(`${root}/`).join("").trim()
        check(
          `link/${name}: --emit-panics matches expected.panics`,
          got === want,
          `--- expected\n${want}\n--- actual\n${got}`
        )
      }
    }

    if (capsArgs.length > 0) {
      const want = read("expected.caps.json")
      const got = fs.existsSync(capsJson) ? fs.readFileSync(capsJson, "utf8") : ""
      check(
        `link/${name}: --emit-capabilities matches expected.caps.json byte for byte`,
        got === want,
        `--- expected\n${want}\n--- actual\n${got}`
      )
    }
  }

  const run = await runNative(`link/${name}`, exe, [])
  if (run.death !== null) {
    check(run.death, false, `stdout so far:\n${run.stdout}${run.stderr}`)
    continue
  }
  const wantCode = Number(read("expected.code").trim())
  const wantOut = fs.existsSync(side("expected.out")) ? read("expected.out").trim() : ""
  check(
    `link/${name}: exits with ${wantCode} and stdout matches expected.out`,
    run.status === wantCode && String(run.stdout).trim() === wantOut,
    `--- expected exit ${wantCode}, stdout:\n${wantOut}\n--- actual exit ${run.status}, stdout:\n${run.stdout}${run.stderr}`
  )
  // The worker pool (docs/wp20-threads.md §8e) at the two sizes a default run on a
  // big machine never sees: no workers, where the caller runs every task in spawn
  // order, and one; and at eight, more threads than a small runner has cores.
  // wp29 C6's no-deadlock argument for channels rests on the pool's queue order
  // at every size, so a threads program prints the same at each.
  if (/^(thread|par)_/.test(name)) {
    for (const threads of ["1", "2", "8"]) {
      const sized = await runNative(`link/${name} (NISH_NUM_THREADS=${threads})`, exe, [], {
        env: envWithThreads(threads),
      })
      check(
        sized.death ?? `link/${name}: the same exit and stdout under NISH_NUM_THREADS=${threads}`,
        sized.death === null && sized.status === wantCode && String(sized.stdout).trim() === wantOut,
        `--- actual exit ${sized.status}, stdout:\n${sized.stdout}${sized.stderr}`
      )
    }
  }
  // A program whose threads all panic prints exactly one whole message: the
  // first panic claims the process, prints and `_exit`s, and every later one
  // parks (`nish_panic_claim`, runtime/runtime.c). Each thread's message is the
  // same, so a second print, or two interleaved, is a stderr that differs from
  // expected.stderr. Run often, at two pool sizes: a race shows as some runs
  // differing, never as a slow one.
  if (fs.existsSync(side("expected.stderr"))) {
    const wantErr = read("expected.stderr")
    const bad = []
    for (let i = 0; i < PANIC_ONCE_RUNS && bad.length === 0; i++) {
      for (const threads of ["2", "8"]) {
        const once = await runNative(`link/${name} (run ${i}, NISH_NUM_THREADS=${threads})`, exe, [], {
          env: envWithThreads(threads),
        })
        if (once.death !== null || once.status !== wantCode || String(once.stderr) !== wantErr) {
          bad.push(
            `run ${i}, NISH_NUM_THREADS=${threads}: exit ${once.status}, stderr ${JSON.stringify(String(once.stderr))}`
          )
        }
      }
    }
    check(
      `link/${name}: every one of ${PANIC_ONCE_RUNS} runs at 2 and 8 threads prints expected.stderr once and exits ${wantCode}`,
      bad.length === 0,
      `--- expected stderr ${JSON.stringify(wantErr)}\n${bad.join("\n")}`
    )
  }
}

/** The `.ll` files an output directory holds, in name order. */
const llFilesIn = (dir) =>
  fs.existsSync(dir)
    ? fs
        .readdirSync(dir)
        .filter((f) => f.endsWith(".ll"))
        .sort()
    : []

// ---- WP14: self-hosting ---------------------------------------------------------------
// `src/` is the compiler written in Nish (docs/wp14-selfhost.md), and the
// compiler every other section of this file runs. It is checked here rather than
// in tests/cases because it is a program, not a construct: the floor is that it
// compiles every module of itself cleanly, and above that stand the oracles that
// hold each phase to something outside it and the bootstrap's fixed point. It
// sits here, where the split of a sharded run ends, because it is the one
// section after the link programs that is dealt like them: it runs in the shard
// `sectionShard("selfHosting")` names, and reads nothing the sections after it write.
if (DEALT_SECTIONS.selfHosting.selected && SHARD === sectionShard("selfHosting")) {
  const selfDir = path.join(root, "src")
  const modules = fs.existsSync(selfDir)
    ? fs
        .readdirSync(selfDir)
        .filter((f) => f.endsWith(".ts"))
        .sort()
    : []
  check("src/ has at least one module", modules.length > 0, `${modules.length} modules`)
  // The property is "the compiler accepts every module of src/", and one root per
  // module proved it at the price of 58 process starts and 58 walks of the
  // module graph -- about a minute of every run. Named together they are one
  // walk and prove the same thing, so the batch is the fast path and the loop
  // below is the fallback that says *which* module failed: a green batch is
  // reported as the same 58 checks under the same names, and a red one is
  // re-run module by module so the failure is attributed rather than dumped.
  //
  // The entry points are compiled apart from the rest because only the entry
  // module may declare `export function main`, so naming two of them in one
  // command produces that diagnostic instead of a build. They are found the
  // way scripts/smoke.sh finds them, and for the same reason: both spellings
  // are legal (docs/wp22-arrow-functions.md).
  const out = path.join(buildDir, "self")
  fs.mkdirSync(out, { recursive: true })
  // `src/compile.ts` is compiled under `--json`, which moves its report to
  // stdout as one object per diagnostic: the performance ratchet below counts
  // that compile's warnings, so the count costs no compile of its own.
  const RATCHETED = "compile.ts"
  let ratchetedRun = null
  const compileSelf = (names) => {
    const ratcheted = names.length === 1 && names[0] === RATCHETED
    const r = spawnSync(
      NISH,
      [...names.map((m) => path.join(selfDir, m)), "-o", `${out}/`, ...(ratcheted ? ["--json"] : [])],
      { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
    )
    if (ratcheted) {
      ratchetedRun = r
    }
    return r
  }
  const declaresMain = (m) =>
    /^export (function main\b|const main\s*=)/m.test(fs.readFileSync(path.join(selfDir, m), "utf8"))
  const entries = modules.filter(declaresMain)
  const groups = [modules.filter((m) => !declaresMain(m)), ...entries.map((m) => [m])]
  const batched = groups.every((g) => g.length === 0 || compileSelf(g).status === 0)
  for (const m of modules) {
    // `batched` is the whole answer when it is true; when it is false one of
    // the groups failed and every module is compiled alone to find out which.
    const r = batched ? null : compileSelf([m])
    check(`src/${m} compiles`, batched || r.status === 0, batched ? "" : `${r.stderr}${r.stdout}`)
  }

  // The performance ratchet. `std/` and `examples/` are held to zero warnings
  // (the performance gate above); the compiler's own source is not there yet,
  // so it is held to the count it has, per file and per code, in
  // tests/perf-baseline.json, and the count may only fall. A warning more than
  // the baseline fails and names the warnings of that file and code, among
  // which the new one is. A warning fewer fails too, asking for the baseline to
  // come down to the new count, because a cap that is never lowered lets the
  // next warning in for free. Counted from `--json` by `code`, never from the
  // report, which stops printing at 20 (`.claude/testing.md`).
  if (ratchetedRun === null) {
    check(`performance ratchet: src/${RATCHETED} was compiled, so its warnings can be counted`, false)
  } else {
    const baselineFile = path.join(root, "tests", "perf-baseline.json")
    const baseline = JSON.parse(fs.readFileSync(baselineFile, "utf8")).counts
    const warnings = diagnosticsOf(ratchetedRun.stdout)
      .filter((d) => d.severity === "performance")
      // The modules were named by absolute path, and a diagnostic names its
      // file the way it was reached; the baseline is keyed by the repository's
      // own spelling so it reads the same on every checkout.
      .map((d) => ({
        ...d,
        file: path.relative(root, path.resolve(root, d.file)).split(path.sep).join("/"),
      }))
    const actual = {}
    for (const d of warnings) {
      actual[d.file] ??= {}
      actual[d.file][d.code] = (actual[d.file][d.code] ?? 0) + 1
    }
    const over = []
    const under = []
    for (const file of [...new Set([...Object.keys(baseline), ...Object.keys(actual)])].sort()) {
      const want = baseline[file] ?? {}
      const got = actual[file] ?? {}
      for (const code of [...new Set([...Object.keys(want), ...Object.keys(got)])].sort()) {
        const allowed = want[code] ?? 0
        const count = got[code] ?? 0
        if (count > allowed) {
          const named = warnings
            .filter((d) => d.file === file && d.code === code)
            .map((d) => `        ${diagnosticLine(d)}`)
          over.push(
            `${file} ${code}: ${count}, the baseline allows ${allowed}; one of these is new:\n${named.join("\n")}`
          )
        } else if (count < allowed) {
          const edit = count === 0 ? "remove it from" : `set it to ${count} in`
          under.push(
            `${file} ${code}: ${count}, the baseline says ${allowed}; ${edit} tests/perf-baseline.json`
          )
        }
      }
    }
    const total = warnings.length
    check(
      `performance ratchet: src/${RATCHETED} has no performance warning past tests/perf-baseline.json (${total} today)`,
      ratchetedRun.status === 0 && over.length === 0,
      ratchetedRun.status !== 0 ? `${ratchetedRun.stdout}${ratchetedRun.stderr}` : over.join("\n")
    )
    check(
      `performance ratchet: tests/perf-baseline.json is lowered to src/${RATCHETED}'s count wherever the count fell`,
      ratchetedRun.status === 0 && under.length === 0,
      `${under.join("\n")}\nA warning proven away is progress; the baseline comes down with it so it cannot come back.`
    )
  }
  // Module constants are the reason `src/` can name its token kinds at all: if
  // one ever became a global, every kind would cost a load on the lexer's hot path.
  const tokensLl = path.join(buildDir, "self", "tokens.ll")
  if (fs.existsSync(tokensLl)) {
    const ir = fs.readFileSync(tokensLl, "utf8")
    check(
      "src/tokens.ts emits no global for its token kinds",
      !/^@(?!\.str\.)/m.test(ir),
      ir
        .split("\n")
        .filter((l) => l.startsWith("@"))
        .join(" | ")
    )
  }

  // The DWARF `producer` string is "nish <version>", and stage1 cannot read
  // package.json to find the version, so it is a constant in `src/branding.ts`.
  // This is what stops that constant going stale: a disagreement here is a
  // `--version` and a byte of every `-g` module that name the wrong release.
  const brandingTs = path.join(root, "src", "branding.ts")
  if (fs.existsSync(brandingTs)) {
    const branding = fs.readFileSync(brandingTs, "utf8")
    const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"))
    check(
      `src/branding.ts names the CLI and the version package.json does (nish ${pkg.version})`,
      branding.includes(`export const CLI: string = "nish"`) &&
        branding.includes(`export const VERSION: string = "${pkg.version}"`),
      branding
        .split("\n")
        .filter((l) => l.startsWith("export const"))
        .join(" | ")
    )
  }

  // stage1 cannot read `std/` to list it: `src/` has to compile under the last
  // *released* compiler (the WP19 G2 gate), and `readdirSync` is newer than
  // that release, so `src/std-modules.ts` carries the list as a literal. This
  // is what stops the literal going stale: a module added to `std/` at any
  // depth and not to the list would be one the "not part of the standard
  // library" diagnostic leaves out, and no golden triggers that by chance.
  // Each module is listed by its specifier tail, `std/crypto/sha256.ts` as
  // `crypto/sha256`.
  {
    const actual = stdModuleFiles()
      .map((f) => f.slice("std/".length, -".ts".length))
      .sort()
      .join(", ")
    const stage1 = fs.readFileSync(path.join(root, "src", "std-modules.ts"), "utf8")
    // The formatter may break the arrow before a long literal, so the literal
    // is read from the declaration wherever it wrapped.
    const listed = /stdModuleNames = \(\): string =>\s*"([^"]*)"/.exec(stage1)
    check(
      `src/std-modules.ts lists the modules std/ actually has (${actual})`,
      listed !== null && listed[1] === actual,
      listed === null
        ? 'no `stdModuleNames = (): string => "..."` in src/std-modules.ts'
        : `it lists: ${listed[1]}`
    )

    // And the third party to that contract, added 2026-09-20: the release
    // tarball's presence gate. `std/` was not staged at all for four releases,
    // and the gate that exists to catch exactly that listed seven paths and
    // none of them under `std/`. Naming the modules there fixes the case that
    // happened; deriving the list from the same directory the two above read
    // is what stops the NEXT module shipping in `src/`'s literal and not in
    // the tarball -- three lists that agree until one is edited is the defect
    // `.github/seed-targets.json` exists to prevent one level up.
    const releaseYmlText = fs.readFileSync(path.join(root, ".github", "workflows", "release.yml"), "utf8")
    //
    // All THREE presence gates, not the first one found. release.yml has one per
    // artefact -- the release tarball, the per-platform npm package, and the main npm
    // package -- and the first two ship a native compiler from the same staged
    // directory while the third ships `dist/`. Picking one by a `.find` would test
    // whichever happened to come first in the file and say nothing about the others,
    // which is the shape of the defect rather than a check on it.
    const gateLines = releaseYmlText.split("\n").filter((l) => /^\s*for f in \S+ /.test(l))
    //
    // Every module, a nested one (`std/crypto/sha256.ts`) included: a gate that
    // named only the top level would let a subdirectory drop out of the staging
    // unnoticed, which is the defect this check exists for.
    const listedModules = actual.split(", ")
    const holes = gateLines.flatMap((line) =>
      listedModules.filter((m) => !line.includes(`std/${m}.ts`)).map((m) => `std/${m}.ts in: ${line.trim()}`)
    )
    check(
      `release.yml's ${gateLines.length} presence gates each name every std module, nested ones included, so none can ship missing (${listedModules.join(", ")})`,
      gateLines.length === 3 && holes.length === 0,
      gateLines.length !== 3
        ? `expected 3 \`for f in ...\` gates in release.yml, found ${gateLines.length}`
        : `not named:\n${holes.join("\n")}`
    )
  }

  // S1: the lexer, built by the seed, runs natively, and its token stream agrees
  // with the `typescript` scanner's over the whole corpus. The oracle links a
  // binary, so it needs clang; without one this is skipped like every other
  // toolchain-dependent check.
  const oracle = spawnSync("node", [path.join(root, "tests", "lexer-oracle.js"), "--seed", seedSpec], {
    cwd: root,
    encoding: "utf8",
  })
  const summary = oracle.stdout.trim().split("\n").pop() ?? ""
  check(
    `src/lexer.ts agrees with the typescript scanner (${summary})`,
    oracle.status === 0,
    `${oracle.stdout}${oracle.stderr}`
  )

  // The one thing the oracle cannot judge: the scanner recovers from a
  // lexical error and this lexer stops, so the message and the position it
  // stops at are a golden of their own.
  const dumper = path.join(buildDir, "self", "dump_tokens")
  const built = spawnSync(NISH, [path.join(selfDir, "dump-tokens.ts"), "--link", dumper], {
    cwd: root,
    encoding: "utf8",
  })
  if (check("src/dump-tokens.ts links", built.status === 0, built.stderr)) {
    const errorsTs = path.join(root, "tests", "lexer", "errors.ts")
    const run = spawnSync(dumper, [errorsTs], { cwd: root, encoding: "utf8" })
    const want = fs.readFileSync(path.join(root, "tests", "lexer", "errors.out"), "utf8")
    check(
      "src/lexer.ts stops at a lexical error with its message and position",
      run.stdout === want && run.status === 1,
      `exit ${run.status}\n${run.stdout}`
    )
  }

  // S2: the same shape one level up. Every positive program in the corpus
  // must parse to the tree the `typescript` parser builds, span for span;
  // the files the oracle skips are the forbidden constructs Nish-0 has
  // no grammar for yet, and that count is the S2 gate's own measurement.
  const parserOracle = spawnSync("node", [path.join(root, "tests", "parser-oracle.js"), "--seed", seedSpec], {
    cwd: root,
    encoding: "utf8",
  })
  const parserSummary = parserOracle.stdout.trim().split("\n").pop() ?? ""
  check(
    `src/parser.ts agrees with the typescript parser (${parserSummary})`,
    parserOracle.status === 0,
    `${parserOracle.stdout}${parserOracle.stderr}`
  )

  // And the half of the parser the oracle cannot see: recovery. A failed
  // parse is an `N_ERROR` node and a diagnostic, and the declaration after
  // it still parses (docs/wp14-selfhost.md §3a D1).
  const astDumper = path.join(buildDir, "self", "dump_ast")
  const builtAst = spawnSync(NISH, [path.join(selfDir, "dump-ast.ts"), "--link", astDumper], {
    cwd: root,
    encoding: "utf8",
  })
  if (check("src/dump-ast.ts links", builtAst.status === 0, builtAst.stderr)) {
    // Relative, because the diagnostics quote the path they were given and
    // the golden cannot hold this machine's checkout directory.
    const recovery = spawnSync(astDumper, ["tests/parser/recovery.ts"], { cwd: root, encoding: "utf8" })
    const wantOut = fs.readFileSync(path.join(root, "tests", "parser", "recovery.out"), "utf8")
    const wantErr = fs.readFileSync(path.join(root, "tests", "parser", "recovery.err"), "utf8")
    check(
      "src/parser.ts reports a syntax error and keeps parsing what follows",
      recovery.stdout === wantOut && recovery.stderr === wantErr && recovery.status === 1,
      `exit ${recovery.status}\n${recovery.stdout}${recovery.stderr}`
    )
  }

  // WP33 R1 parses `with (…)`, `try { }` and `var x` for Phase 0 to refuse,
  // and each word is still a name wherever it cannot open the statement:
  // `tests/parser/names.ts` compiled before R1 and has to go on compiling,
  // with `with(n)` a call rather than a refused `with` statement, and
  // `finally()` and `catch(1)` after a `try`-named block calls rather than
  // handlers.
  const namesLl = path.join(buildDir, "parser_names.ll")
  const namesRun = spawnSync(NISH, ["tests/parser/names.ts", "-o", namesLl], { cwd: root, encoding: "utf8" })
  const namesIr = namesRun.status === 0 ? fs.readFileSync(namesLl, "utf8") : ""
  check(
    "src/parser.ts reads `with`, `try` and `var` as names where they cannot open a statement",
    namesRun.status === 0 &&
      namesIr.includes("call i32 @with(i32 %1)") &&
      namesIr.includes("call i32 @finally()") &&
      namesIr.includes("call i32 @catch(i32 1)") &&
      namesIr.includes("%try.addr = alloca i32"),
    `exit ${namesRun.status}\n${namesRun.stdout}${namesRun.stderr}`
  )
  // A literal argument is not a catch binding, so `catch([1, 2])` and
  // `catch({ first: 1, second: 2 })` after a `try`-named block stay calls;
  // each needs a `catch` of its own type, hence a file each.
  for (const literal of ["names-catch-array", "names-catch-object"]) {
    const literalLl = path.join(buildDir, `parser_${literal}.ll`)
    const literalRun = spawnSync(NISH, [`tests/parser/${literal}.ts`, "-o", literalLl], {
      cwd: root,
      encoding: "utf8",
    })
    const literalIr = literalRun.status === 0 ? fs.readFileSync(literalLl, "utf8") : ""
    check(
      `src/parser.ts reads \`catch(<literal>)\` after a \`try\`-named block as a call (tests/parser/${literal}.ts)`,
      literalRun.status === 0 && literalIr.includes("call i32 @catch("),
      `exit ${literalRun.status}\n${literalRun.stdout}${literalRun.stderr}`
    )
  }

  // The operators of the second stage are words too: `typeof`, `delete`,
  // `void`, `await` and `yield` before an operand, `in`, `instanceof`, `as`
  // and `satisfies` after one. `tests/parser/names-operators.ts` uses each, and
  // `of`, as a variable, a parameter and a field in every position a name can
  // stand, and compiled before the operators were read; each local survives as
  // its own slot. `names-operator-calls.ts` calls a function of each name,
  // `typeof(n)` and `void (0)` among them, and every call survives as a call.
  const operatorWords = [
    "typeof",
    "delete",
    "void",
    "instanceof",
    "in",
    "yield",
    "await",
    "satisfies",
    "as",
    "of",
  ]
  const wordsLl = path.join(buildDir, "parser_names_operators.ll")
  const wordsRun = spawnSync(NISH, ["tests/parser/names-operators.ts", "-o", wordsLl], {
    cwd: root,
    encoding: "utf8",
  })
  const wordsIr = wordsRun.status === 0 ? fs.readFileSync(wordsLl, "utf8") : ""
  const missingLocals = operatorWords.filter((word) => !wordsIr.includes(`%${word}.addr = alloca i32`))
  check(
    "src/parser.ts reads the operator words as names where an operator cannot stand (tests/parser/names-operators.ts)",
    wordsRun.status === 0 && missingLocals.length === 0,
    `exit ${wordsRun.status}, no slot for ${missingLocals.join(", ")}\n${wordsRun.stdout}${wordsRun.stderr}`
  )
  const callsLl = path.join(buildDir, "parser_names_operator_calls.ll")
  const callsRun = spawnSync(NISH, ["tests/parser/names-operator-calls.ts", "-o", callsLl], {
    cwd: root,
    encoding: "utf8",
  })
  const callsIr = callsRun.status === 0 ? fs.readFileSync(callsLl, "utf8") : ""
  // How many times each function is called in the source, the one in
  // `through` included, so a call read as an operator is one fewer.
  const wantCalls = {
    typeof: 5,
    delete: 2,
    void: 3,
    instanceof: 3,
    in: 4,
    yield: 2,
    await: 3,
    satisfies: 2,
    as: 3,
    of: 1,
  }
  const wrongCalls = operatorWords.filter(
    (word) => callsIr.split(`call i32 @${word}(`).length - 1 !== wantCalls[word]
  )
  check(
    "src/parser.ts reads a call of a function named like an operator as the call (tests/parser/names-operator-calls.ts)",
    callsRun.status === 0 && wrongCalls.length === 0,
    `exit ${callsRun.status}, wrong call count for ${wrongCalls.join(", ")}\n${callsRun.stdout}${callsRun.stderr}`
  )

  // The third stage's words open declarations: `async` a function, a method
  // or an arrow, `namespace` and `module` a block, `declare` a `global` or a
  // namespace, `keyof` a type operator. `tests/parser/names-declarations.ts`
  // uses each as a variable, a parameter, a field and a method, and `keyof`
  // as a class; `names-declaration-calls.ts` calls a function of each name,
  // `async (n)` and `async` before a parenthesis on the next line among them.
  const declarationWords = ["async", "namespace", "module", "declare", "global", "type"]
  const declsLl = path.join(buildDir, "parser_names_declarations.ll")
  const declsRun = spawnSync(NISH, ["tests/parser/names-declarations.ts", "-o", declsLl], {
    cwd: root,
    encoding: "utf8",
  })
  const declsIr = declsRun.status === 0 ? fs.readFileSync(declsLl, "utf8") : ""
  const missingDeclLocals = declarationWords.filter((word) => !declsIr.includes(`%${word}.addr = alloca i32`))
  check(
    "src/parser.ts reads the declaration words as names where a declaration cannot start (tests/parser/names-declarations.ts)",
    declsRun.status === 0 && missingDeclLocals.length === 0 && declsIr.includes("%struct.keyof = type"),
    `exit ${declsRun.status}, no slot for ${missingDeclLocals.join(", ")}\n${declsRun.stdout}${declsRun.stderr}`
  )
  const declCallsLl = path.join(buildDir, "parser_names_declaration_calls.ll")
  const declCallsRun = spawnSync(NISH, ["tests/parser/names-declaration-calls.ts", "-o", declCallsLl], {
    cwd: root,
    encoding: "utf8",
  })
  const declCallsIr = declCallsRun.status === 0 ? fs.readFileSync(declCallsLl, "utf8") : ""
  // As above, the calls in `through`, in the instance of `apply` and in the
  // template included.
  const wantDeclCalls = { async: 9, namespace: 2, module: 4, declare: 2, global: 2, keyof: 1, type: 2 }
  const wrongDeclCalls = Object.keys(wantDeclCalls).filter(
    (word) => declCallsIr.split(`call i32 @${word}(`).length - 1 !== wantDeclCalls[word]
  )
  check(
    "src/parser.ts reads a call of a function named like a declaration word as the call (tests/parser/names-declaration-calls.ts)",
    declCallsRun.status === 0 && wrongDeclCalls.length === 0,
    `exit ${declCallsRun.status}, wrong call count for ${wrongDeclCalls.join(", ")}\n${declCallsRun.stdout}${declCallsRun.stderr}`
  )

  // The fourth stage's forms open at `get`, `set`, `{`, `[`, `...`, `=` and
  // `,` where a syntax error used to be, and `tests/parser/names-bindings.ts`
  // holds the programs beside each that already compiled: `get` and `set` as
  // class fields, methods and locals and as interface fields, `get` before a
  // method's parameters or a field's type on the next line, a body on the line after its signature, and parenthesised
  // assignments and literals where an arrow's parameters could open.
  const bindingsLl = path.join(buildDir, "parser_names_bindings.ll")
  const bindingsRun = spawnSync(NISH, ["tests/parser/names-bindings.ts", "-o", bindingsLl], {
    cwd: root,
    encoding: "utf8",
  })
  const bindingsIr = bindingsRun.status === 0 ? fs.readFileSync(bindingsLl, "utf8") : ""
  const wantBindings = [
    "%struct.Accessors = type { i32, i32, i32 }",
    "%struct.Pair = type { i32, i32 }",
    "%struct.Wrapped = type { i32, i32 }",
    "@GetSet.get(",
    "@GetSet.set(",
    "@LineBreaks.get(",
    "@body(",
    "@twice(",
  ]
  const missingBindings = wantBindings.filter((want) => !bindingsIr.includes(want))
  check(
    "src/parser.ts keeps the readings beside the function and binding forms (tests/parser/names-bindings.ts)",
    bindingsRun.status === 0 && missingBindings.length === 0,
    `exit ${bindingsRun.status}, missing ${missingBindings.join(", ")}\n${bindingsRun.stdout}${bindingsRun.stderr}`
  )

  // The fifth stage's forms open at `abstract`, `declare`, `static`, the
  // accessibility words, a string or number member name, `[`, `(`, `new`,
  // `extends` and `class` where a syntax error used to be, and
  // `tests/parser/names-classes.ts` holds the programs beside each that already
  // compiled: the words as fields, methods, parameters, locals, functions and
  // object keys, alone on their line before a member's type or parameters,
  // and a body on the line after its signature.
  const classesLl = path.join(buildDir, "parser_names_classes.ll")
  const classesRun = spawnSync(NISH, ["tests/parser/names-classes.ts", "-o", classesLl], {
    cwd: root,
    encoding: "utf8",
  })
  const classesIr = classesRun.status === 0 ? fs.readFileSync(classesLl, "utf8") : ""
  const wantClasses = [
    "%struct.Words = type { i32, i32, i32, i32, i32, i32, i32 }",
    "%struct.Lines = type { i32, i32 }",
    "%struct.Keys = type { i32, i32, i32, i32, i32, i32, i32 }",
    "@Lines.static(",
    "@Lines.declare(",
    "@Params.abstract(",
    "@Params.constructor(",
    "@declare(",
    "@abstract(",
  ]
  const missingClasses = wantClasses.filter((want) => !classesIr.includes(want))
  check(
    "src/parser.ts keeps the readings beside the class, interface and enum forms (tests/parser/names-classes.ts)",
    classesRun.status === 0 && missingClasses.length === 0,
    `exit ${classesRun.status}, missing ${missingClasses.join(", ")}\n${classesRun.stdout}${classesRun.stderr}`
  )

  // Wave C: the support library the checker and the emitter are written
  // over (docs/wp14-selfhost.md §3). It has no counterpart in stage0's `src/` to
  // diff phase by phase, so each function is matched with something that
  // already exists — stage0's IR escape and f64 hex, recorded in a golden
  // while it was in the tree, `node:path` for
  // the module-identity hazard of §3a D3, and `JSON.stringify` / `Map` for
  // the rest.
  const supportOracle = spawnSync(
    "node",
    [path.join(root, "tests", "self", "support-oracle.js"), "--seed", seedSpec],
    {
      cwd: root,
      encoding: "utf8",
    }
  )
  const supportSummary = supportOracle.stdout.trim().split("\n").pop() ?? ""
  check(
    `src/ support library agrees with node and stage0's recorded answers (${supportSummary})`,
    supportOracle.status === 0,
    `${supportOracle.stdout}${supportOracle.stderr}`
  )

  // WP19 G2.4: the four comparisons that held stage1 against stage0 --
  // the type model, the diagnostics, the scope chain and the checker's whole
  // dump -- written down. They were green when they were retired, so stage1's
  // output *is* the agreed behaviour; `tests/self/goldens/` is that output
  // checked in, and `goldens.js` compares stage1's live answer against it.
  //
  // The seed is `seedSpec` above, passed in rather than looked up, so the tool
  // builds with the seed the rest of the run was built with.
  const goldens = spawnSync(
    "node",
    [
      path.join(root, "tests", "self", "goldens.js"),
      ...(process.env.UPDATE_GOLDENS === "1" ? ["--update"] : []),
      "--seed",
      seedSpec,
    ],
    { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
  )
  const goldensSummary = goldens.stdout.trim().split("\n").pop() ?? ""
  check(
    `src/ prints what tests/self/goldens/ records, with no stage0 in it (${goldensSummary})`,
    goldens.status === 0,
    `${goldens.stdout}${goldens.stderr}`
  )

  // The other half of milestone S3: refusing the programs it should, for the
  // reason each case names. A dump comparison cannot see that, so every
  // `reject_*` case and every `tests/link/` negative is run through
  // `src/dump-checked.ts` and its own expected fragments are required of the
  // output -- the assertion section A makes of the driver, made of the checker
  // on its own.
  const rejectOracle = spawnSync(
    "node",
    [path.join(root, "tests", "self", "reject-oracle.js"), "--seed", seedSpec],
    {
      cwd: root,
      encoding: "utf8",
      maxBuffer: 64 * 1024 * 1024,
    }
  )
  const rejectSummary = rejectOracle.stdout.trim().split("\n").pop() ?? ""
  check(
    `src/ refuses every negative case with the message it pins (${rejectSummary})`,
    rejectOracle.status === 0,
    `${rejectOracle.stdout}${rejectOracle.stderr}`
  )

  // WP19 G2.1: the successor to the IR and interop oracles, which held stage1
  // against stage0 and retired with it (`docs/wp19-stage0-retirement.md` §2B).
  // `nish-cmp` compares the **last released** `nish` with HEAD over the same
  // corpus, byte for byte — Go's `toolstash -cmp` — and a difference has to
  // be named in `CHANGELOG.md` before it goes green.
  //
  // It needs a released `nish` to compare with, so without `NISH_BOOTSTRAP`
  // it skips rather than runs, and the skip is counted and says why: a
  // comparison against nothing that reported PASS would be exactly the
  // green-run-proving-less problem the summary at the bottom of this file
  // exists to expose. Set `NISH_BOOTSTRAP` to the seed -- the variable
  // `scripts/bootstrap.sh` reads -- and it runs. Budget about three minutes
  // for it when it does: it is the whole corpus twice.
  // The gate's own comparison logic, driven here because the gate itself
  // skips on any machine with no seed -- which is most of them, and is the
  // shape `.claude/selfhost.md` warns about: a guard nothing exercises. It is
  // the one piece of that tool that can make two DIFFERING files look equal,
  // so it is the piece worth a stand-in (`reject-oracle.js`'s `selfCheck` and
  // `scripts/verify-binaries.sh` are the precedent).
  //
  // Why the tool needs it at all: two compilers are never installed in one
  // directory, and a module reached as `nish/<name>` is named by the path the
  // compiler found it at, so the seed writes its own unpacked path where HEAD
  // writes `std/text.ts`. Measured against the v0.5.0 seed, that is four
  // undeclared differences over two programs and nothing else -- a red gate
  // for a property no cross-install comparison can have.
  check(
    "nish-cmp: its own package-root normalisation is right (stand-in inputs, not the corpus)",
    selfCheckRoots() === null,
    String(selfCheckRoots())
  )
  check(
    "nish-cmp: a compiler's own root is derived the way the compiler derives it",
    packageRootOf(NISH) === root && packageRootOf(path.join(root, "build", "self", "compile")) === root,
    `build/nish-test -> ${packageRootOf(NISH)}, ` +
      `build/self/compile -> ${packageRootOf(path.join(root, "build", "self", "compile"))}, root is ${root}`
  )
  check(
    "nish-cmp: removing a root leaves the module path, and a sibling directory alone",
    withoutOwnRoot("; ModuleID = '/opt/nish/std/text.ts'", "/opt/nish") === "; ModuleID = 'std/text.ts'" &&
      withoutOwnRoot("/opt/nish-old/std/a.ts", "/opt/nish") === "/opt/nish-old/std/a.ts",
    `${withoutOwnRoot("; ModuleID = '/opt/nish/std/text.ts'", "/opt/nish")} | ` +
      `${withoutOwnRoot("/opt/nish-old/std/a.ts", "/opt/nish")}`
  )
  // The other thing two releases cannot agree about: a `-g` build records
  // `producer: "nish <version>"`, and the reference is the last release while
  // HEAD carries the next number from the commit that bumps it. Measured
  // against the v0.6.0 seed on the 0.7.0 bump, that is seven undeclared
  // differences, one line each, all in `dbg_*` cases -- the same digits
  // `normaliseProducer` lets go for the goldens.
  check(
    "nish-cmp: its own producer-version normalisation is right (stand-in inputs, not the corpus)",
    selfCheckVersions() === null,
    String(selfCheckVersions())
  )
  // And the lookup that decides whether a declared difference is excused: its
  // words may be in CHANGELOG.md or in the section scripts/changelog-gen.mjs
  // would render for the commits not yet released, and a pending section that
  // could not be read excuses nothing.
  check(
    "nish-cmp: a declaration's words are found in CHANGELOG.md or the pending release notes, and nowhere else (stand-in inputs)",
    selfCheckNotes() === null,
    String(selfCheckNotes())
  )

  // The fuzz run's declarations, by the same argument: an intended change to
  // the IR is accepted only where an entry names the function and both
  // attribute groups, and an entry nothing uses fails, but the run that
  // applies them needs a seed. #438 is what an undeclared one costs: #427's
  // CG-8 moved `nish_str_concat`'s group, and every seeded `npm test` went red.
  for (const [label, failure] of fuzzDeclarations()) {
    check(`fuzz --stage1: ${label} (fabricated modules)`, failure === null, String(failure))
  }

  // The same equality on programs nobody wrote. The corpus is checked in and
  // therefore finite and adapted-to; the WP13 fuzzer generates random
  // straight-line programs, and here the released `nish` and HEAD are each
  // asked for the IR of every one and the texts compared byte for byte,
  // module set included (`fuzz.js --stage1`, docs/wp13-differential.md "The
  // fuzzer"). Sixteen programs from one fixed seed, which is a time budget
  // rather than a coverage judgement -- about a third of a second each, plus
  // one link. A failure reproduces from the summary line.
  // Both need the released compiler, so both wait for the same variable and
  // share one counted skip without it.
  if (!process.env.NISH_BOOTSTRAP) {
    skip(
      "NISH_BOOTSTRAP is unset: there is no released nish to compare HEAD against, so " +
        "tests/nish-cmp.js (WP19 G2) and tests/differential/fuzz.js --stage1 did not run"
    )
  } else {
    // `cmpSince` in .github/seed-targets.json names the first release this gate
    // may be asked about, and CI's `seeds` job gives nish-cmp no row for an
    // older one; the same rule here, read from the same field, so a run seeded
    // with such a release reports a counted skip rather than a red it was
    // told in advance to expect. The note beside the field says why.
    const cmpSince = JSON.parse(
      fs.readFileSync(path.join(root, ".github", "seed-targets.json"), "utf8")
    ).cmpSince
    const released = resolveSeed(process.env.NISH_BOOTSTRAP)
    const seedVersion =
      released.error === undefined
        ? /^nish (\S+)$/m.exec(spawnSeed(released, ["--version"]).stdout ?? "")?.[1]
        : undefined
    if (seedVersion !== undefined && !notAfter(cmpSince, seedVersion)) {
      skip(
        `NISH_BOOTSTRAP is nish ${seedVersion}, older than cmpSince ${cmpSince} in .github/seed-targets.json, ` +
          "so tests/nish-cmp.js (WP19 G2) and tests/differential/fuzz.js --stage1 did not run"
      )
    } else {
      const nishCmp = spawnSync("node", [path.join(root, "tests", "nish-cmp.js")], {
        cwd: root,
        encoding: "utf8",
        maxBuffer: 64 * 1024 * 1024,
      })
      const nishCmpSummary = nishCmp.stdout.trim().split("\n").pop() ?? ""
      check(
        `the released nish and HEAD write the same bytes (${nishCmpSummary})`,
        nishCmp.status === 0,
        `${nishCmp.stdout}${nishCmp.stderr}`
      )

      const stage1FuzzSeed = 20261001
      const stage1Fuzz = spawnSync(
        "node",
        [
          path.join(root, "tests", "differential", "fuzz.js"),
          "--stage1",
          "--seed",
          String(stage1FuzzSeed),
          "--count",
          "16",
        ],
        { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
      )
      const stage1FuzzSummary =
        stage1Fuzz.stdout
          .trim()
          .split("\n")
          .filter((l) => l.startsWith("fuzz: stage1 seed="))
          .pop() ?? ""
      check(
        `the released nish and HEAD emit the same IR for random programs (${stage1FuzzSummary || `seed=${stage1FuzzSeed}`})`,
        stage1Fuzz.status === 0,
        `${stage1Fuzz.stdout}${stage1Fuzz.stderr}`
      )
    }
  }

  // S5, and the claim the work package exists for: `src/` compiles `src/`.
  // stage1 is `src/` built by the seed, stage2 is `src/` built by stage1,
  // stage3 is `src/` built by stage2. `IR(stage1) == IR(stage2)` is the
  // fixed point -- nothing about the seed leaks into the result any more --
  // and stage3 must be byte-identical to stage2 so the binaries are compared
  // as well as the text. Three links, so it is the slowest check here.
  //
  // It is also a check CI was running twice. ci.yml's
  // `bootstrap` job has a row per seed the last release attaches, and its
  // x86_64-linux row runs `scripts/bootstrap.sh --verify` on the runner the
  // `test` job uses, with the seed the `test` job fetches -- `seeds` reads the
  // newest release and scripts/fetch-seed.sh the latest one, which are the
  // same tag unless a prerelease heads the list, and .github/seed-matrix.sh
  // turns red on a newest tag that is not a plain version.
  // `--verify` asserts these two equalities, byte for byte, with the speed
  // profile this check uses (the profile changes the link, not the IR). About
  // eighty seconds of the `test` job, the critical path, bought nothing the
  // run did not already have in parallel.
  //
  // So the `test` job passes `--delegate-fixed-point`, and when the request is
  // honest the check is delegated to that row rather than run here: counted as
  // delegated, not as passed, and not as a skip -- a skip says "unproven", and
  // this is proved, by a job the summary names. What makes the request honest:
  //
  //   * It is a GitHub Actions run. The flag is a claim about the workflow this
  //     run is part of; from a terminal it names a job that is not running, and
  //     the check runs here as it always has. A local `npm test` pays for the
  //     fixed point, and is the only place outside CI that proves it.
  //   * This host has a seed row, which is to say a `bootstrap` row: the job is
  //     named from .github/seed-targets.json by this host's triple, the way the
  //     `seeds` job names it. A host with no seed target has no row to hand the
  //     check to, and it runs here.
  //   * That row exists whenever this job can go green. x86_64-linux has been
  //     due since 0.1.1, so a release that does not carry its seed turns
  //     `seeds` red (.github/seed-matrix.sh); and with no release at all
  //     scripts/fetch-seed.sh has nothing to fetch and this job is red before
  //     it gets here. release.yml runs this whole workflow through
  //     `workflow_call` and its `release` job is `needs: ci`, so a red row
  //     stops a release as a red check here would.
  //   * The workflow still says so. The check after this one reads ci.yml and
  //     fails if the `test` job asks for the delegation while the `bootstrap`
  //     job has stopped running `scripts/bootstrap.sh --verify`, and the one
  //     after that holds `--verify` to asserting both equalities.
  //
  // Nothing reads what this check builds: tests/self/bootstrap.js deletes its
  // stages on the way out, and the checks below build their own. And the
  // equalities are not absent from the `test` job even so -- the perturbed-seed
  // check below runs `--verify` over three debug-profile stages and requires
  // both to hold.
  const fixedPointName = "src/ compiles src/: the bootstrap reaches a fixed point"
  const hostSeedTarget = JSON.parse(
    fs.readFileSync(path.join(root, ".github", "seed-targets.json"), "utf8")
  ).targets.find((t) => t.triple === HOST_TRIPLE)
  if (
    process.argv.includes("--delegate-fixed-point") &&
    process.env.GITHUB_ACTIONS === "true" &&
    hostSeedTarget !== undefined
  ) {
    delegate(
      fixedPointName,
      `ci.yml's \`bootstrap (${hostSeedTarget.asset})\` job, which runs scripts/bootstrap.sh --verify with the same seed`
    )
  } else {
    const bootstrap = spawnSync(
      "node",
      [path.join(root, "tests", "self", "bootstrap.js"), "--seed", seedSpec],
      {
        cwd: root,
        encoding: "utf8",
        maxBuffer: 64 * 1024 * 1024,
      }
    )
    const bootstrapSummary = bootstrap.stdout.trim().split("\n").pop() ?? ""
    check(
      `${fixedPointName} (${bootstrapSummary})`,
      bootstrap.status === 0,
      `${bootstrap.stdout}${bootstrap.stderr}`
    )
  }

  // The delegation above is a claim about ci.yml, so ci.yml is read for it on
  // every run, local ones included: a `test` job that still asks for it while
  // the `bootstrap` job no longer runs `--verify` would be a green run with
  // the fixed point proved nowhere. Comment lines are left out, because a
  // comment that mentions a flag is not a step that passes it.
  const ciJob = (text, name) => {
    const lines = text.split("\n")
    const start = lines.indexOf(`  ${name}:`)
    if (start < 0) {
      return ""
    }
    const end = lines.findIndex((l, i) => i > start && /^ {2}\S/.test(l))
    return lines
      .slice(start, end < 0 ? lines.length : end)
      .filter((l) => !l.trimStart().startsWith("#"))
      .join("\n")
  }
  const ciYmlText = fs.readFileSync(path.join(root, ".github", "workflows", "ci.yml"), "utf8")
  const testJobText = ciJob(ciYmlText, "test")
  const bootstrapJobText = ciJob(ciYmlText, "bootstrap")
  check(
    "ci.yml: the `test` job delegates the fixed point only while the `bootstrap` job runs scripts/bootstrap.sh --verify",
    testJobText !== "" &&
      (!testJobText.includes("--delegate-fixed-point") ||
        (/^\s+needs: seeds$/m.test(bootstrapJobText) &&
          bootstrapJobText.includes("scripts/bootstrap.sh --verify"))),
    `test job:\n${testJobText}\n\nbootstrap job:\n${bootstrapJobText}`
  )

  // A sharded job runs `--shard "$SHARD/<n>"` over a `shard:` list,
  // and the two numbers are written apart. A list shorter than `n` is a green
  // run in which the missing shard's programs ran nowhere; a longer one is a
  // shard the suite refuses. So the list's length is held to `n`, for the
  // suite's own job, the Nish runner's and the macOS `net_` job's.
  for (const job of ["test", "runner", "runtime-net"]) {
    const text = ciJob(ciYmlText, job)
    const list = /^\s+shard: \[([\d, ]+)\]$/m.exec(text)
    const flag = /^\s+SHARD: \$\{\{ matrix\.shard \}\}$/m.test(text)
      ? /--shard "\$SHARD\/(\d+)"/.exec(text)
      : null
    const shards = list ? list[1].split(",").map((n) => Number(n.trim())) : []
    check(
      `ci.yml: the \`${job}\` job's shard list is 1..n for the n its --shard names`,
      flag !== null && shards.length === Number(flag[1]) && shards.every((n, i) => n === i + 1),
      `shard list: ${list ? list[1] : "(none)"}, --shard .../${flag ? flag[1] : "(none)"}`
    )
  }

  // `--delegate-ir-checks` (DELEGATE_IR_CHECKS) hands a link program's compile
  // checks to the `test` job, which is honest only while that job runs every
  // program: its suite line names no filter, and no job but `runtime-net`
  // asks for the delegation.
  {
    const suiteLine = /npm test -- (.*?) \|/.exec(ciJob(ciYmlText, "test"))?.[1] ?? ""
    const words = suiteLine.split(/\s+/).filter(Boolean)
    const filters = words.filter((w, i) => !w.startsWith("--") && !["--seed", "--shard"].includes(words[i - 1]))
    const uncommented = ciYmlText
      .split("\n")
      .filter((l) => !l.trimStart().startsWith("#"))
      .join("\n")
    const asks = (text) => text.split("--delegate-ir-checks").length - 1
    check(
      "ci.yml: --delegate-ir-checks is asked for by `runtime-net` alone, and the `test` job runs every tests/link program",
      suiteLine !== "" && filters.length === 0 && asks(uncommented) === asks(ciJob(ciYmlText, "runtime-net")),
      `test job's suite line: ${suiteLine || "(not found)"}; filters: ${filters.join(", ") || "none"}`
    )
  }

  // WP19 G3: which equalities `scripts/bootstrap.sh --verify` asserts, and
  // this check is what stops that from drifting.
  //
  // `IR(seed) == IR(stage1)` asks whether codegen has changed since the seed
  // was released, which forbids every improvement a release cycle exists to
  // carry and says nothing about the bootstrap, so it is reported and not
  // asserted. (While stage0 was a seed the same comparison was diverse
  // double-compiling, and was asserted; that went with stage0's `src/`.)
  // `IR(stage1) == IR(stage2)` and `stage3 == stage2` are properties of the
  // working tree alone and are asserted for every seed.
  //
  // The run uses the debug profile, where three stages cost about eight
  // seconds rather than the speed profile's minutes; what is under test is
  // the decision, not the code the linker produced.
  const seedWork = (name) => path.join(buildDir, "seed-equality", name)
  const runBootstrap = (name, env) =>
    spawnSync(
      "bash",
      [
        path.join(root, "scripts", "bootstrap.sh"),
        "--verify",
        "--profile",
        "debug",
        "--work",
        seedWork(name),
        "-o",
        path.join(seedWork(name), "nish"),
      ],
      { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024, env: { ...process.env, ...env } }
    )

  // A seed guaranteed to differ: the seed this run was built with, wrapped so
  // that it emits `--unchecked-indexing`, which removes the bounds checks
  // from the IR it writes for `src/` -- the
  // same shape of difference a codegen improvement makes, and the shape that
  // broke this run when the first one landed. A released seed differs from
  // HEAD already, but by however much codegen moved since that release, which
  // may be nothing; the wrapper is what makes the difference certain. It still
  // builds a working stage1, so the fixed point is untouched and stays
  // asserted.
  //
  // The difference has to actually be there: a run where nothing differs
  // would pass this check while proving nothing, so the count is read out of
  // the note and required to be non-zero.
  const perturbedSeed = seedWork("seed-unchecked.mjs")
  fs.mkdirSync(path.dirname(perturbedSeed), { recursive: true })
  fs.writeFileSync(
    perturbedSeed,
    "// Generated by tests/run.js: the seed, emitting IR without bounds checks.\n" +
      `import { spawnSync } from "node:child_process";\n` +
      "const args = process.argv.slice(2);\n" +
      `const asking = args.includes("--version") || args.includes("--help");\n` +
      `const r = spawnSync(${JSON.stringify(seed.cmd)}, [...${JSON.stringify(seed.prefix)}, ...args,` +
      ` ...(asking ? [] : ["--unchecked-indexing"])], { stdio: "inherit" });\n` +
      "process.exit(r.status === null ? 70 : r.status);\n"
  )
  const released = runBootstrap("released", { NISH_BOOTSTRAP: perturbedSeed })
  const note = /note: IR\(seed\) vs IR\(stage1\): (\d+) of (\d+) modules differ/.exec(released.stdout)
  check(
    `a seed that emits different IR has the difference reported and not asserted (${
      note ? `${note[1]} of ${note[2]} modules` : "no note printed"
    })`,
    released.status === 0 &&
      note !== null &&
      Number(note[1]) > 0 &&
      released.stdout.includes("Not a bootstrap failure") &&
      /IR\(stage1\) == IR\(stage2\): \d+ modules identical/.test(released.stdout) &&
      released.stdout.includes("stage3 == stage2: byte-identical binaries"),
    `${released.status}:\n${released.stdout}${released.stderr}`
  )

  // The deployment path (docs/wp14-selfhost.md §7). The check above proves
  // the fixed point and then deletes every compiler it built; this one
  // proves the artifact: `scripts/bootstrap.sh` builds a compiler you can
  // keep, and that compiler is the whole command line — the output planning,
  // the directory creation and the link step included, which is D4 reversed
  // (§7a). Everything below runs the binary itself, with no wrapper in the
  // way. One stage rather than three, because what is under test here is the
  // recipe and the driver, not the equalities.
  const shipDir = path.join(buildDir, "selfhost")
  fs.rmSync(shipDir, { recursive: true, force: true })
  const compiler = path.join(shipDir, "nish")
  const shipped = spawnSync(
    "bash",
    [
      path.join(root, "scripts", "bootstrap.sh"),
      "--stages",
      "1",
      "--profile",
      "debug",
      "--work",
      shipDir,
      "-o",
      compiler,
      "--quiet",
    ],
    {
      cwd: root,
      encoding: "utf8",
      maxBuffer: 64 * 1024 * 1024,
      env: { ...process.env, NISH_BOOTSTRAP: seedSpec },
    }
  )
  if (
    check(
      "scripts/bootstrap.sh builds the self-hosted compiler from source",
      shipped.status === 0 && fs.existsSync(compiler),
      `${shipped.stdout}${shipped.stderr}`
    )
  ) {
    // One module: the IR lands next to the binary as `<exe>.ll`, which is
    // where stage0's `--link` puts it too.
    const hello = path.join(shipDir, "hello")
    const one = spawnSync(compiler, ["examples/hello.ts", "--link", hello, "--profile", "debug"], {
      cwd: root,
      encoding: "utf8",
    })
    const ranHello = one.status === 0 ? spawnSync(hello, [], { encoding: "utf8" }) : null
    check(
      "the self-hosted compiler: the self-hosted compiler links and runs examples/hello.ts",
      one.status === 0 &&
        fs.existsSync(`${hello}.ll`) &&
        ranHello !== null &&
        ranHello.status === 0 &&
        ranHello.stdout === "hello from Nish\n",
      `${one.stdout}${one.stderr}${ranHello ? `ran: ${ranHello.status} ${JSON.stringify(ranHello.stdout)}` : ""}`
    )

    // Two modules: the compiler makes the `<exe>.modules/` directory itself
    // now, and `main()` returns the exit code.
    const multi = path.join(shipDir, "multi")
    const many = spawnSync(compiler, ["examples/multi/main.ts", "--link", multi, "--profile", "debug"], {
      cwd: root,
      encoding: "utf8",
    })
    const ranMulti = many.status === 0 ? spawnSync(multi, [], { encoding: "utf8" }) : null
    const emitted = fs.existsSync(`${multi}.modules`)
      ? fs
          .readdirSync(`${multi}.modules`)
          .filter((f) => f.endsWith(".ll"))
          .sort()
      : []
    check(
      "the self-hosted compiler: a program with imports links from <exe>.modules/ and exits 49",
      many.status === 0 &&
        emitted.join(",") === "main.ll,math.ll" &&
        ranMulti !== null &&
        ranMulti.status === 49,
      `${many.stdout}${many.stderr}modules: ${emitted.join(",")}${ranMulti ? ` exit ${ranMulti.status}` : ""}`
    )

    // `-g` reaches both halves: the compiler puts the DWARF in the `.ll` and
    // hands `-g` to
    // scripts/build.sh, so the DWARF in the .ll survives the link instead of
    // being stripped with the profile. A `.debug_info` section in the linked
    // binary is the end-to-end proof; the metadata in the IR is what the
    // oracle compares byte for byte.
    const dbgExe = path.join(shipDir, "hello-g")
    const withG = spawnSync(compiler, ["examples/hello.ts", "--link", dbgExe, "--profile", "debug", "-g"], {
      cwd: root,
      encoding: "utf8",
    })
    const dbgIr = fs.existsSync(`${dbgExe}.ll`) ? fs.readFileSync(`${dbgExe}.ll`, "utf8") : ""
    const dwarf =
      withG.status === 0 && HAS_LLVM_DWARFDUMP
        ? spawnSync("llvm-dwarfdump", ["--debug-info", dbgExe], {
            encoding: "utf8",
            maxBuffer: 64 * 1024 * 1024,
          })
        : null
    // Without llvm-dwarfdump, read the section table clang already wrote.
    const hasDwarf = dwarf
      ? dwarf.status === 0 && dwarf.stdout.includes("DW_TAG_compile_unit")
      : withG.status === 0 && fs.readFileSync(dbgExe).includes("debug_info")
    check(
      "the self-hosted compiler: -g reaches the compiler and the linked program carries DWARF",
      withG.status === 0 &&
        dbgIr.includes("!llvm.dbg.cu") &&
        dbgIr.includes('distinct !DISubprogram(name: "main"') &&
        hasDwarf,
      `${withG.status}: ${withG.stdout}${withG.stderr}${dwarf ? dwarf.stdout.slice(0, 400) : ""}`
    )

    // stage1 answers `--version` itself: `src/branding.ts` carries the
    // version as a constant because stage1 cannot read `package.json`, so
    // this is what catches the two drifting apart at the next release bump.
    const ourVersion = spawnSync(compiler, ["--version"], { cwd: root, encoding: "utf8" })
    check(
      "the self-hosted compiler: --version names the release package.json does",
      ourVersion.status === 0 &&
        ourVersion.stdout ===
          `nish ${JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8")).version}\n`,
      JSON.stringify(ourVersion.stdout)
    )

    // `--json` is the editor-facing diagnostic shape: the objects, their
    // order and their spans. A multi-error program is the case worth
    // pinning, because it is also the one that proves stage1 collected every
    // error rather than stopping at the first.
    //
    // The `.err` sidecars cannot see a whole span on their own -- they are
    // matched as substrings, so the caret run they pin fixes a start column
    // but not an end one, and the two compilers once printed the same
    // sentence for `reject_ffi_pointer_array` while spanning it on `CPtr[]`
    // and on `CPtr` respectively (WP27 S2). A case joins this list when its
    // span is the property under test, and the spans are written out here,
    // `line:column-endLine:endColumn` per object, because they were agreed
    // between the two compilers before stage0 retired and nothing else pins
    // them now.
    const jsonCases = [
      ["reject_multi_error", ["2:10-2:18 NL2231", "6:19-6:20 NL2185", "11:10-11:16 NL2231"]],
      ["reject_ffi_pointer_array", ["21:18-21:22 NL2323"]],
      ["reject_ffi_pointer_type_argument_fn", ["22:13-22:18 NL2323"]],
      // WP33 R1: Phase 0 ends a module at its first refusal, and the pass 1
      // `for...of` sweep recovers per declaration; a `.err` cannot count.
      ["reject_stmt_forms_together", ["8:3-9:4 NL1056"]],
      ["reject_for_of_heads_together", ["4:3-6:4 NL2133", "12:8-12:9 NL2135"]],
      // The expression forms: Phase 0's end the module the same way, and the
      // checker's pass 1 sweep reports once per declaration, ahead of the
      // declaration's own collection.
      ["reject_expr_forms_together", ["6:50-6:56 NL1047"]],
      ["reject_expr_sweep_together", ["6:18-6:26 NL2210", "8:40-8:51 NL2254", "10:35-10:41 NL2237"]],
      // The declaration forms, the same two ways.
      ["reject_decl_forms_together", ["6:1-8:2 NL1015"]],
      ["reject_decl_sweep_together", ["12:18-12:19 NL2292", "17:8-17:15 NL2038", "20:23-20:24 NL2292"]],
      ["reject_type_keyof_constraint", ["14:32-14:41 NL2038", "16:28-16:37 NL2038", "21:20-21:29 NL2038"]],
      // A type parameter list that repeats a name: one diagnostic, on the
      // first repeat, however many there are.
      ["reject_generic_duplicate_type_parameter_triple", ["5:19-5:20 NL2302"]],
      // The function and binding forms, all the checker's: one per
      // declaration, the first in source order.
      [
        "reject_fn_sweep_together",
        [
          "16:22-16:38 NL2235",
          "18:14-18:19 NL2096",
          "20:14-20:20 NL2254",
          "22:23-22:33 NL2233",
          "24:10-24:19 NL2096",
          "26:24-26:30 NL2254",
          "28:1-28:33 NL2084",
        ],
      ],
      // The class, interface and enum forms: one per declaration, the first
      // in source order, and a member header the collector refuses first.
      [
        "reject_cls_sweep_together",
        [
          "4:3-4:22 NL2027",
          "7:3-7:19 NL2116",
          "10:3-10:12 NL2090",
          "14:15-14:28 NL2234",
          "16:1-18:2 NL2168",
          "20:3-20:28 NL2116",
          "23:3-23:19 NL2213",
          "26:17-26:31 NL2215",
          "29:19-29:40 NL2258",
          "30:1-30:24 NL2286",
          "31:1-33:2 NL2018",
        ],
      ],
    ]
    for (const [jsonName, spans] of jsonCases) {
      const jsonCase = path.join("tests", "cases", `${jsonName}.ts`)
      const ourJson = spawnSync(compiler, [jsonCase, "--json"], { cwd: root, encoding: "utf8" })
      let got = []
      try {
        got = ourJson.stdout
          .split("\n")
          .filter(Boolean)
          .map((line) => JSON.parse(line))
          .map((o) => `${o.line}:${o.column}-${o.endLine}:${o.endColumn} ${o.code}`)
      } catch {
        got = ["(stdout is not one JSON object per line)"]
      }
      check(
        `the self-hosted compiler: ${jsonName}'s --json diagnostics carry the spans they are pinned to`,
        ourJson.status === 1 && ourJson.stderr === "" && got.join(", ") === spans.join(", "),
        `wanted ${spans.join(", ")}\ngot ${got.join(", ")}\n${ourJson.stdout}${ourJson.stderr}`
      )
    }

    // WP21 S2: the walk up to `node_modules` has to reach the directories
    // Node reaches, and the working directory is what makes that hard.
    // `tests/link/package_above` installs the package *above* the directory
    // the compiler is run in -- `proj/node_modules` beside `proj/src/main.ts`,
    // which is what npm produces -- and is compiled the way that program is
    // compiled, `nish main.ts` from stage0's `src/`. stage1 has no `process.cwd()`
    // (WP19 §A3) and climbs past `.` by spelling `..`, so a stage1 that
    // stopped where `dirname` stops answered `` Cannot find package
    // `pkg_above` `` for a program that resolves. The two modules are the
    // entry and the package it found.
    const aboveSrc = path.join(root, "tests", "link", "package_above", "src")
    if (fs.existsSync(path.join(aboveSrc, "main.ts"))) {
      const ourDir = path.join(shipDir, "package_above-stage1") + path.sep
      fs.rmSync(ourDir, { recursive: true, force: true })
      const ourAbove = spawnSync(compiler, ["main.ts", "-o", ourDir], {
        cwd: aboveSrc,
        encoding: "utf8",
      })
      const ourModules = llFilesIn(ourDir)
      check(
        "the self-hosted compiler: a package above the working directory resolves",
        ourAbove.status === 0 && ourModules.join(",") === "index.ll,main.ll",
        `stage1 ${ourAbove.status}: ${ourAbove.stdout}${ourAbove.stderr}modules [${ourModules.join(" ")}]`
      )
    }

    // WP21 S2, the other half of that walk: an ancestor the module's own name
    // does not spell. `tests/link/package_doubled` installs the package one
    // `node_modules` inside another and is compiled from inside
    // `node_modules/app`, so the ancestor is `..` -- a directory named without
    // being named. Node steps over a `node_modules` ancestor and so does the
    // compiler wherever the name spells one, but `..` spells nothing, and the
    // compiler has no way to learn what it is: stage1 has no `process.cwd()`
    // (WP19 §A3) and the language has no `statSync`, which is what naming a
    // directory from below would take. So it searches it, and finds the
    // package, which is the answer stage0 gave too while there was one.
    const doubledSrc = path.join(root, "tests", "link", "package_doubled", "node_modules", "app")
    if (fs.existsSync(path.join(doubledSrc, "main.ts"))) {
      const ourDir = path.join(shipDir, "package_doubled-stage1") + path.sep
      fs.rmSync(ourDir, { recursive: true, force: true })
      const ourDoubled = spawnSync(compiler, ["main.ts", "-o", ourDir], {
        cwd: doubledSrc,
        encoding: "utf8",
      })
      const ourDoubledModules = llFilesIn(ourDir)
      check(
        "the self-hosted compiler: a `node_modules` ancestor no name spells is searched",
        ourDoubled.status === 0 && ourDoubledModules.join(",") === "index.ll,main.ll",
        `stage1 ${ourDoubled.status}: ${ourDoubled.stdout}${ourDoubled.stderr}` +
          `modules [${ourDoubledModules.join(" ")}]`
      )

      // The same tree named from its root, where the compiler *can* read the
      // ancestor's name and steps over it: the package is not found, and the
      // refusal says where it looked.
      const doubledRoot = path.join(root, "tests", "link", "package_doubled")
      const doubledEntry = path.join("node_modules", "app", "main.ts")
      const ourNamed = spawnSync(compiler, [doubledEntry, "-o", ourDir], {
        cwd: doubledRoot,
        encoding: "utf8",
      })
      check(
        "the self-hosted compiler: a `node_modules` ancestor the name spells is stepped over",
        ourNamed.status === 1 &&
          ourNamed.stderr.includes(
            "error: Cannot find package `@nish-absent/zed`; no `node_modules` directory above the importing module has it"
          ),
        `stage1 ${ourNamed.status}: ${ourNamed.stderr}`
      )
    }

    // WP21 S3 and #198: a package is its real directory. `package_symlink` is
    // pnpm's layout, one package reached a second time through a link, which
    // is one package: `@shared.val` is defined once. `package_workspace` is a
    // workspace link to a directory outside any `node_modules`, whose own
    // relative import stays in that package rather than joining the root
    // package: `foo`'s `helper` is `@foo.helper` beside the program's
    // `@helper`, where it used to clash with it. Both are compiled the way a
    // user compiles them, `nish main.ts` from the fixture; the link loop above
    // runs them.
    for (const [workspaceName, wantDefines] of [
      ["package_symlink", ["@app2.twice(", "@shared.val("]],
      ["package_workspace", ["@foo.foo(", "@foo.helper(", "@helper("]],
    ]) {
      const ourDir = path.join(shipDir, `${workspaceName}-stage1`) + path.sep
      fs.rmSync(ourDir, { recursive: true, force: true })
      const ourBuild = spawnSync(compiler, ["main.ts", "-o", ourDir], {
        cwd: path.join(root, "tests", "link", workspaceName),
        encoding: "utf8",
      })
      const defines = llFilesIn(ourDir)
        .flatMap((file) => fs.readFileSync(path.join(ourDir, file), "utf8").split("\n"))
        .filter(
          (line) => line.startsWith("define ") && !line.includes("@main(") && !line.includes("@nish_main(")
        )
        .map((line) => /@[\w.$]+\(/.exec(line)?.[0] ?? line)
        .sort()
      check(
        `the self-hosted compiler: ${workspaceName} is one package per real directory (${wantDefines.join(" ")})`,
        ourBuild.status === 0 && defines.join(" ") === wantDefines.join(" "),
        `stage1 ${ourBuild.status}: ${ourBuild.stdout}${ourBuild.stderr}defines [${defines.join(" ")}]`
      )
    }

    // WP15 §8 through the driver (WP19 G1). The analysis is pinned by the
    // performance section and the checked goldens already; what this pins is
    // the half that is the driver's -- that it prints the warnings at all,
    // on stderr, as JSON objects on stdout under `--json`, and not at all
    // under `--no-warn-performance`. A warning changes no exit code, so the
    // compile that carries it is a successful one. `wrote <file>` is dropped:
    // it names a path in a temporary directory.
    const perfCase = path.join("tests", "cases", "perf_str_concat_loop.ts")
    const perfOut = (dir) => path.join(shipDir, dir, "perf.ll")
    const withoutWrote = (text) =>
      text
        .split("\n")
        .filter((line) => !line.startsWith("wrote "))
        .join("\n")
    const ourPerf = spawnSync(compiler, [perfCase, "-o", perfOut("perf1")], { cwd: root, encoding: "utf8" })
    const ourPerfJson = spawnSync(compiler, [perfCase, "-o", perfOut("perf1j"), "--json"], {
      cwd: root,
      encoding: "utf8",
    })
    const ourPerfOff = spawnSync(compiler, [perfCase, "-o", perfOut("perf1q"), "--no-warn-performance"], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      "the self-hosted compiler: the performance warnings are printed, and --no-warn-performance silences them",
      ourPerf.status === 0 &&
        ourPerf.stderr.includes("performance: `out` is rebuilt") &&
        withoutWrote(ourPerf.stderr).trimEnd().endsWith("4 performance warnings") &&
        ourPerfJson.status === 0 &&
        ourPerfJson.stdout.split("\n").filter(Boolean).length === 4 &&
        ourPerfJson.stdout
          .split("\n")
          .filter(Boolean)
          .every((line) => JSON.parse(line).severity === "performance") &&
        ourPerfOff.status === 0 &&
        withoutWrote(ourPerfOff.stderr).trim() === "",
      `ours:\n${ourPerf.stderr}\nours --json:\n${ourPerfJson.stdout}\nours --no-warn-performance:\n${ourPerfOff.stderr}`
    )

    // `--emit-checked` through the driver, rather than through the
    // `dump_checked` entry `tests/self/goldens.js` spawns: the same text has
    // to come out of both, which is why one `src/dump.ts` writes it for
    // both, and the entry's is the one the goldens hold. A whole program is
    // dumped module by module, the entry named as one.
    const dumpCase = path.join("examples", "multi", "main.ts")
    const ourDump = spawnSync(compiler, [dumpCase, "--emit-checked"], { cwd: root, encoding: "utf8" })
    const dumpEntry = path.join(shipDir, "dump_checked")
    const dumpBuilt = spawnSync(
      compiler,
      ["src/dump-checked.ts", "--link", dumpEntry, "--profile", "debug"],
      {
        cwd: root,
        encoding: "utf8",
      }
    )
    const viaEntry =
      dumpBuilt.status === 0
        ? spawnSync(dumpEntry, [dumpCase], { cwd: root, encoding: "utf8" })
        : {
            status: dumpBuilt.status,
            stdout: "",
            stderr: `could not link src/dump-checked.ts:\n${dumpBuilt.stderr}`,
          }
    check(
      "the self-hosted compiler: --emit-checked dumps a whole program as the dump entry does",
      ourDump.status === 0 &&
        viaEntry.status === 0 &&
        ourDump.stdout === viaEntry.stdout &&
        ourDump.stdout.includes("module examples/multi/main.ts (entry)") &&
        ourDump.stdout.includes("module examples/multi/math.ts"),
      `driver:\n${ourDump.stdout}${ourDump.stderr}\ndump entry ${viaEntry.status}:\n${viaEntry.stdout}${viaEntry.stderr}`
    )

    // No flag is stage0's by name any more (`--emit-ast` was the last, WP19
    // R1), so what this pins is the property the refusal was really about: a
    // flag the compiler does not know is refused rather than quietly
    // dropped, because a build that asked for something must not come out
    // without it and without being told. It answers exit 2, which is the
    // usage-error code the CLI contract fixes.
    const refused = spawnSync(compiler, ["examples/hello.ts", "--emit-sidecar"], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      "the self-hosted compiler: an unknown flag is refused, not ignored",
      refused.status === 2 && refused.stderr.includes("--emit-sidecar"),
      `stage1 ${refused.status}: ${refused.stdout}${refused.stderr}`
    )

    // The `--help` contract: a request that succeeded goes to stdout with
    // exit 0, a refusal to stderr with exit 2. It is the shape that is pinned
    // here; the WP12 block pins the text.
    const ourHelp = spawnSync(compiler, ["--help"], { cwd: root, encoding: "utf8" })
    const ourRefusal = spawnSync(compiler, [], { cwd: root, encoding: "utf8" })
    check(
      "the self-hosted compiler: --help answers on stdout with exit 0, and a usage error on stderr with exit 2",
      ourHelp.status === 0 &&
        ourHelp.stdout.includes("usage:") &&
        ourHelp.stderr === "" &&
        ourRefusal.status === 2 &&
        ourRefusal.stderr.includes("usage:") &&
        ourRefusal.stdout === "",
      `help ${ourHelp.status}:\n${ourHelp.stdout}${ourHelp.stderr}\nrefusal ${ourRefusal.status}:\n${ourRefusal.stdout}${ourRefusal.stderr}`
    )

    // The interop sidecars, and the directory each one needs. The bytes
    // themselves are the WP8 section's business.
    const sidecarDir = path.join(shipDir, "interop")
    const sidecarFiles = ["add.h", "add.d.ts", "add.mjs", "add.napi.c"]
    const sidecars = spawnSync(
      compiler,
      [
        "examples/add.ts",
        "-o",
        path.join(shipDir, "add.ll"),
        "--emit-header",
        path.join(sidecarDir, "add.h"),
        "--emit-dts",
        path.join(sidecarDir, "add.d.ts"),
        "--emit-napi",
        path.join(sidecarDir, "add.napi.c"),
      ],
      { cwd: root, encoding: "utf8" }
    )
    const wrote = sidecarFiles.filter((f) => fs.existsSync(path.join(sidecarDir, f)))
    const selfHeader = wrote.includes("add.h") ? fs.readFileSync(path.join(sidecarDir, "add.h"), "utf8") : ""
    check(
      "the self-hosted compiler: the interop sidecars are passed through and their directory made",
      sidecars.status === 0 &&
        wrote.length === sidecarFiles.length &&
        selfHeader.includes("int32_t add(int32_t a, int32_t b);"),
      `${sidecars.status}: ${sidecars.stdout}${sidecars.stderr}wrote: ${wrote.join(",")}`
    )

    // ---- The command line answers the way stage0's did, not merely close
    // to it. Each of these was a silent divergence while there were two
    // compilers to compare: a flag stage1 accepted and ignored, an input it
    // dropped, a stream it wrote the wrong way down.

    // An unknown `--number-mode` refused rather than quietly meaning i32:
    // the failure mode is a program that compiles, in the other arithmetic.
    const badMode = spawnSync(
      compiler,
      ["examples/hello.ts", "--number-mode", "f32", "-o", path.join(shipDir, "unused.ll")],
      { cwd: root, encoding: "utf8" }
    )
    check(
      "the self-hosted compiler: an unknown --number-mode is refused",
      badMode.status === 2 && !fs.existsSync(path.join(shipDir, "unused.ll")),
      `stage1 ${badMode.status}: ${badMode.stderr}`
    )

    // Every positional is a root, as it is for stage0. Before this the last
    // one won and the others were compiled into nothing.
    const rootsDir = path.join(shipDir, "roots")
    const roots = spawnSync(compiler, ["examples/hello.ts", "examples/add.ts", "-o", `${rootsDir}/`], {
      cwd: root,
      encoding: "utf8",
    })
    const rootsWrote = fs.existsSync(rootsDir) ? fs.readdirSync(rootsDir).sort() : []
    check(
      "the self-hosted compiler: every file named on the command line is a root",
      roots.status === 0 && rootsWrote.join(",") === "add.ll,hello.ll",
      `${roots.status}: ${roots.stdout}${roots.stderr}wrote: ${rootsWrote.join(",")}`
    )

    // stdout carries the IR and the `--json` diagnostics and nothing else,
    // so `wrote <file>` goes to stderr. A build script that pipes the IR
    // somewhere must not find chatter mixed into it.
    const chatterDir = path.join(shipDir, "chatter")
    const chatter = spawnSync(compiler, ["examples/hello.ts", "-o", `${chatterDir}/`], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      "the self-hosted compiler: `wrote <file>` goes to stderr",
      chatter.status === 0 && chatter.stdout === "" && chatter.stderr.includes("wrote "),
      `stage1 out=${JSON.stringify(chatter.stdout)} err=${JSON.stringify(chatter.stderr)}`
    )

    // A root that cannot be opened is a driver failure, not a diagnostic
    // with a span: stage0 answers exit 1 with `error: ...` on stderr, and
    // one flat object on stdout under `--json`. The errno itself stays
    // stage0's — Node names it and the runtime's read does not.
    const missing = spawnSync(
      compiler,
      [path.join(shipDir, "no_such_file.ts"), "-o", path.join(shipDir, "nope.ll")],
      { cwd: root, encoding: "utf8" }
    )
    const missingJson = spawnSync(
      compiler,
      [path.join(shipDir, "no_such_file.ts"), "--json", "-o", path.join(shipDir, "nope.ll")],
      { cwd: root, encoding: "utf8" }
    )
    let missingObject = null
    try {
      missingObject = JSON.parse(missingJson.stdout.trim())
    } catch {
      // Not JSON: missingObject stays null and the check below fails on it.
    }
    check(
      "the self-hosted compiler: an unreadable root exits 1 and --json makes it an object",
      missing.status === 1 &&
        missing.stderr.startsWith("error: cannot open ") &&
        missingJson.status === 1 &&
        missingObject !== null &&
        missingObject.severity === "error" &&
        missingObject.message.startsWith("cannot open "),
      `${missing.status}: ${missing.stderr}json ${missingJson.status}: ${missingJson.stdout}`
    )

    // `--link` on a program with no entry point: stage0 refuses it before it
    // emits anything, with exit 1 and a message naming what to declare.
    // Reaching clang instead costs a link and answers `undefined reference
    // to main` with exit 3.
    const noMain = spawnSync(
      compiler,
      ["tests/link/no_main/main.ts", "--link", path.join(shipDir, "no_main"), "--profile", "debug"],
      { cwd: root, encoding: "utf8" }
    )
    check(
      "the self-hosted compiler: --link without `export const main` is refused before anything is linked",
      noMain.status === 1 && noMain.stderr.includes("export const main"),
      `stage1 ${noMain.status}: ${noMain.stderr}`
    )

    // An unknown profile refused before the compile rather than after it, as
    // stage0 validates `PROFILES` before it reads a file.
    const badProfile = spawnSync(
      compiler,
      ["examples/hello.ts", "--link", path.join(shipDir, "bad"), "--profile", "turbo"],
      { cwd: root, encoding: "utf8" }
    )
    check(
      "the self-hosted compiler: an unknown --profile is refused before anything is compiled",
      badProfile.status === 2 && badProfile.stderr.includes("unknown profile"),
      `${badProfile.status}: ${badProfile.stdout}${badProfile.stderr}`
    )

    // `-o <dir>/` writes into the directory it was given; it does not empty
    // it first: `-o build/` must not take the rest of `build/` with it.
    const keepDir = path.join(shipDir, "keep")
    fs.mkdirSync(keepDir, { recursive: true })
    fs.writeFileSync(path.join(keepDir, "keep.txt"), "not the compiler's\n")
    const keep = spawnSync(compiler, ["examples/hello.ts", "-o", `${keepDir}/`], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      "the self-hosted compiler: -o <dir>/ writes into the directory, it does not clear it",
      keep.status === 0 &&
        fs.existsSync(path.join(keepDir, "keep.txt")) &&
        fs.existsSync(path.join(keepDir, "hello.ll")),
      `${keep.status}: ${keep.stdout}${keep.stderr}`
    )

    // ---- The three things §7a listed as still stage0's, closed. -----------

    // `-o <dir>` for a directory that is already there, without the trailing
    // slash: stage0 stats the path, and so does this now (`isDirectorySync`,
    // WP14 §7a). The slash still names a directory that does not exist yet,
    // so both spellings are checked, and a name that is *not* a directory
    // must still be taken as a file.
    const statDir = path.join(shipDir, "stat")
    fs.mkdirSync(statDir, { recursive: true })
    const intoDir = spawnSync(compiler, ["examples/hello.ts", "-o", statDir], {
      cwd: root,
      encoding: "utf8",
    })
    const asFile = path.join(shipDir, "stat_file.ll")
    const intoFile = spawnSync(compiler, ["examples/hello.ts", "-o", asFile], {
      cwd: root,
      encoding: "utf8",
    })
    check(
      "the self-hosted compiler: -o <existing dir> without the slash is the directory, as stage0 stats it",
      intoDir.status === 0 &&
        fs.existsSync(path.join(statDir, "hello.ll")) &&
        intoFile.status === 0 &&
        fs.existsSync(asFile),
      `dir ${intoDir.status}: ${intoDir.stderr}file ${intoFile.status}: ${intoFile.stderr}`
    )

    // `--target host`: the machine answers, through `process.platform` and
    // `process.arch`, and `src/target.ts` composes the triple from them. The
    // module it writes has to be the one naming that triple outright writes --
    // the whole module rather than the triple line, which keeps the check
    // honest about the layout string too. A host with no triple of its own is
    // refused with the list, and the WP9 block pins which one that is.
    const hostTripleHere = HOST_TRIPLE
    const ourHost = path.join(shipDir, "host.ll")
    const namedHost = path.join(shipDir, "host_named.ll")
    const hostOurs = spawnSync(compiler, ["examples/hello.ts", "--target", "host", "-o", ourHost], {
      cwd: root,
      encoding: "utf8",
    })
    const hostNamed = hostTripleHere
      ? spawnSync(compiler, ["examples/hello.ts", "--target", hostTripleHere, "-o", namedHost], {
          cwd: root,
          encoding: "utf8",
        })
      : null
    check(
      hostNamed !== null
        ? `the self-hosted compiler: --target host writes the module --target ${hostTripleHere} writes`
        : "the self-hosted compiler: --target host is refused on a host with no triple, naming the supported ones",
      hostNamed !== null
        ? hostOurs.status === 0 &&
            hostNamed.status === 0 &&
            stripHeader(fs.readFileSync(ourHost, "utf8")) === stripHeader(fs.readFileSync(namedHost, "utf8"))
        : hostOurs.status === 2 && hostOurs.stderr.includes("supported: host,"),
      `host ${hostOurs.status}: ${hostOurs.stderr}` +
        (hostNamed !== null ? `named ${hostNamed.status}: ${hostNamed.stderr}` : "")
    )

    // `--emit-ast`, the last flag that was stage0's by name (WP19 R1, §2A).
    // What it prints is deliberately *not* stage0's output: stage0 dumps the
    // `typescript` package's node names and 1-based line:column spans, and
    // this dumps the flattened vocabulary of `src/nodes.ts` with byte
    // offsets, because that is the tree this compiler actually has. So there
    // is no oracle between the two — there is a golden per compiler, over
    // the same input file, and this is stage1's. The check is that the flag
    // is answered (exit 0, no IR written) and that the tree is the one
    // `tests/self/dump-ast.golden` records.
    const astOut = path.join(shipDir, "ast")
    fs.mkdirSync(astOut, { recursive: true })
    const astRun = spawnSync(compiler, ["tests/cases/dump_ast.ts", "--emit-ast", "-o", `${astOut}/`], {
      cwd: root,
      encoding: "utf8",
    })
    const astGoldenFile = path.join(root, "tests", "self", "dump-ast.golden")
    const astGolden = fs.existsSync(astGoldenFile) ? fs.readFileSync(astGoldenFile, "utf8") : ""
    if (process.env.UPDATE_GOLDENS === "1" && astRun.status === 0 && astRun.stdout !== astGolden) {
      fs.writeFileSync(astGoldenFile, astRun.stdout)
    }
    check(
      "the self-hosted compiler: --emit-ast prints its own tree and writes no IR",
      astRun.status === 0 &&
        astRun.stdout === fs.readFileSync(astGoldenFile, "utf8") &&
        fs.readdirSync(astOut).length === 0,
      `${astRun.status}: ${astRun.stderr}--- stdout\n${astRun.stdout}`
    )

    // A broken invariant answers 70 (`EX_SOFTWARE`) and stage0's report,
    // less the two halves a self-hosted compiler honestly has not got: the
    // input files, which live in a `process.argv` that only a program with
    // an entry `main` may read, and the stack, which needs the `try`/`catch`
    // the language does not have. `tests/self/ice.ts` calls the report
    // directly, because an invariant nothing reaches cannot be provoked from
    // a command line, and stage1 builds it, so what prints this is stage1's
    // code compiled by stage1.
    const iceVersion = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8")).version
    const iceExe = path.join(shipDir, "ice")
    const iceBuild = spawnSync(compiler, ["tests/self/ice.ts", "--link", iceExe, "--profile", "debug"], {
      cwd: root,
      encoding: "utf8",
    })
    const ice = iceBuild.status === 0 ? spawnSync(iceExe, [], { cwd: root, encoding: "utf8" }) : null
    check(
      "the self-hosted compiler: an internal error exits 70 and says what it cannot show",
      ice !== null &&
        ice.status === 70 &&
        ice.stderr.startsWith(`nish ${iceVersion}: internal compiler error\n`) &&
        ice.stderr.includes("  emitter: no callee recorded for `f`\n") &&
        ice.stderr.includes("NISH_DEBUG=1 adds nothing") &&
        ice.stderr.includes("This is a bug in nish, not in your program."),
      `${iceBuild.status}: ${iceBuild.stderr}${ice ? `ran ${ice.status}: ${ice.stderr}` : ""}`
    )
  }
}

// The end of a sharded run's split: shard 1 names the link programs it dealt
// away, and every other shard names everything after this point and stops.
if (linkDealtAway.length > 0) {
  const byShard = new Map()
  for (const name of linkDealtAway) {
    byShard.set(linkShard(name), (byShard.get(linkShard(name)) ?? 0) + 1)
  }
  for (const [i, count] of [...byShard].sort((a, b) => a[0] - b[0])) {
    delegate(`${count} tests/link program(s)`, shardJob(i))
  }
}
if (irDelegated > 0) {
  delegate(
    `the compile's checks of ${irDelegated} tests/link program(s) (--delegate-ir-checks)`,
    "ci.yml's `test` job, which runs every tests/link program on Linux"
  )
}
// ---- crypto-bench: the crypto twins ------------------------------------------------
// bench/crypto/run.mjs --validate builds every family under bench/crypto/ (a
// directory with a family.json) in Nish, OpenSSL, Go, Rust and Node, requires
// every program to print the checksums its expected.txt pins, and proves the
// portable columns portable. Each family must report every kernel size matched,
// found by listing the directories, so a new family is checked without an edit
// here. A missing toolchain is the runner's note and a column of —, not a
// failure; so is a family that needs a loopback socket the machine refuses, and
// a portable column this host cannot prove. Those notes and unproved lines are
// printed under the check on a pass too, so a green run says what it left out.
//
// It is dealt like the link programs (`DEALT_SECTIONS`) rather than left to
// shard 1: it builds every twin of five families, four and a half minutes of
// a CI shard, and reads nothing another section writes.
if (DEALT_SECTIONS.cryptoBench.selected && SHARD === sectionShard("cryptoBench")) {
  if (HAS_CLANG) {
    const families = fs
      .readdirSync(path.join(root, "bench", "crypto"))
      .filter((d) => fs.existsSync(path.join(root, "bench", "crypto", d, "family.json")))
      .sort()
    const proved = families.filter(
      (f) =>
        JSON.parse(fs.readFileSync(path.join(root, "bench", "crypto", f, "family.json"), "utf8"))
          .portableProof !== undefined
    )
    const v = spawnSync(
      "node",
      [path.join(root, "bench", "crypto", "run.mjs"), "--compiler", path.relative(root, NISH), "--validate"],
      { cwd: root, encoding: "utf8" }
    )
    // The runner accounts for every column of every family it validated: a
    // `<family>: ran …` line, and for each other column `<family> has no <id>:`
    // (the family's own word) or `<family> did not run <id>:` (this machine's
    // reason). The test takes that account rather than probing toolchains
    // itself, which disagreed with the runner on a host whose Go was older
    // than go.mod or whose cargo could not fetch. The column list is the
    // runner's own `crypto: columns …` line; without it the check fails.
    const COLUMNS = (/^crypto: columns (.+)$/m.exec(v.stdout)?.[1] ?? "").split(", ").filter((id) => id !== "")
    const validated = families.filter((f) => !new RegExp(`^${f}: skipped `, "m").test(v.stdout))
    const unaccounted = validated.flatMap((f) => {
      const ran = (new RegExp(`^${f}: ran (.*)$`, "m").exec(v.stdout)?.[1] ?? "").split(", ")
      return COLUMNS.filter(
        (id) => !ran.includes(id) && !new RegExp(`^${f} (?:has no|did not run) ${id}: `, "m").test(v.stdout)
      ).map((id) => `${f} ${id}`)
    })
    // GitHub's x86-64 Linux runner has every twin's toolchain and the
    // extensions their portable builds give up, so there a column this machine
    // did not run, or an `unproved` line, means a gate failed open: every twin
    // must run and the OpenSSL and Go proofs must be measured ones.
    const strict =
      process.env.GITHUB_ACTIONS === "true" && process.platform === "linux" && os.arch() === "x64"
    const provedLine = (f, id) => new RegExp(`^portable ${f} ${id}: \\d+\\.\\d{3}x the time of `, "m")
    check(
      `crypto-bench: every family (${families.join(", ")}) prints its expected.txt checksums from every twin, and its portable columns are portable`,
      v.status === 0 &&
        families.length > 0 &&
        COLUMNS.length > 0 &&
        families.every((f) =>
          new RegExp(
            `^${f}: (?:(\\d+) of \\1 kernel size\\(s\\) match expected\\.txt|skipped \\(needs loopback\\))$`,
            "m"
          ).test(v.stdout)
        ) &&
        unaccounted.length === 0 &&
        proved.every((f) =>
          ["openssl-portable", "go-purego", "rust-soft"].every((id) =>
            new RegExp(`^portable ${f} ${id}: `, "m").test(v.stdout)
          )
        ) &&
        (!strict ||
          (validated.length === families.length &&
            !/ did not run /.test(v.stdout) &&
            proved.every((f) =>
              ["openssl-portable", "go-purego"].every((id) => provedLine(f, id).test(v.stdout))
            ))),
      `columns: ${COLUMNS.join(", ") || "none printed"}; unaccounted for: ${unaccounted.join(", ") || "none"}${strict ? "; strict: every twin must run and the OpenSSL and Go proofs must be measured" : ""}\n${v.stdout}${v.stderr}`
    )
    for (const line of `${v.stdout}${v.stderr}`.split("\n")) {
      if (line.startsWith("note: ") || / unproved \(/.test(line) || / did not run /.test(line)) {
        console.log(`      ${line}`)
      }
    }
    // --validate fails, not only passes: a copy of the curves family, read
    // through --families, passes as committed and fails once one line of its
    // expected.txt is altered. Nish and OpenSSL alone, at x25519's one size.
    const copies = path.join(buildDir, "crypto-bench", "families")
    const copyCurves = (name, edit) => {
      const dir = path.join(copies, name)
      fs.rmSync(dir, { recursive: true, force: true })
      // main.ts imports ../lib/gen, so the shared library comes along.
      for (const d of ["curves", "lib"]) {
        fs.cpSync(path.join(root, "bench", "crypto", d), path.join(dir, d), { recursive: true })
      }
      edit(path.join(dir, "curves"))
      return dir
    }
    const validateCopy = (dir, only) =>
      spawnSync(
        "node",
        [
          path.join(root, "bench", "crypto", "run.mjs"),
          "--compiler",
          path.relative(root, NISH),
          "--families",
          dir,
          "--only",
          only,
          "--no-go",
          "--no-rust",
          "--no-node",
          "--validate",
        ],
        { cwd: root, encoding: "utf8" }
      )
    const clean = validateCopy(
      copyCurves("clean", () => {}),
      "x25519"
    )
    const altered = validateCopy(
      copyCurves("altered", (dir) => {
        const file = path.join(dir, "expected.txt")
        const text = fs.readFileSync(file, "utf8")
        // The checksum's last hex digit, moved by one: still a well-formed line.
        const next = text.replace(/^(x25519 32 \d+ [0-9a-f]{7})([0-9a-f])$/m, (_, head, d) =>
          `${head}${((parseInt(d, 16) + 1) % 16).toString(16)}`
        )
        fs.writeFileSync(file, next === text ? `${text}# no x25519 32 line to alter\n` : next)
      }),
      "x25519"
    )
    check(
      "crypto-bench: --validate exits 1 with a CHECKSUM MISMATCH line when one expected.txt line is altered, and 0 on the unaltered copy",
      clean.status === 0 &&
        /^curves: 1 of 1 kernel size\(s\) match expected\.txt$/m.test(clean.stdout) &&
        altered.status === 1 &&
        /^CHECKSUM MISMATCH x25519 32 nish: printed [0-9a-f]{8}, expected\.txt has [0-9a-f]{8}$/m.test(
          altered.stdout
        ) &&
        /^crypto: \d+ mismatch\(es\); nothing is timed$/m.test(altered.stdout),
      `unaltered: exit ${clean.status}\n${clean.stdout}${clean.stderr}\naltered: exit ${altered.status}\n${altered.stdout}${altered.stderr}`
    )
    // The paired-rounds proof (portableRounds) on two more copies, each with a
    // ratio floor no mask reaches so the rounds alone decide: the real mask
    // must pass; a mask that clears only AVX, which X25519 does not use, must
    // fail (its ratio alone would pass it on a noisy run, as 1.098x once did).
    // That mask names its second word as `~0x0`: OpenSSL reads a missing second
    // word as zero, which would clear BMI2 and ADX too. Each needs a CPU with
    // the flags its mask clears; GitHub's runner has them. The verdict line
    // names whichever proof case decided, the last one when all fall short.
    const withFamily = (edit) => (dir) => {
      const file = path.join(dir, "family.json")
      const spec = JSON.parse(fs.readFileSync(file, "utf8"))
      edit(spec)
      fs.writeFileSync(file, `${JSON.stringify(spec, null, 2)}\n`)
    }
    const pairedLine = (verdict) =>
      new RegExp(
        `^${verdict} curves openssl-portable: \\d+\\.\\d{3}x the time of openssl at [\\w-]+@\\d+, slower in \\d+ of \\d+ paired rounds `,
        "m"
      )
    const paired = [
      {
        name: "crypto-bench: portableRounds proves the curves family's OpenSSL mask by its paired rounds when the ratio falls short",
        dir: "paired-real",
        edit: (spec) => {
          spec.portableMinRatio.openssl = 100
        },
        status: 0,
        line: pairedLine("portable"),
      },
      {
        name: "crypto-bench: portableRounds fails an OpenSSL mask that clears nothing X25519 uses (AVX only)",
        dir: "paired-avx",
        edit: (spec) => {
          spec.portableMinRatio.openssl = 100
          spec.twins.openssl.portable.env.OPENSSL_ia32cap = "~0x1000000000000000:~0x0"
          spec.portableProofFlags = ["avx"]
        },
        status: 1,
        line: pairedLine("NOT PORTABLE"),
      },
    ]
    for (const c of paired) {
      const r = validateCopy(copyCurves(c.dir, withFamily(c.edit)), "curves")
      const unproved = /^portable curves openssl-portable: unproved \((.*)\)$/m.exec(r.stdout)
      if (unproved !== null && !strict) {
        skip(`${c.name} (${unproved[1]})`)
        continue
      }
      check(c.name, r.status === c.status && c.line.test(r.stdout), `exit ${r.status}\n${r.stdout}${r.stderr}`)
    }
    fs.rmSync(copies, { recursive: true, force: true })
    // `bench/run.mjs --only crypto` hands the run to bench/crypto/run.mjs: the
    // compiler it was given reaches the child, and the child's status comes
    // back. A wrapper answers --version from the compiler under test and fails
    // the first build with 3, which bench/crypto/run.mjs reports as its exit 1.
    // That build is whichever family sorts first, so the log may name any
    // family's main.ts.
    const wrapDir = path.join(buildDir, "crypto-bench")
    const wrapper = path.join(wrapDir, "nish-wrapper")
    const wrapLog = path.join(wrapDir, "wrapper.log")
    fs.mkdirSync(wrapDir, { recursive: true })
    fs.rmSync(wrapLog, { force: true })
    fs.writeFileSync(
      wrapper,
      `#!/bin/sh\nif [ "$1" = --version ]; then exec '${path.resolve(NISH)}' --version; fi\necho "$@" >> '${wrapLog}'\nexit 3\n`,
      { mode: 0o755 }
    )
    const deleg = spawnSync(
      "node",
      [path.join(root, "bench", "run.mjs"), "--compiler", wrapper, "--only", "crypto", "--validate"],
      { cwd: root, encoding: "utf8" }
    )
    const forwarded = fs.existsSync(wrapLog) ? fs.readFileSync(wrapLog, "utf8") : ""
    check(
      "crypto-bench: bench/run.mjs --only crypto forwards --compiler to bench/crypto/run.mjs and exits with its status",
      deleg.status === 1 && /bench[\\/]crypto[\\/][a-z0-9-]+[\\/]main\.ts/.test(forwarded),
      `exit ${deleg.status}\n${deleg.stdout}${deleg.stderr}\nwrapper log: ${forwarded}`
    )
    // bench/run.mjs rewrites docs/BENCHMARKS.md whole, and must carry over the
    // section bench/crypto/run.mjs --record writes there: fib(20), Nish and C
    // only, one run, into a copy of the file.
    const out = path.join(buildDir, "crypto-bench", "benchmarks.md")
    const section = "<!-- crypto:begin -->\n## kept\n<!-- crypto:end -->"
    fs.mkdirSync(path.dirname(out), { recursive: true })
    fs.writeFileSync(out, `# Benchmarks\n\nstale table\n\n${section}\n`)
    const r = spawnSync(
      "node",
      [
        path.join(root, "bench", "run.mjs"),
        "--compiler",
        path.relative(root, NISH),
        "--only",
        "fib",
        "--n",
        "fib=20",
        "--runs",
        "1",
        "--warmup",
        "0",
        "--no-rust",
        "--no-go",
        "--out",
        out,
      ],
      { cwd: root, encoding: "utf8" }
    )
    const text = r.status === 0 ? fs.readFileSync(out, "utf8") : ""
    check(
      "crypto-bench: bench/run.mjs rewriting docs/BENCHMARKS.md keeps the section bench/crypto/run.mjs --record wrote, once",
      text.includes(section) &&
        text.split("<!-- crypto:begin -->").length === 2 &&
        !text.includes("stale table"),
      r.status === 0 ? text.slice(-400) : `${r.stdout}${r.stderr}`
    )
  } else {
    skip("crypto-bench: bench/crypto/run.mjs --validate (no clang)")
  }
}

for (const [key, section] of Object.entries(DEALT_SECTIONS)) {
  if (section.selected && SHARD !== sectionShard(key)) {
    delegate(section.name, shardJob(sectionShard(key)))
  }
}
if (SHARD > 1) {
  delegate("every section after the tests/link programs but the WP14 self-hosting and crypto-bench ones", shardJob(1))
  summarise()
}
// A name in `LINK_READ_LATER` that is no longer a program would pin nothing,
// and the checks that read its output skip a file that is not there.
if (!only) {
  const gone = LINK_READ_LATER.filter((name) => !linkTests.includes(name))
  check(
    "every program LINK_READ_LATER keeps in shard 1 is a tests/link program",
    gone.length === 0,
    `not in tests/link: ${gone.join(", ")}`
  )
}

// X509-6: `nish/crypto/x509-random` draws from `crypto.getRandomValues`, so
// `tests/link/crypto_x509_random_wasm` (a wasm32 build importing it) is refused
// by the link loop above. This is the other half: `nish/crypto/x509` alone
// still compiles for wasm32, which an import of the drawing module from
// `x509.ts` would end.
if (!only || "crypto_x509_random_wasm".includes(only)) {
  const entry = path.join(linkDir, "crypto_x509_random_wasm", "x509-only.ts")
  const outDir = path.join(buildDir, "x509-only-wasm") + path.sep
  fs.rmSync(outDir, { recursive: true, force: true })
  const r = fs.existsSync(entry)
    ? spawnSync(NISH, [entry, "--target", "wasm32", "-o", outDir], { cwd: root, encoding: "utf8" })
    : null
  check(
    "crypto_x509_random_wasm: a wasm32 build importing nish/crypto/x509 alone compiles",
    r !== null && r.status === 0,
    r === null ? "no such fixture: tests/link/crypto_x509_random_wasm/x509-only.ts" : r.stderr
  )
}

// #628: P-256's fixed-base comb (`p256BaseMult`, which `p256PublicKey` and
// `p256Sign` use) against its variable-base window (`p256ScalarMult` on G, which
// `p256Verify` uses), byte for byte, on Wycheproof's scalars, RFC 6979 A.2.5's,
// the edges and a seeded corpus of 10,000. Neither multiply is exported, so the
// program reaches them through a test-only seam: this copies std/crypto/p256.ts
// with `tests/link/crypto_p256_agree/seam.ts.in` appended beside the program,
// as `./p256`, and the two fixture directories it imports beside that. The
// program's header says what it runs; its expected.out ends in a checksum of
// every comb output. Natively, and as a `--profile wasi` module under Node.
// The wasi run segfaults in Node 22 unless V8's fast API calls are off, which
// examples/wasi-host.mjs now does itself: a collection inside WASI's
// `fd_write` fast call crashes its frame walk. On Node 22.22.0, 16 of 20 runs
// crashed with no flag, 1 of 50 with the `--single-threaded-gc` this check
// used to pass, and none of 50 with the host turning the calls off.
// #732 tracks the Node bug and when the host can drop the flag.
/**
 * Builds `tests/link/<program>`'s `main` (from `source`) beside a copy of
 * std/crypto/p256.ts with the program's `seam.ts.in` appended, as `./p256`,
 * natively and as a `--profile wasi` module under Node, and checks that each
 * prints its expected.out: `label` names the checks, `dir` the scratch, and
 * `extra` the directories of `tests/link` copied beside it.
 */
const p256SeamProgram = ({ label, dir, program, source, extra, nativeName }) => {
  const seamDir = path.join(buildDir, dir)
  const programDir = path.join(seamDir, program)
  fs.rmSync(seamDir, { recursive: true, force: true })
  fs.mkdirSync(path.join(seamDir, "crypto_p256"), { recursive: true })
  fs.mkdirSync(programDir, { recursive: true })
  for (const name of extra) {
    fs.cpSync(path.join(linkDir, name), path.join(seamDir, name), { recursive: true })
  }
  fs.copyFileSync(path.join(linkDir, "crypto_p256", "hex.ts"), path.join(seamDir, "crypto_p256", "hex.ts"))
  fs.copyFileSync(path.join(linkDir, program, source), path.join(programDir, "main.ts"))
  fs.writeFileSync(
    path.join(programDir, "p256.ts"),
    fs.readFileSync(path.join(root, "std", "crypto", "p256.ts"), "utf8") +
      fs.readFileSync(path.join(linkDir, program, "seam.ts.in"), "utf8")
  )
  const want = fs.readFileSync(path.join(linkDir, program, "expected.out"), "utf8")
  const entry = path.join(programDir, "main.ts")
  if (only !== "wasi") {
    const exe = path.join(seamDir, "app")
    const built = spawnSync(NISH, [entry, "-o", path.join(seamDir, "native") + path.sep, "--link", exe], {
      cwd: root,
      encoding: "utf8",
    })
    const ran = built.status === 0 ? spawnSync(exe, [], { encoding: "utf8" }) : built
    check(nativeName, built.status === 0 && ran.status === 0 && ran.stdout === want, shown(ran))
  }
  if (WASI_SYSROOT && has("wasm-ld")) {
    const wasm = path.join(seamDir, "app.wasm")
    const built = spawnSync(
      NISH,
      [entry, "-o", path.join(seamDir, "wasi") + path.sep, "--link", wasm, "--profile", "wasi"],
      { cwd: root, encoding: "utf8" }
    )
    const ran =
      built.status === 0
        ? spawnSync("node", ["--no-warnings", "examples/wasi-host.mjs", wasm], {
            cwd: root,
            encoding: "utf8",
          })
        : built
    check(
      `${label}: the \`--profile wasi\` build (sysroot ${WASI_SYSROOT}) prints the same expected.out under Node's WASI`,
      built.status === 0 && ran.status === 0 && ran.stdout === want,
      shown(ran)
    )
  } else {
    skip(
      `skipped: ${label}: no WASI sysroot${has("wasm-ld") ? "" : " and no wasm-ld"} (set WASI_SYSROOT): the wasi build of ${program} is not run`
    )
  }
}
if (!only || ["p256 agree", "crypto_p256_agree", "wasi"].some((name) => name.includes(only))) {
  p256SeamProgram({
    label: "p256 agree",
    dir: "p256-agree",
    program: "crypto_p256_agree",
    source: "agree.ts",
    extra: ["crypto_wycheproof"],
    nativeName:
      "p256 agree: the fixed-base comb and the variable-base window give the same bytes for every scalar of tests/link/crypto_p256_agree, natively",
  })
}

// #758: the nonce's inverse by safegcd (`p256ScalarInverse`, which `p256Sign`
// and `p256SignSha256Into` use) against Fermat's (`p256ScalarInvert`, which
// `p256Verify` keeps), byte for byte, on the edges and a seeded corpus of
// 10,000 scalars. Neither inversion is exported, so the program reaches them
// through `tests/link/crypto_p256_inverse/seam.ts.in`, appended to a copy of
// std/crypto/p256.ts beside it as `./p256`, as the "p256 agree" check does, through `p256SeamProgram`.
// Its expected.out ends in a checksum of every inverse. Natively, and as a
// `--profile wasi` module under Node.
if (!only || ["p256 inverse", "crypto_p256_inverse", "wasi"].some((name) => name.includes(only))) {
  p256SeamProgram({
    label: "p256 inverse",
    dir: "p256-inverse",
    program: "crypto_p256_inverse",
    source: "inverse.ts",
    extra: [],
    nativeName:
      "p256 inverse: safegcd and Fermat give the same inverse for every scalar of tests/link/crypto_p256_inverse, natively",
  })
}

// The comb table in std/crypto/p256.ts is what scripts/gen-p256-table.mjs
// computes from SEC 2's G, limb for limb: a hand edit to one entry would put a
// wrong point in every key and signature that reads it, and only the scalars
// whose digits name that entry would show it.
if (!only || "p256 gen-p256-table".includes(only)) {
  const r = spawnSync("node", ["scripts/gen-p256-table.mjs", "--check"], { cwd: root, encoding: "utf8" })
  check(
    "p256: the comb table in std/crypto/p256.ts is what scripts/gen-p256-table.mjs generates",
    r.status === 0 && r.stdout === "gen-p256-table: 3840 limbs, as generated\n",
    shown(r)
  )
}

// WP29 P1: `dst` shorter than `src` panics before any element is written, with
// `std/threads.ts`'s own message. The link loop above compares stdout and the
// exit code only, so the wording is pinned here, on stderr, the way
// `arr_bounds_panic` pins `index out of range`.
// The binary's existence is part of the assertion rather than a guard around it,
// so a renamed or deleted fixture fails here instead of dropping the check.
if (!only || "par_dst_short".includes(only)) {
  // The fixture is asked for too: the link loop empties its output directory
  // only when it runs the case, so a binary left by an earlier run would
  // otherwise answer for a fixture that is gone.
  const fixture = linkTests.includes("par_dst_short")
  const exe = path.join(buildDir, "link", "par_dst_short", "app")
  const run = fixture && fs.existsSync(exe) ? spawnSync(exe) : null
  const missing = fixture ? `no such binary: ${exe}` : "no such fixture: tests/link/par_dst_short"
  check(
    "link/par_dst_short: exits 1 with `parallelMapInto: dst has 2 elements and src has 3` on stderr",
    run !== null &&
      run.status === 1 &&
      String(run.stderr).includes("parallelMapInto: dst has 2 elements and src has 3") &&
      String(run.stdout).trim() === "before",
    run !== null ? `exit ${run.status}\nstdout: ${run.stdout}\nstderr: ${run.stderr}` : missing
  )
}

// What TLS 1.3 resumption saves the server (docs/security/tls.md,
// "Resumption"). `net_tls_resume_bench` runs 41 interleaved rounds of a full
// handshake, the same full handshake again and a resumed one, each on a
// server whose random and x25519 key are drawn fresh, and prints the medians
// of the server's own time per handshake on stderr; the link loop above pins
// its stdout, the counts, the bytes and a checksum folded from every
// session's traffic secret. Measured after its first review round, nine
// runs, eight of them: full 416-436 us, its byte-identical copy within 1.2%
// of it (the noise band), resumed 256-262 us, 0.60-0.62x the full handshake;
// the ninth, on a loaded machine, was slower in every arm alike (712 and
// 452 us, 0.63x). psk_dhe_ke still does
// the x25519 exchange and leaves out the certificate and the P-256 signature.
// On the wire, 854 bytes a full handshake against 637 a resumed one, both
// sides and the NewSessionTicket counted. The bound is the resumed median
// below 0.85x the smaller full one, far outside the band.
if (!only || "net_tls_resume_bench".includes(only)) {
  const fixture = linkTests.includes("net_tls_resume_bench")
  const exe = path.join(buildDir, "link", "net_tls_resume_bench", "app")
  const run = fixture && fs.existsSync(exe) ? spawnSync(exe, [], { encoding: "utf8" }) : null
  const missing = fixture ? `no such binary: ${exe}` : "no such fixture: tests/link/net_tls_resume_bench"
  const m =
    run === null ? null : /resume bench ns: full (\d+) copy (\d+) resumed (\d+)/.exec(String(run.stderr))
  const [full, copy, resumed] = m === null ? [0, 0, 0] : [Number(m[1]), Number(m[2]), Number(m[3])]
  check(
    "link/net_tls_resume_bench: a resumed handshake costs the server under 0.85x a full one",
    run !== null && run.status === 0 && m !== null && resumed > 0 && resumed < 0.85 * Math.min(full, copy),
    run !== null ? `exit ${run.status}\nstderr: ${run.stderr}` : missing
  )
}

// A `Channel<string>` send copies in time that grows with the string, not with
// the sender's arena. `thread_channel_string_many` sends a million strings it
// also keeps, so its arena grows with the sends: a send that asked whether the
// arena held the string walked and sorted every chunk of it, and the program
// took 46.9 s where it now takes 0.5 s. The bound is twenty times the second.
if (!only || "thread_channel_string_many".includes(only)) {
  const fixture = linkTests.includes("thread_channel_string_many")
  const exe = path.join(buildDir, "link", "thread_channel_string_many", "app")
  const started = Date.now()
  const run =
    fixture && fs.existsSync(exe) ? spawnSync(exe, [], { timeout: 120_000, killSignal: "SIGKILL" }) : null
  const ms = Date.now() - started
  const missing = fixture
    ? `no such binary: ${exe}`
    : "no such fixture: tests/link/thread_channel_string_many"
  check(
    "link/thread_channel_string_many: a million Channel<string> sends finish in under 10 s",
    run !== null && run.status === 0 && String(run.stdout) === "1000000 54792\n" && ms < 10_000,
    run !== null ? `exit ${run.status}, signal ${run.signal}, after ${ms} ms\nstdout: ${run.stdout}` : missing
  )
}

// `Http1Server` builds a slot's connection on the first accept into it, so a
// pool sized for a busy day costs little before its first connection.
// `tests/link/net_http1_server/startup.ts` builds a pool of 16,384 slots on no
// socket and prints the arena bytes it took, which the ceiling
// `HTTP1_SERVER_START_BYTES` in `tests/runtime-budgets.js` holds, and whether
// they fit in one chunk, without which `Arena.used()` measures nothing.
if (!only || "net_http1_server".includes(only) || "runtime-budget".includes(only)) {
  const dir = path.join(buildDir, "link", "net_http1_server.startup")
  fs.rmSync(dir, { recursive: true, force: true })
  fs.mkdirSync(dir, { recursive: true })
  const exe = path.join(dir, "app")
  const built = spawnSync(
    NISH,
    [path.join(root, "tests", "link", "net_http1_server", "startup.ts"), "-o", dir + path.sep, "--link", exe],
    { cwd: root, encoding: "utf8" }
  )
  if (check("net_http1_server: startup.ts links", built.status === 0, shown(built))) {
    const run = spawnSync(exe, [], { encoding: "utf8", timeout: 60_000, killSignal: "SIGKILL" })
    const [bytes, , chunk] = String(run.stdout).trim().split(" ")
    check(
      "net_http1_server: a 16,384-slot Http1Server takes at most HTTP1_SERVER_START_BYTES before its first connection",
      run.status === 0 && chunk === "yes" && Number(bytes) > 0 && Number(bytes) <= HTTP1_SERVER_START_BYTES,
      `ceiling ${HTTP1_SERVER_START_BYTES}\n${shown(run)}`
    )
  }
}

// `TlsTcpServer` and `Http1TlsServer` build a slot's TLS state, and the
// latter its connection, on the first accept into it too, and so does
// `Http2TlsServer` past slot 0.
// `tests/link/net_tls_record_tcp/startup.ts`,
// `tests/link/net_http1_server/tls-startup.ts` and
// `tests/link/net_http2_tls/startup.ts` build pools of 16,384 slots on no
// socket and print the bytes they took and whether they fit one chunk, which
// the ceilings `TLS_TCP_START_BYTES`, `HTTP1_TLS_SERVER_START_BYTES` and
// `HTTP2_TLS_SERVER_START_BYTES` hold.
for (const [unit, program, name, ceiling, ceilingName] of [
  ["net_tls_record_tcp", "startup.ts", "TlsTcpServer", TLS_TCP_START_BYTES, "TLS_TCP_START_BYTES"],
  [
    "net_http1_server",
    "tls-startup.ts",
    "Http1TlsServer",
    HTTP1_TLS_SERVER_START_BYTES,
    "HTTP1_TLS_SERVER_START_BYTES",
  ],
  [
    "net_http2_tls",
    "startup.ts",
    "Http2TlsServer",
    HTTP2_TLS_SERVER_START_BYTES,
    "HTTP2_TLS_SERVER_START_BYTES",
  ],
]) {
  if (only && !unit.includes(only) && !"runtime-budget".includes(only)) {
    continue
  }
  const dir = path.join(buildDir, "link", `${unit}.${program.replace(".ts", "")}`)
  fs.rmSync(dir, { recursive: true, force: true })
  fs.mkdirSync(dir, { recursive: true })
  const exe = path.join(dir, "app")
  const built = spawnSync(
    NISH,
    [path.join(root, "tests", "link", unit, program), "-o", dir + path.sep, "--link", exe],
    {
      cwd: root,
      encoding: "utf8",
    }
  )
  if (check(`${unit}: ${program} links`, built.status === 0, shown(built))) {
    const run = spawnSync(exe, [], { encoding: "utf8", timeout: 60_000, killSignal: "SIGKILL" })
    const [bytes, chunk] = String(run.stdout).trim().split(" ")
    check(
      `${unit}: a 16,384-slot ${name} takes at most ${ceilingName} before its first connection`,
      run.status === 0 && chunk === "yes" && Number(bytes) > 0 && Number(bytes) <= ceiling,
      `ceiling ${ceiling}\n${shown(run)}`
    )
  }
}

// `Http3Server` builds a slot's QUIC and HTTP/3 connections and its address on
// the first Initial accepted into it, so what a pool costs before its first
// connection is its per-slot tables. `tests/link/net_http3_server/startup.ts`
// builds a pool of 65,536 slots on no socket and prints the arena bytes it
